export const meta = {
  name: 'ship-feature',
  description: 'Detect stack → investigate → spec → build → quality gates → converge (spec vs code) → visual → adversarial review → docs, for a single feature across one or more repos',
  whenToUse: 'When a feature is well-scoped enough to implement end-to-end. Auto-detects the stack from the stack manifests and supports split backend+frontend repos. Pass {profile:"quick"} for one Converge round, one Fix round, maxFindings 4 and maxAgents 60; {maxAgents, maxFindings} set the per-run agent cap and the findings kept per review dimension. Pass {spec:"<ref>"} to execute an approved spec (folder name, legacy number, ticket key, or timestamp id); pass {repos:{backend,frontend}} for a polyrepo project. When the frontend stack declares e2e and its config exists, browser acceptance leaves an E2E regression test traced to the acceptance criteria ({e2e:false} skips it); with split repos and contract-sync installed, API drift is a gate. Saves its report to .ai/reports/ for /open-pr --report.',
  phases: [
    { title: 'Detect', detail: 'Identify stack(s) and repo layout', model: 'sonnet' },
    { title: 'Investigate', detail: 'Deep-read codebase + docs per repo', model: 'opus' },
    { title: 'Spec', detail: 'Decompose into ordered tasks and persist to .ai/specs', model: 'opus' },
    { title: 'Rules', detail: 'Load the business rules the spec cites, read-only', model: 'sonnet' },
    { title: 'Clarify', detail: 'Fresh-context clarity gate on an inline spec; unanswered questions keep it draft', model: 'opus' },
    { title: 'Prepare', detail: 'Leave a protected branch for a feature branch per repo and mark an approved spec in progress', model: 'haiku' },
    { title: 'Build', detail: 'Implement each task with the right specialist, tick progress', model: 'sonnet' },
    { title: 'Gates', detail: 'Run the detected quality tooling per repo, auto-fix until green', model: 'sonnet' },
    { title: 'Converge', detail: 'Audit code vs spec/tasks, append gap tasks, rebuild (max 2 rounds)', model: 'opus' },
    { title: 'Visual', detail: 'Playwright MCP visual tests: theming, UI, UX, responsive, a11y contrast', model: 'opus' },
    { title: 'Review', detail: 'Adversarial panel: dimensions x 2-vote verify', model: 'opus' },
    { title: 'Fix', detail: 'Fix confirmed findings, re-run gates, re-verify the fixed ones (max 2 rounds)', model: 'sonnet' },
    { title: 'Acceptance', detail: 'Trace the reported scenario end-to-end; confirm the original problem resolves; write the E2E regression test', model: 'opus' },
    { title: 'Docs', detail: 'Update affected docs to reflect shipped behavior', model: 'opus' },
    { title: 'TestPlan', detail: 'Write copy-paste manual QA steps for a human to verify', model: 'sonnet' },
    { title: 'Close', detail: 'Set the spec done and the backlog slice shipped when the run is shippable, fill the Traceability cells', model: 'haiku' },
    { title: 'Report', detail: 'Synthesize the result', model: 'opus' },
  ],
}

