function sameRequiresEntry(a, b) {
  if (typeof a === 'string' || typeof b === 'string') return a === b
  if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false
  return a.every((p) => b.includes(p))
}

// The requirement as Detect reads it: "needs <path>", or "needs <a> and one of <b>, <c>" for the list form.
function requiresDetectText(requires) {
  if (typeof requires === 'string') return `needs ${requires}`
  return `needs ${requires.map((e) => (Array.isArray(e) ? `one of ${e.join(', ')}` : e)).join(' and ')}`
}

// The devUrlFields of an execWrapper's running check; [] for a string check or none.
function devUrlFieldsOf(wrapper) {
  const check = wrapper && wrapper.requiresRunning
  return check && typeof check === 'object' && Array.isArray(check.devUrlFields) ? check.devUrlFields : []
}

// Stack keys whose execWrapper declares workdir: their marker may sit in a directory above the repo.
function workdirStacks() {
  return Object.keys(STACK_TRAITS).filter((k) => STACK_TRAITS[k].execWrapper && STACK_TRAITS[k].execWrapper.workdir)
}

// Detect prompt fragment asking for the exec-wrapper marker of every stack that declares one; '' when none does.
function execWrapperDetectLine() {
  const rules = Object.keys(STACK_TRAITS).filter((k) => STACK_TRAITS[k].execWrapper).map((k) => {
    const w = STACK_TRAITS[k].execWrapper
    return `${k}: marker ${w.when}${w.requiresRunning ? `, running check ${runningCheckText(w.requiresRunning)}` : ''}`
  })
  if (!rules.length) return ''
  const hostRules = Object.keys(STACK_TRAITS).filter((k) => devUrlFieldsOf(STACK_TRAITS[k].execWrapper).length).map((k) => `${k}: ${devUrlFieldsOf(STACK_TRAITS[k].execWrapper).join(', ')}`)
  const hosts = hostRules.length
    ? ` For a manifest whose running check declares devUrlFields (${hostRules.join('; ')}; a discovered manifest names its own), when the check passes set reportedDevHosts to the hostname of every URL at those dotted paths of the same JSON output (a field holds a URL or a list of URLs; the hostname only, without scheme, port or path); omit reportedDevHosts otherwise.`
    : ''
  const line = ` EXEC WRAPPER — for a repo whose stack manifest declares execWrapper (${rules.join('; ')}; a discovered manifest names its own), set execWrapper {present} to whether the marker file exists in that repo and, when present and the manifest declares a running check, {running} to whether that check passes (run it in that repo); omit running for a wrapper without a running check.${hosts}`
  const nested = workdirStacks()
  if (!nested.length) return line
  return `${line} For a manifest whose execWrapper declares workdir (${nested.join(', ')}; a discovered manifest declares its own), the marker also counts as present when it is in an ancestor directory of the repo: check each ancestor, nearest first, up to the filesystem root, only with the Glob tool on the literal absolute path <ancestor>/<marker>, never reading the file, and set {dir} to the repo's path relative to the directory that holds the marker ("." when the marker is in the repo itself, plain relative path characters only); omit dir for any other wrapper.`
}

// The narrow exception to the outside-the-project rule that the workdir marker search needs; '' without workdir.
function workdirOutsideRule() {
  return workdirStacks().length ? ' The one other check allowed outside the project is the EXEC WRAPPER ancestor marker search below: a Glob of that literal marker path, nothing else.' : ''
}

// Gates the greenfield scaffold installs: the stack's gates minus those it skips; none for an untrusted overlay.
function scaffoldGatesFor(stack) {
  if (!hasOwn(STACKS, stack) || isUntrustedStack(stack)) return []
  const skip = traitsFor(stack).scaffoldSkipGates || []
  return STACKS[stack].gates.filter((g) => !skip.includes(g.name))
}

// Command that exports a backend's route list for contract-sync; '' when the stack has none or is untrusted.
function routeListCommandFor(stack) {
  return traitsFor(stack).routeListCommand || ''
}

/**
 * The add-on that ships a stack: a first-party key through FIRST_PARTY_FILES, an overlay key through its source.
 * @param {string} stack Stack key.
 * @returns {{ dir: string|null, plugin: string|null, source: string|null }} dir: the add-on directory (file-copy
 *   installs stage its files under .claude/<kind>/<dir>/); plugin: the plugin name; source: the overlay's manifest source.
 */
function addonFor(stack) {
  for (const [dir, keys] of Object.entries(FIRST_PARTY_FILES)) {
    if (keys.includes(stack)) return { dir, plugin: FIRST_PARTY_PLUGINS.find((p) => p === `sdd-kit-${dir}`) || null, source: null }
  }
  if (!hasOwn(OVERLAY_META, stack)) return { dir: null, plugin: null, source: null }
  const source = OVERLAY_META[stack].source
  const plugin = /^plugin:([^@]+)/.exec(source)
  return { dir: null, plugin: plugin ? plugin[1] : null, source }
}

/**
 * Where a backend stack's contract-sync template lives, from its manifest's contractSync.template (a path
 * relative to the add-on root). The add-on is named explicitly: a workflow agent gets no placeholder
 * substitution and runs from the core plugin, so it must look the add-on's install directory up itself.
 * @param {string} stack Stack key.
 * @returns {string} Prompt text naming every location, or '' when the stack declares no template or is untrusted.
 * @example contractTemplateFor('acme') // first-party add-on directory "acme", plugin "sdd-kit-acme"
 * // "templates/contract-sync in the sdd-kit-acme plugin's install directory (plugin mode: ...), or .claude/templates/acme/contract-sync in file-copy installs"
 */
function contractTemplateFor(stack) {
  const template = traitsFor(stack).contractTemplate
  if (!template) return ''
  const { dir, plugin, source } = addonFor(stack)
  const locations = []
  if (plugin) locations.push(`${template} in the ${plugin} plugin's install directory (plugin mode: its installPath in \`claude plugin list --json\` or ~/.claude/plugins/installed_plugins.json, or its --plugin-dir path)`)
  if (dir) locations.push(`.claude/templates/${dir}/${template.replace(/^templates\//, '')} in file-copy installs`)
  if (!locations.length) locations.push(`${template} in the add-on that provides ${source || `the ${stack} stack`}`)
  return locations.join(', or ')
}

function isContractConsumer(stack) {
  return !!(hasOwn(STACK_TRAITS, stack) && STACK_TRAITS[stack].contractConsumer)
}

// Extras whose fields carry commands (scaffold, ci, e2e, migrations, audit, packageManagers): empty for an untrusted overlay.
const extrasFor = (stack) => (hasOwn(STACK_EXTRAS, stack) && !isUntrustedStack(stack) ? STACK_EXTRAS[stack] : {})

/**
 * The manifest's exploration rows for the stacks of the given repos, as prompt text for a code-explorer
 * step. Rows render as "- <what>: <where>" under one heading per stack (deduplicated); a stack with no
 * rows, and an untrusted overlay, adds nothing.
 * @param {Array<{stack: string, role?: string}>} repos
 * @returns {string} empty, or text that starts with a blank line so it can be appended to a prompt
 */
function exploreText(repos) {
  const seen = []
  const groups = []
  for (const repo of repos || []) {
    if (!repo || seen.includes(repo.stack)) continue
    seen.push(repo.stack)
    const rows = extrasFor(repo.stack).explore || []
    const roots = extrasFor(repo.stack).sourceDirs || []
    const scope = roots.length ? `\nSearch under ${roots.join(' ')} first; vendored and framework code (core, contrib, vendor) is read-only reference, so do not sweep it with repo-wide globs.` : ''
    if (rows.length) groups.push(`Where ${repo.stack} keeps things (${repo.role || 'repo'} repo):${scope}\n${rows.map((r) => `- ${r.what}: ${r.where}`).join('\n')}`)
  }
  return groups.length ? `\n\n${groups.join('\n\n')}` : ''
}

// Skill names the manifest lists for a stack: { conventions, testing, scaffold } (absent groups are empty).
// Empty for an untrusted overlay (OD-17a): its steps run as the default agent with no stack skills.
function skillsFor(stack) {
  const s = (hasOwn(STACK_EXTRAS, stack) && !isUntrustedStack(stack) ? STACK_EXTRAS[stack] : {}).skills || {}
  return { conventions: s.conventions || [], testing: s.testing || [], scaffold: s.scaffold || [] }
}

// Every distinct skill name the manifest lists for a stack, conventions first.
function skillNamesFor(stack) {
  const s = skillsFor(stack)
  return Array.from(new Set([...s.conventions, ...s.testing, ...s.scaffold]))
}

// Skills for a phase that only writes tests: the manifest's testing group, else its conventions group.
function testSkillNamesFor(stack) {
  const s = skillsFor(stack)
  return s.testing.length ? s.testing : s.conventions
}

// Source directories the debug scan greps, as one prompt fragment; the repo's own source roots when the
// manifest names none or is untrusted (the directories are pasted into a command line).
function sourceDirsFor(stack) {
  const dirs = extrasFor(stack).sourceDirs || []
  return dirs.length ? dirs.join(' ') : "the repo's source directories"
}

/**
 * Package managers a stack's manifest declares, in manifest order; the last entry is the default
 * (no lockfile). Empty when the stack declares none or is untrusted.
 * @param {string} stack Stack key.
 * @returns {{ name: string, lockfiles: string[], run: string, exec?: string }[]}
 */
function packageManagersFor(stack) {
  return extrasFor(stack).packageManagers || []
}

// The package manager a repo uses: the one Detect recorded, else its stack's default; null when the stack declares none.
function packageManagerFor(repo, fallbackToDefault) {
  const pms = packageManagersFor(repo.stack)
  const found = pms.find((p) => p.name === repo.packageManager)
  if (found) return found
  return fallbackToDefault === false ? null : pms[pms.length - 1] || null
}

// Fills <pm>, <pmx> and <pm-audit> in a manifest command; unchanged when there is no package manager.
function fillPackageManager(command, pm) {
  return pm ? command.split('<pm-audit>').join(pm.audit || `${pm.run} audit`).split('<pmx>').join(pm.exec || pm.run).split('<pm>').join(pm.run) : command
}

// Prompt sentence telling an agent how <pm>/<pmx> expand for a stack; '' when the stack declares no package managers.
function packageManagerLine(stack) {
  const pms = packageManagersFor(stack)
  if (!pms.length) return ''
  return `Use the package manager the repo uses (its lockfile; default ${pms[pms.length - 1].name}) for every command: <pm> is ${pms.map((p) => p.run).join(', ')}, and <pmx> is ${pms.map((p) => p.exec || p.run).join(', ')} respectively.`
}

// Scaffold block of the manifest ({ command, tooling[] }); empty when the stack declares none or is untrusted.
function scaffoldFor(stack) {
  const sc = extrasFor(stack).scaffold || {}
  return { command: sc.command || '', tooling: sc.tooling || [] }
}

// CI block of the manifest ({ services[], setup[] }); empty when the stack declares none or is untrusted.
function ciFor(stack) {
  const ci = extrasFor(stack).ci || {}
  return { services: ci.services || [], setup: ci.setup || [] }
}

// E2E block of the manifest ({ configGlob, file, run, convention, seed }); null when the stack declares none or is untrusted.
function e2eFor(stack) {
  return extrasFor(stack).e2e || null
}

// What a backend stack adds to a frontend's E2E step ({ convention, seed }); null when it declares nothing or is untrusted.
function e2eBackendFor(stack) {
  return extrasFor(stack).e2eBackend || null
}

// Regression test file for the E2E step from the manifest's e2e.file pattern ({slug} filled in); '' when the manifest names none.
function e2eFileFor(stack, slug) {
  const e2e = e2eFor(stack)
  if (!e2e || !e2e.file) return ''
  return e2e.file.split('{slug}').join(slug || '<short-feature-slug>')
}

const NO_E2E_DECLARED = 'not run (stack declares no e2e)'
const NO_APP_URL = 'not run (no reachable app URL)'

// A skipped step reports status 'skip' with its reason. Skips are informational: they never change the recommendation.
function skipResult(reason) {
  return { status: 'skip', ran: false, written: false, details: reason }
}

// Why the E2E step does not run for a frontend repo, as a skip result; null when it should run.
// `requested` is the explicit e2e argument (true, false or null), `configFound` whether a file matches the manifest's configGlob.
function e2eSkipFor(frontend, requested, configFound) {
  if (requested === false) return skipResult('skipped — e2e:false')
  if (frontend && isUntrustedStack(frontend.stack)) return skipResult(NOT_RUN_UNTRUSTED)
  const e2e = frontend ? e2eFor(frontend.stack) : null
  if (!e2e) return skipResult(NO_E2E_DECLARED)
  if (requested === true || configFound) return null
  return skipResult(`skipped — no ${e2e.configGlob} in the repo (pass e2e:true to add one)`)
}

// Detect prompt fragment: which file proves a repo has e2e set up, per stack, from the manifests.
function e2eGlobsLine() {
  const rows = STACK_KEYS.filter((k) => e2eFor(k)).map((k) => `${k}: ${e2eFor(k).configGlob}`)
  return rows.length ? `e2eConfig=true when the repo has a file matching its stack's e2e config glob (${rows.join('; ')})` : ''
}

// Browser URL: the url argument, else the frontend repo's devUrl, else any repo's devUrl, else ''.
// A repo's own devUrl (from Detect) wins over its manifest's default. Detect's value is used only when it
// passes isDevUrl, and a manifest's default only when the manifest is first-party or trusted. The url argument
// may also use a host reported by the repo it serves: the first frontend repo, else the first repo.
function resolveDevUrl(hint, repos) {
  const list = repos || []
  const served = list.find((r) => isFrontendRepo(r)) || list[0]
  const given = runUrlHint(hint, served && served.reportedDevHosts)
  if (given) return given
  const front = list.find((r) => isFrontendRepo(r) && repoDevUrl(r))
  const any = front || list.find((r) => repoDevUrl(r))
  return any ? repoDevUrl(any) : ''
}

let urlHintLogged = false

// The run-level url argument when it passes isDevUrl for the hosts of the repo it serves; otherwise null, with
// one log line per run.
function runUrlHint(hint, repoHosts) {
  if (!hint) return null
  if (isDevUrl(hint, repoHosts)) return hint
  if (!urlHintLogged) {
    urlHintLogged = true
    log(`url argument is not a local dev URL — ignored. Fix: pass an http(s) URL on ${DEV_URL_HOST_TEXT}`)
  }
  return null
}

// A repo's own dev URL: Detect's value when it passes isDevUrl with the repo's reported hosts, else its
// first-party or trusted manifest's default when that passes too. An approved manifest is still text the user
// wrote, so its devUrl is never trusted to point the browser phases at a host outside the dev-URL rule.
function repoDevUrl(r) {
  const manifestUrl = (hasOwn(STACKS, r.stack) && !isUntrustedStack(r.stack) && !r.declinedStack && STACKS[r.stack].devUrl) || ''
  const hosts = r.reportedDevHosts
  return (isDevUrl(r.devUrl, hosts) ? r.devUrl : '') || (isDevUrl(manifestUrl, hosts) ? manifestUrl : '')
}

/**
 * args.repos in either accepted form as one list of { path, role?, url? }: an array of such entries (or of
 * plain paths), or the older { backend, frontend } object of paths. More than one backend is an error.
 * @param {unknown} hints args.repos
 * @returns {{ entries: { path: string, role?: string, url?: string }[], error: string }}
 * @example normalizeRepoHints({ backend: '../api', frontend: '../web' }).entries // [{ path: '../api', role: 'backend' }, { path: '../web', role: 'frontend' }]
 */
function normalizeRepoHints(hints) {
  let entries = []
  if (Array.isArray(hints)) {
    entries = hints.map((h) => (typeof h === 'string' ? { path: h } : h)).filter((h) => h && typeof h === 'object' && typeof h.path === 'string')
  } else if (hints && typeof hints === 'object') {
    entries = Object.keys(hints).filter((k) => typeof hints[k] === 'string').map((k) => ({ path: hints[k], role: k }))
  }
  const backends = entries.filter((e) => e.role === 'backend')
  if (backends.length > 1) {
    return { entries, error: `repos lists ${backends.length} backends (${backends.map((b) => b.path).join(', ')}); a run takes zero or one. Fix: run once per backend, or mark the others with another role.` }
  }
  return { entries, error: '' }
}

/**
 * One dev URL per frontend repo: the matching args.repos entry's url, else (with a single frontend) the url
 * argument, else the repo's own devUrl, else its manifest default. Two frontends on the same URL are refused.
 * @param {object[]} repos detected repos
 * @param {{ path: string, url?: string }[]} entries normalizeRepoHints entries
 * @param {string|null} hint the url argument
 * @returns {{ targets: { repo: object, url: string }[], error: string }}
 */
function frontendTargets(repos, entries, hint) {
  const same = (a, b) => String(a).replace(/^\.\//, '').replace(/\/+$/, '') === String(b).replace(/^\.\//, '').replace(/\/+$/, '')
  const fronts = (repos || []).filter(isFrontendRepo)
  const given = runUrlHint(hint, fronts.length === 1 ? fronts[0].reportedDevHosts : undefined)
  const targets = []
  for (const repo of fronts) {
    const entry = (entries || []).find((e) => same(e.path, repo.path))
    if (entry && entry.url !== undefined && !isDevUrl(entry.url, repo.reportedDevHosts)) {
      return { targets, error: `The url for ${repo.path} is not a local development URL. Fix: pass http://localhost:<port> (or another local host) as that entry's url.` }
    }
    targets.push({ repo, url: (entry && entry.url) || (fronts.length === 1 && given) || repoDevUrl(repo) })
  }
  const seen = new Map()
  for (const t of targets) {
    if (!t.url) continue
    if (seen.has(t.url)) {
      return { targets, error: `Frontends ${seen.get(t.url)} and ${t.repo.path} resolve to the same url ${t.url}. Fix: pass a distinct url for each in args.repos, or run them separately.` }
    }
    seen.set(t.url, t.repo.path)
  }
  return { targets, error: '' }
}

// Prompt fragment naming each frontend and its URL when a run has several; '' for zero or one.
function frontendPassesLine(targets) {
  if (!targets || targets.length < 2) return ''
  return targets.map((t) => `${t.repo.path} (${t.repo.stack}) at ${t.url || 'a URL you discover'}`).join('; ')
}

/**
 * The URL a repo's build-gate guard checks: its own frontend target's URL, else the run's URL. With several
 * frontends each gate agent must watch its own dev server, not the first frontend's.
 * @param {object} repo a detected repo
 * @param {{ repo: object, url: string }[]} targets frontendTargets(...).targets
 * @param {string} fallback the run-wide URL (or a placeholder)
 * @returns {string}
 */
function gateDevUrlFor(repo, targets, fallback) {
  const target = repo && (targets || []).find((t) => t.repo.path === repo.path)
  return (target && target.url) || fallback
}

/**
 * Splits changed files across frontend targets. A file belongs to the repo whose path is its longest prefix
 * ("." claims any path no other repo does); files of a non-frontend repo are dropped. A file no repo claims
 * (an absolute or repo-relative path) is given to every target, so an ambiguous change is checked, not skipped.
 * @param {{ repo: object, url: string }[]} targets frontendTargets(...).targets
 * @param {string[]} files changed file paths, relative to the current directory
 * @param {object[]} [repos] every detected repo, so a backend's files are not mistaken for unclaimed ones
 * @returns {{ repo: object, url: string, files: string[] }[]} the targets in order, each with its files
 * @example frontendChanges([{ repo: { path: '../web' } }, { repo: { path: '../admin' } }], ['../web/app/page.tsx'])
 *   // [{ ..., files: ['../web/app/page.tsx'] }, { ..., files: [] }]
 */
function frontendChanges(targets, files, repos) {
  const norm = (p) => String(p || '').replace(/^(\.\/)+/, '').replace(/\/+$/, '')
  const list = targets || []
  const roots = list.map((t) => norm(t.repo.path))
    .concat((repos || []).filter((r) => !list.some((t) => norm(t.repo.path) === norm(r.path))).map((r) => norm(r.path)))
  const owned = list.map(() => [])
  const shared = []
  for (const file of files || []) {
    const f = norm(file)
    let best = -1
    let bestLength = -1
    roots.forEach((root, i) => {
      const anywhere = root === '.' || root === ''
      const length = anywhere ? 0 : root.length
      if ((anywhere || f === root || f.startsWith(`${root}/`)) && length > bestLength) {
        best = i
        bestLength = length
      }
    })
    if (best < 0) shared.push(file)
    else if (best < list.length) owned[best].push(file)
  }
  return list.map((t, i) => ({ ...t, files: owned[i].concat(shared) }))
}

/**
 * Runs one browser pass per target, one after another. Every pass drives the session's single browser
 * (one Playwright MCP server, or Claude in Chrome), so concurrent passes would race on its page, viewport
 * and console log.
 * @param {object[]} targets the frontends to visit, in order
 * @param {(target: object) => Promise<object|null>} runPass starts the pass for one target
 * @returns {Promise<(object|null)[]>} each pass's result, in target order
 */
async function sequentialPasses(targets, runPass) {
  const results = []
  for (const target of targets || []) results.push(await runPass(target))
  return results
}

/**
 * Merges per-frontend acceptance results into one: resolved only when every pass returned and resolved;
 * steps, unchanged behaviors and reasons are tagged with their repo path; passes lists each repo's outcome.
 * @param {{ repo: object, url: string }[]} targets the frontends, in pass order
 * @param {(object|null)[]} results each pass's ACCEPTANCE_SCHEMA result (null when the pass did not return)
 * @returns {object} an ACCEPTANCE_SCHEMA result with an extra passes array
 */
function mergeAcceptancePasses(targets, results) {
  const tag = (i, text) => `[${targets[i].repo.path}] ${text}`
  const merged = {
    resolved: results.length > 0 && results.every((r) => !!(r && r.resolved)),
    steps: results.flatMap((r, i) => ((r && r.steps) || []).map((s) => ({ ...s, step: tag(i, s.step) }))),
    brokenLinks: Array.from(new Set(results.flatMap((r) => (r && r.brokenLinks) || []))),
    reason: results.map((r, i) => (!r ? tag(i, 'the acceptance pass did not return') : r.reason ? tag(i, r.reason) : '')).filter(Boolean).join(' '),
    passes: targets.map((t, i) => ({ repo: t.repo.path, url: t.url, resolved: !!(results[i] && results[i].resolved) })),
  }
  if (results.some((r) => r && Array.isArray(r.unchanged))) {
    merged.unchanged = results.flatMap((r, i) => ((r && r.unchanged) || []).map((u) => ({ ...u, behavior: tag(i, u.behavior) })))
  }
  return merged
}

// Prompt fragment for the app URL: the URL, or the instruction to discover and probe one.
function appUrlLine(devUrl) {
  return devUrl || `none declared — discover the dev server URL (the repo's dev script, its config) and probe it; if nothing responds, report the browser check as ${NO_APP_URL}`
}

// Copy-paste manual QA the human runs to confirm a change by hand. Every step names the ids it verifies.
const TEST_PLAN_SCHEMA = {
  type: 'object',
  required: ['steps'],
  properties: {
    path: { type: 'string' },
    preconditions: { type: 'array', items: { type: 'string' } },
    testData: { type: 'array', items: { type: 'string' } },
    steps: {
      type: 'array',
      items: {
        type: 'object',
        required: ['action', 'expected'],
        properties: {
          action: { type: 'string' },
          expected: { type: 'string' },
          covers: { type: 'array', items: { type: 'string' } },
        },
      },
    },
    mustNotChange: { type: 'array', items: { type: 'string' } },
    rollback: { type: 'string' },
  },
}

const TEST_PLAN_SECTIONS = ['Preconditions', 'Test data', 'Steps', 'Must NOT change checks', 'Rollback']

// Lowercase, hyphenated file-name part of at most five words; 'change' when the text has no letters or digits.
function testPlanSlug(text) {
  const words = String(text || '').toLowerCase().match(/[a-z0-9]+/g) || []
  return words.slice(0, 5).join('-') || 'change'
}

// Where the manual test plan goes: beside the spec when there is a (plainly named) spec folder, else beside the run report.
// The timestamp is a shell substitution the writer agent resolves, because workflow scripts cannot read the clock.
function testPlanPath(specFolder, slug) {
  const folder = typeof specFolder === 'string' ? specFolder.replace(/\/+$/, '') : ''
  if (folder && /^[A-Za-z0-9._][A-Za-z0-9._\/-]*$/.test(folder) && !folder.split('/').includes('..')) return `${folder}/manual-test.md`
  return `.ai/reports/test-plan-${testPlanSlug(slug)}-$(date +%Y%m%d-%H%M).md`
}

/**
 * A plan path an agent returned, when it is plain enough to name in a later prompt: a .md file of path
 * characters only, with no ".." segment and no shell substitution left in it.
 * @param {unknown} p
 * @returns {string} the path, or '' when it is not usable
 */
function plainPlanPath(p) {
  const text = typeof p === 'string' ? p.trim() : ''
  return /^\/?[A-Za-z0-9._][A-Za-z0-9._\/-]*\.md$/.test(text) && !text.split('/').includes('..') ? text : ''
}

/**
 * The one TestPlan prompt of ship-feature, fix-bug and greenfield-build.
 * @param {object} o
 * @param {string} o.subject what is verified, e.g. "this feature"
 * @param {string} [o.specFolder] spec folder; the plan is written to its manual-test.md
 * @param {string} [o.slug] words naming the change, used for the file name when there is no spec folder
 * @param {string} [o.context] prompt lines describing the change (repos, entry points, URLs, changed files)
 * @param {string[]} [o.ids] AC, MNC, NFR or bug ids (with their text) the plan must cover
 * @param {{id: (string|number), title: string}[]} [o.manualTasks] Manual: tasks, each given its own step
 * @param {string} [o.extra] extra instructions appended after the file location
 * @param {string} [o.path] the file an earlier round already wrote; it replaces the computed location so a
 *   rewrite updates that file instead of resolving a new timestamp (see plainPlanPath)
 * @returns {{path: string, prompt: string}}
 */
function testPlanPrompt({ subject, specFolder, slug, context = '', ids = [], manualTasks = [], extra = '', path = '' }) {
  const planPath = plainPlanPath(path) || testPlanPath(specFolder, slug)
  const hasSpec = planPath.endsWith('/manual-test.md')
  const manual = manualTasks.length
    ? `Manual tasks (never built; a person runs them): ${JSON.stringify(manualTasks.map((t) => `${t.id}. ${t.title}`))}. Give each its own step, and end the plan with a "Tick after the manual steps pass" line naming the task ids ${manualTasks.map((t) => t.id).join(', ')}${hasSpec ? ` (their "- [ ] N." lines in ${specFolder}/tasks.md; leave them unchecked yourself)` : ''}.\n`
    : ''
  const prompt = `Write a concrete, copy-paste manual test plan a human runs to verify ${subject} by hand — no AI/agent jargon, real values they can paste. Verify each step against the actual implementation; do not invent endpoints or URLs.
${context ? `${context}\n` : ''}${manual}The plan has these sections, in this order: ${TEST_PLAN_SECTIONS.map((x) => `"${x}"`).join(', ')}. Each step is a precise action (exact URL to open / command to run / button to click with real example data) and the exact expected result (status code, redirect target, on-screen text), and carries a tag naming the id it verifies, for example "[AC-2]", "[MNC-1]", "[NFR-1]" or "[BUG-1]". Cover the happy path AND the originally-reported failing case (it must now pass). Under "Must NOT change checks" give each behavior that must stay identical its own check. Under "Rollback" say how to undo the change; write "none needed" when it is not risky. A section with nothing to say reads "none"; never leave a heading empty.${ids.length ? ` Give each of these a step, or point at the automated test that proves it: ${JSON.stringify(ids)}.` : ''}${extra ? ` ${extra}` : ''}

${hasSpec ? `If "${planPath}" already exists, update it in place instead of rewriting it: keep every step a person already ticked ("- [x]") with its tick, keep their notes, and change only the steps the current run affects.\n` : ''}Write the plan to "${planPath}" as markdown (lowercase filename, human-authored tone, no AI-marker comments${hasSpec ? '' : planPath.includes('$(date') ? '; resolve the $(date ...) part of the name in the shell and create .ai/reports first' : '; it already exists, so update it in place'}). Set path to that file.`
  return { path: planPath, prompt }
}

const COVERAGE_ID = /\b(?:(?:AC|MNC|NFR|BUG|BR)-\d+|SLICE)\b/gi

/**
 * The ids (AC-1, MNC-2, NFR-1, BUG-1, BR-1, SLICE) named in a list of strings, upper-cased, first occurrence kept.
 * @param {(string|number)[]} items criterion texts such as "AC-1: ..." or bare ids
 * @returns {string[]}
 */
function coverageIds(items) {
  const found = []
  for (const item of Array.isArray(items) ? items : []) {
    for (const m of String(item).match(COVERAGE_ID) || []) if (!found.includes(m.toUpperCase())) found.push(m.toUpperCase())
  }
  return found
}

// Markdown a spec may wrap around a leading criterion id: list markers, bold or italic, as in "- **AC-2**: ...".
const CRITERION_LEAD = /^[\s>*_-]*((?:AC|MNC|NFR|BUG|BR)-\d+|SLICE)[*_]*(?=[\s:(]|$)/i

/**
 * The id a criterion text starts with, upper-cased, or '' when it starts with none. Ids named later in the
 * text (a cited rule, a reference to another criterion) are not the criterion's id.
 * @param {string|number} text
 * @returns {string}
 * @example leadingId('**AC-2** (BR-31): totals round down')  // 'AC-2'
 * @example leadingId('see AC-2')                            // ''
 */
function leadingId(text) {
  const m = CRITERION_LEAD.exec(String(text == null ? '' : text))
  return m ? m[1].toUpperCase() : ''
}

/**
 * The ids of a run's criteria: the leading id of each text, first occurrence kept.
 * @param {(string|number)[]} items criterion texts such as "AC-1: ..." or bare ids
 * @returns {string[]}
 */
function criterionIds(items) {
  const found = []
  for (const item of Array.isArray(items) ? items : []) {
    const id = leadingId(item)
    if (id && !found.includes(id)) found.push(id)
  }
  return found
}

/**
 * The full text of the criterion with the given id, matched on its leading id, so a bold or listed
 * criterion ("**AC-1**: ...") is found as well as a plain one.
 * @param {string} id  e.g. "AC-1"
 * @param {(string|number)[]} texts criterion texts
 * @returns {string|undefined}
 */
function criterionText(id, texts) {
  const want = String(id || '').trim().toUpperCase()
  return want ? (Array.isArray(texts) ? texts : []).map(String).find((t) => leadingId(t) === want) : undefined
}

// A step proves an id only through a tag: "[AC-2]", "[AC-2, MNC-1]", or a trailing "(AC-2, MNC-1)" id list.
const STEP_TAG = /\[([^\]]*)\]|\(((?:\s*(?:(?:AC|MNC|NFR|BUG|BR)-\d+|SLICE)\s*,?)+)\)\s*$/gi

/**
 * The ids a plan step or check text tags. A bare mention ("unlike AC-3") is not a tag.
 * @param {string} text
 * @returns {string[]}
 */
function taggedIds(text) {
  const found = []
  for (const m of String(text || '').matchAll(STEP_TAG)) {
    const inner = m[1] !== undefined ? m[1] : m[2]
    const ids = coverageIds([inner])
    // A bracket holds tags only: "[see AC-3 later]" is prose, not a tag.
    if (!ids.length || inner.replace(COVERAGE_ID, '').replace(/[\s,]/g, '') !== '') continue
    for (const id of ids) if (!found.includes(id)) found.push(id)
  }
  return found
}

const TEST_FILE_REF = /[\w./-]+\.(?!md\b)[a-z]{1,5}\b/i

/**
 * The ids whose Traceability row names a test file in its "Verified by" cell. Manual steps
 * ("manual-test.md#step-2") and empty cells do not count.
 * @param {string[]} rows rows of the tasks.md Traceability table: | ID | Criterion | Verified by | Kind | Task |
 * @param {string[]} [known] files this run built or changed; when given, a row counts only if it names one of them,
 *   because a planned name in a spec is not proof that the file exists
 * @returns {string[]}
 */
function tracedTestIds(rows, known) {
  const knownFiles = Array.isArray(known) ? known.map((f) => String(f).replace(/^\.\//, '')) : null
  const names = (cell) => (cell.match(new RegExp(TEST_FILE_REF.source, 'gi')) || []).map((r) => r.replace(/^\.\//, ''))
  const exists = (cell) => !knownFiles || names(cell).some((r) => knownFiles.some((f) => f === r || f.endsWith(`/${r}`)))
  const ids = []
  for (const row of Array.isArray(rows) ? rows : []) {
    const cells = String(row).split('|').map((c) => c.trim())
    if (cells[0] === '') cells.shift()
    const [id, , verifiedBy = ''] = cells
    if (!coverageIds([id]).length || /manual-test\.md/i.test(verifiedBy) || !TEST_FILE_REF.test(verifiedBy) || !exists(verifiedBy)) continue
    for (const found of coverageIds([id])) if (!ids.includes(found)) ids.push(found)
  }
  return ids
}

/**
 * The ids a test plan leaves without proof: not named by an automated test (`tested`) and not carried by any
 * plan step (covers list or an "[ID]" tag in its action or expected text) or by a "Must NOT change" check that
 * starts with or tags the id. An id only mentioned in passing proves nothing.
 * @param {{steps?: {action?: string, expected?: string, covers?: string[]}[], mustNotChange?: string[]}|null} plan
 * @param {(string|number)[]} ids criteria of the run, with or without their text; each counts by its leading id
 * @param {(string|number)[]} [tested] ids with an automated test or build result
 * @returns {string[]}
 */
function testPlanMissing(plan, ids, tested = []) {
  const proven = new Set(coverageIds(tested))
  for (const step of (plan && Array.isArray(plan.steps) ? plan.steps : [])) {
    for (const id of [...coverageIds(Array.isArray(step.covers) ? step.covers : []), ...taggedIds(step.action), ...taggedIds(step.expected)]) proven.add(id)
  }
  for (const check of (plan && Array.isArray(plan.mustNotChange) ? plan.mustNotChange : [])) {
    for (const id of [leadingId(check), ...taggedIds(check)].filter(Boolean)) proven.add(id)
  }
  return criterionIds(ids).filter((id) => !proven.has(id))
}

/**
 * Checks the plan against the run's ids in script. Ids with neither an automated test nor a tagged step go
 * back to the plan writer once; whatever is still missing after that is returned as `missing`.
 * @param {object} o
 * @param {object|null} o.plan the plan the writer returned
 * @param {(string|number)[]} o.ids
 * @param {(string|number)[]} [o.tested]
 * @param {(missing: string[]) => Promise<object|null>} o.rewrite asks the writer to add steps for the missing ids; returns the new plan
 * @returns {Promise<{plan: object|null, missing: string[], repaired: boolean}>}
 */
async function checkTestPlanCoverage({ plan, ids, tested = [], rewrite }) {
  const missing = testPlanMissing(plan, ids, tested)
  if (!plan || !missing.length) return { plan, missing, repaired: false }
  const next = await rewrite(missing)
  if (!next) return { plan, missing, repaired: false }
  return { plan: next, missing: testPlanMissing(next, ids, tested), repaired: true }
}

/**
 * The shared TestPlan step: writes the plan, checks its coverage in script, and sends the ids without proof
 * back to the writer once. The rewrite names the file the first round wrote, so it updates that file
 * instead of creating a second one with a new timestamp.
 * @param {object} o
 * @param {object} o.request the testPlanPrompt options (subject, specFolder, slug, context, ids, manualTasks, extra)
 * @param {(string|number)[]} [o.tested] ids an automated test or build result proves
 * @param {(prompt: string) => Promise<object|null>} o.write runs the plan writer agent on a prompt
 * @returns {Promise<{plan: object|null, missing: string[], repaired: boolean}>}
 */
async function writeCheckedTestPlan({ request, tested = [], write }) {
  const first = await write(testPlanPrompt(request).prompt)
  return checkTestPlanCoverage({
    plan: first,
    ids: request.ids || [],
    tested,
    rewrite: (missing) => {
      const again = testPlanPrompt({ ...request, path: plainPlanPath(first && first.path) || request.path || '' })
      return write(`${again.prompt} The previous plan has no tagged step for ${missing.join(', ')}: rewrite the same file with a step tagged for each of them.`)
    },
  })
}

/**
 * The ledger entry of the test-plan check.
 * @param {string[]} missing ids still without proof after the repair round
 * @param {boolean} planWritten whether a plan came back at all
 * @returns {{check: string, status: string, reason: string}}
 */
function testPlanAssurance(missing, planWritten = true) {
  if (!planWritten) return assure('test-plan', 'unavailable', 'the plan writer returned nothing')
  return missing.length ? assure('test-plan', 'fail', `no test or plan step for ${missing.join(', ')}`) : assure('test-plan', 'pass')
}

// Renders the Detect-phase catalog straight from the registry so the detector
// agent is told about every stack without any stack prose living in the prompt.
function stackCatalog() {
  const known = STACK_KEYS.filter((k) => k !== 'other').map((k) => {
    const s = STACKS[k]
    const extras = hasOwn(STACK_EXTRAS, k) ? STACK_EXTRAS[k] : {}
    const skipRules = (extras.gates || {})
    const gates = s.gates.length
      ? s.gates.map((g) => `{${g.name}: ${g.command}${skipRules[g.name] && skipRules[g.name].unless ? ` — skip when any of ${skipRules[g.name].unless.join(', ')} exists` : ''}}`).join(', ')
      : '(whatever lint/test tooling exists)'
    const pms = (extras.packageManagers || []).map((p) => `${p.lockfiles.join(' or ')} → packageManager ${p.name} (<pm> = ${p.run}, <pmx> = ${p.exec || p.run})`)
    const pmLine = pms.length ? ` package managers (record packageManager from the lockfile; no lockfile → ${extras.packageManagers[extras.packageManagers.length - 1].name}; write gateCommands with <pm>/<pmx> replaced by the real commands): ${pms.join('; ')}.` : ''
    return `- ${k} — detect: ${s.detect}. specialistAgent: ${s.agent}. conventions: ${s.conventions.join(', ') || '(infer)'}. gateCommands (only those whose tool actually exists): ${gates}. debug patterns: ${s.debugPatterns.join(' ')}.${isDevUrl(s.devUrl) ? ` devUrl default ${s.devUrl}.` : ''}${pmLine}`
  })
  known.push(`- other — anything unrecognized; specialistAgent: general-purpose; conventions = whatever actually exists. gateCommands only from these templates, one item per script or target the evidence file defines, as {name, command, evidence, script} (evidence = the file relative to the repo root, script = the script or target name, command = the template with {script} replaced): ${gateTemplatesLine()}. Any other command is dropped.`)
  return known.join('\n')
}

// Model tiers. Phases name a tier, never a model, and every agent() call gets
// the tier's model AND effort explicitly — an agentType agent otherwise
// inherits its own frontmatter model, and effort falls back to the session
// default (which changes between releases).
// Aliases follow each new release, which suits personal use. For team
// reproducibility, distribute a version with full model IDs here
// (e.g. 'claude-opus-5-5'), or pin per run: args.models = { deep: 'claude-opus-5-5' }
// or { deep: { model: 'claude-opus-5-5', effort: 'xhigh' } }.
const MODEL_TIERS = {
  deep: { model: 'opus', effort: 'high' }, // investigation, specs, review, acceptance, decisions
  standard: { model: 'sonnet', effort: 'medium' }, // implementation, fixes, gates, verification votes
  light: { model: 'haiku', effort: 'low' }, // inventory and other mechanical work
}
function phaseModels(phaseTiers) {
  const overrides = (typeof args !== 'undefined' && args && typeof args === 'object' && args.models) || {}
  const resolved = {}
  for (const [phase, tier] of Object.entries(phaseTiers)) {
    const base = MODEL_TIERS[tier]
    if (!base) throw new Error(`Unknown model tier "${tier}" for phase "${phase}" (use ${Object.keys(MODEL_TIERS).join(' | ')})`)
    const o = overrides[tier]
    // A bridge host picks its own models, so its jobs carry the tier and the effort only.
    if (HOST !== 'claude') {
      resolved[phase] = { tier, effort: (o && typeof o === 'object' && o.effort) || base.effort }
      continue
    }
    resolved[phase] = typeof o === 'string' ? { ...base, model: o } : { ...base, ...(o || {}) }
  }
  return resolved
}

// Every step that may need a browser gets the same instructions: Playwright MCP
// first (built in), Claude in Chrome as a fallback, and an honest "not run".
const BROWSER_PHASES = new Set(['Reproduce', 'Acceptance', 'Visual'])
const BROWSER_GUIDE = `BROWSER: when this step needs a browser (web UI, navigation, visual or end-to-end checks), drive it with the Playwright MCP tools, named mcp__playwright__browser_* when the server comes from the project and mcp__plugin_sdd-kit_playwright__browser_* when it comes from the sdd-kit plugin (use whichever is available): browser_navigate, browser_snapshot, browser_click, browser_type, browser_fill_form, browser_wait_for, browser_take_screenshot, browser_console_messages, browser_network_requests, browser_resize (load each with ToolSearch "select:<name>" before its first call). Assert against browser_snapshot (the accessibility tree), use screenshots only as evidence, and check console errors and failed network requests on every page you visit. If the Playwright tools are unavailable, use Claude in Chrome (mcp__claude-in-chrome__*). If neither is available, report the browser check as not run — never claim it passed. API-only checks use HTTP (curl) instead of a browser.`
// The host reaches the runtime only through the sddHost global that the workflow bridge injects;
// Claude Code has no bridge, so the global is absent and the registry text below applies unchanged.
const HOST = typeof sddHost === 'string' && hasOwn(HOSTS, sddHost) ? sddHost : 'claude'
const browserGuideFor = () => HOSTS[HOST].browserGuide || BROWSER_GUIDE
// Where the host keeps project stacks, user stacks, agents and its trust store; Claude's values reproduce the text below unchanged.
const HOST_STACKS_DIR = HOSTS[HOST].stacksDir
const HOST_USER_STACKS_DIR = `~/${HOSTS[HOST].configDir}/stacks`
// A bridge host resolves specialists from the kit and from approved stack add-ons only, never from its own agents folder.
const addAgentHint = (name) => (HOST === 'claude'
  ? `add ${name}.md to ${HOSTS[HOST].agentsDir}/`
  : `add ${name}.md to agents/ of an approved stack add-on under ${HOSTS[HOST].stackAddonsDir}/`)
const HOST_TRUST_STORE_DIR = HOSTS[HOST].trustStoreDir.replace('<OS home>', '<home>')
const escapeRegex = (text) => text.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&')
// Plugin installs namespace agents ("sdd-kit:code-explorer", "<plugin>:<agent>");
// file-copy installs use bare names. Detect reports which one this run sees as
// discovery.mode (resolveDetect records it), and the candidates follow it so a pure
// install resolves every agent on the first try. The default agent is the last resort:
//   - a core agent (CORE_AGENTS): "sdd-kit:<name>" and the bare name;
//   - a stack specialist (AGENT_INFO): the bare name and "<plugin>:<name>", the latter only when its manifest sets agent.plugin;
//   - general-purpose is never resolved.
// "plugin" puts the namespaced form first, "file-copy" the bare name. "mixed", "unknown",
// "none" and every call made before Detect returns keep the default order: the namespaced
// form first for a core agent, the bare name first for a specialist.
// A candidate fails only when agent() throws (unknown agent type). A null result is the agent's own
// outcome (skipped, or ended without output) and is returned, so a resolved prompt never runs twice.
// The resolution (the form that worked, or null for the default agent) is kept per agent name for the
// run, so later calls go straight to the resolved form and the fallback is logged once. A form that
// worked is known only when its whole agent run returns, so calls that start together do not wait for
// it: each tries the candidates itself, skipping the forms an earlier call saw rejected.
const resolvedAgents = new Map()
const rejectedAgentTypes = new Set()
let discoveryMode = null

/**
 * Agent counts and token totals per phase for the run report.
 * phases[name] = { agents, tokens }: agents counts runAgent calls made with opts.phase = name
 * ('unphased' when absent); tokens is the budget spent while the phase was the current
 * costSnapshot phase, or null when the run has no budget. probesFailed counts candidate
 * names agent() rejected while resolving an agent type.
 */
const RUN_COST = { phases: {}, probesFailed: 0, cap: { limit: null, used: 0, refused: 0, phase: null } }
let costMark = null

/** Highest value args.maxAgents accepts: the runtime's own per-run backstop. */
const AGENT_CAP_LIMIT = 1000
/** Phases whose calls are never refused, so a capped run still writes its report. setAgentCap adds a workflow's own. */
const AGENT_CAP_EXEMPT = new Set(['Report', 'Close'])

/**
 * Sets the per-run agent cap. Call it before Detect with args.maxAgents. undefined and null take
 * `fallback`; any other value must be an integer from 1 to AGENT_CAP_LIMIT (strict: "40" and 1.5 are rejected).
 * @param {*} value args.maxAgents
 * @param {number|null} [fallback] the workflow's default; null or absent means no cap
 * @param {string[]} [exempt] phases besides Report and Close that are never refused
 * @returns {string[]} argIssues entries; empty when the value is acceptable
 * @example
 * const issues = setAgentCap(args.maxAgents, 120)
 */
function setAgentCap(value, fallback, exempt = []) {
  for (const name of exempt) AGENT_CAP_EXEMPT.add(name)
  const cap = RUN_COST.cap
  cap.limit = typeof fallback === 'number' ? fallback : null
  if (value === undefined || value === null) return []
  if (!Number.isInteger(value) || value < 1 || value > AGENT_CAP_LIMIT) {
    return [`args.maxAgents must be an integer from 1 to ${AGENT_CAP_LIMIT}. Fix: pass a whole number in that range, or leave it out for the default`]
  }
  cap.limit = value
  return []
}

/** Highest value args.maxFindings accepts. */
const FINDINGS_CAP_LIMIT = 50
/** The per-dimension Review findings cap of this run; setReviewArgs sets it. */
const REVIEW_CAP = { maxFindings: 8 }

/**
 * Validates the review-related args before Detect and sets the per-dimension findings cap.
 * `maxFindings` must be an integer from 1 to FINDINGS_CAP_LIMIT (undefined and null take `fallback`);
 * `profile`, when `profiles` is given, must be one of them.
 * @param {*} maxFindings args.maxFindings
 * @param {*} profile args.profile
 * @param {number} fallback default findings per dimension
 * @param {string[]} [profiles] the profile names the workflow accepts; omit when it has none
 * @returns {string[]} argIssues entries; empty when the args are acceptable
 * @example
 * const issues = setReviewArgs(args.maxFindings, args.profile, 8, ['quick', 'standard'])
 */
function setReviewArgs(maxFindings, profile, fallback, profiles) {
  const issues = []
  REVIEW_CAP.maxFindings = fallback
  if (maxFindings !== undefined && maxFindings !== null) {
    if (!Number.isInteger(maxFindings) || maxFindings < 1 || maxFindings > FINDINGS_CAP_LIMIT) {
      issues.push(`args.maxFindings must be an integer from 1 to ${FINDINGS_CAP_LIMIT}. Fix: pass a whole number in that range, or leave it out for the default`)
    } else REVIEW_CAP.maxFindings = maxFindings
  }
  if (profiles && profile !== undefined && profile !== null && !profiles.includes(profile)) {
    issues.push(`args.profile must be one of ${profiles.map((p) => `'${p}'`).join(' or ')}. Fix: pass one of those values, or leave it out for the default`)
  }
  return issues
}

/**
 * The run's agent cap as a result returns it.
 * @returns {{ limit: number|null, used: number, reached: boolean, refused: number, phase: string|null }}
 */
function agentCapResult() {
  const { limit, used, refused, phase } = RUN_COST.cap
  return { limit, used, reached: refused > 0, refused, phase }
}

/**
 * The cost line for the report: used and limit, with the phase of the first refusal once the cap was reached.
 * @returns {string}
 */
function agentCapLine() {
  const { limit, used, refused, phase } = RUN_COST.cap
  if (limit === null) return `agents: ${used} (no cap)`
  return refused > 0 ? `agents: ${used} of ${limit} (cap reached in ${phase})` : `agents: ${used} of ${limit}`
}

/**
 * A report-prompt paragraph for workflows without a ledger: empty unless calls were refused.
 * @returns {string}
 */
function agentCapNote() {
  const { limit, refused, phase } = RUN_COST.cap
  if (!refused) return ''
  return `\nAgent cap: the run's limit of ${limit} agents was reached in ${phase}; ${refused} call(s) were refused, so later checks did not run and the results are partial. State this in the report and end with: Fix: re-run with a higher maxAgents`
}

const CALL_KEY = /^[A-Za-z_$][A-Za-z0-9_$]*$/

/**
 * Serializes a workflow args value as call text: bare identifier keys in insertion order, JSON values.
 * A string is quoted in full and is never truncated, so the printed call runs as written.
 * @param {*} value the caller's args (object or string)
 * @returns {string}
 * @example
 * callArgs({ spec: 'spec-1', maxAgents: 240 }) // '{ spec: "spec-1", maxAgents: 240 }'
 */
function callArgs(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return JSON.stringify(value === undefined ? null : value)
  const parts = Object.keys(value)
    .filter((k) => value[k] !== undefined)
    .map((k) => `${CALL_KEY.test(k) ? k : JSON.stringify(k)}: ${JSON.stringify(value[k])}`)
  return parts.length ? `{ ${parts.join(', ')} }` : '{}'
}

/**
 * The call that launches a workflow again, computed in script so the Report agent quotes it as is.
 * A bridge host (HOST not 'claude') is checked first because the bridge always uses the bare name;
 * otherwise the name follows Detect's discovery mode: bare in file-copy mode, namespaced elsewhere.
 * @param {string} name workflow meta.name
 * @param {*} callerArgs args to pass on
 * @returns {string}
 */
function resumeCall(name, callerArgs) {
  if (HOST !== 'claude') return `workflow_start({ name: "${name}", workspace, args: ${callArgs(callerArgs)} })`
  const callName = discoveryMode === 'file-copy' ? name : `sdd-kit:${name}`
  return `Workflow({ name: "${callName}", args: ${callArgs(callerArgs)} })`
}

/**
 * The note that tells a file-copy install how the call is named; '' on a bridge host or in file-copy mode.
 * It goes into log and Report text only, never into a result field.
 * @param {string} name workflow meta.name
 * @returns {string}
 */
function resumeFileCopyNote(name) {
  return HOST !== 'claude' || discoveryMode === 'file-copy' ? '' : ` (file-copy install: name "${name}")`
}

/**
 * The maxAgents a relaunch should carry after the cap stopped the run: min(2 x limit, 1000).
 * @returns {number|null} null when the cap did not stop the run or is already at its maximum
 */
function raisedMaxAgents() {
  const { limit, refused } = RUN_COST.cap
  if (limit === null || refused === 0 || limit >= AGENT_CAP_LIMIT) return null
  return Math.min(limit * 2, AGENT_CAP_LIMIT)
}

/**
 * The caller's args for a relaunch: the same args, with maxAgents raised when the cap stopped the run.
 * A string argument stays a string unless keys are added; then it moves under `stringKey`.
 * @param {*} callerArgs the run's args
 * @param {object} [overrides] keys to set, such as { spec: '<id>' }
 * @param {string} [stringKey] the workflow's arg that a string argument stands for, such as 'bug'
 * @returns {*}
 * @example relaunchArgs('the total is off', { spec: 's' }, 'bug')  // { bug: 'the total is off', spec: 's' }
 */
function relaunchArgs(callerArgs, overrides = {}, stringKey = 'description') {
  const raised = raisedMaxAgents()
  const extra = { ...overrides, ...(raised ? { maxAgents: raised } : {}) }
  if (typeof callerArgs === 'string') return Object.keys(extra).length ? { [stringKey]: callerArgs, ...extra } : callerArgs
  return { ...(callerArgs && typeof callerArgs === 'object' ? callerArgs : {}), ...extra }
}

/**
 * The Next line for a run that should be relaunched as the same run: every task is ticked, so a new
 * {spec} run would have nothing to build.
 * @param {string} [call] the computed relaunch call to quote after the sentence; omit for ship-feature
 * @returns {string}
 */
function sameRunRelaunchLine(call) {
  const { limit, refused } = RUN_COST.cap
  const raised = raisedMaxAgents()
  const stopped = limit !== null && refused > 0
  const cap = !stopped ? '' : raised ? ` with maxAgents raised to ${raised}` : ` (maxAgents is at its maximum of ${AGENT_CAP_LIMIT}. Fix: narrow the scope or split the spec)`
  return `Relaunch this run in the same session (or after claude --resume)${cap}${call ? `: ${call}` : ''}`
}

/**
 * The ledger entry for a run that refused calls, or null when none was refused.
 * @returns {{ check: string, status: string, reason: string }|null}
 */
function agentCapEntry() {
  const { limit, refused, phase } = RUN_COST.cap
  if (!refused) return null
  return assure('agent-cap', 'unavailable', `agent cap of ${limit} reached in ${phase}; ${refused} call(s) refused, so later checks did not run. Fix: re-run with a higher maxAgents`)
}

function costPhase(name) {
  if (!hasOwn(RUN_COST.phases, name)) RUN_COST.phases[name] = { agents: 0, tokens: null }
  return RUN_COST.phases[name]
}

const runBudget = () => (typeof budget !== 'undefined' && budget && budget.total > 0 ? budget : null)

/**
 * Closes the current cost phase and opens `name`. Call it right after each main-line phase()
 * call, with the same title. The budget spent since the previous snapshot is added to the
 * previous phase, so a phase that repeats (a fix loop) accumulates. With no budget
 * (budget.total 0, as on the bridge) tokens stay null and the report prints "tokens: n/a".
 * @param {string} name the phase being entered
 * @returns {void}
 * @example
 * phase('Build'); costSnapshot('Build')
 */
function costSnapshot(name) {
  const b = runBudget()
  const remaining = b ? b.remaining() : null
  if (costMark && b && costMark.remaining !== null) {
    const entry = costPhase(costMark.phase)
    entry.tokens = (entry.tokens || 0) + Math.max(0, costMark.remaining - remaining)
  }
  costPhase(name)
  costMark = { phase: name, remaining }
}

/**
 * Candidate agent types for `name`, in the order runAgent tries them.
 * @param {string} name agent name without a plugin prefix
 * @param {string|null} [mode] Detect's discovery.mode; null (before Detect) keeps the default order
 * @returns {{ candidates: string[], hint: string }} hint: what to install or add when none resolves
 */
function agentCandidates(name, mode = discoveryMode) {
  if (CORE_AGENTS.includes(name)) {
    const candidates = mode === 'file-copy' ? [name, `sdd-kit:${name}`] : [`sdd-kit:${name}`, name]
    return { candidates, hint: 'reinstall sdd-kit (core agent missing)' }
  }
  if (hasOwn(AGENT_INFO, name)) {
    const info = AGENT_INFO[name]
    const namespaced = info.plugin ? [`${info.plugin}:${name}`] : []
    const candidates = mode === 'plugin' ? [...namespaced, name] : [name, ...namespaced]
    const stacks = info.stacks.join(', ')
    const hint = info.plugin
      ? `install ${info.plugin} for ${stacks}`
      : `${addAgentHint(name)}${info.source ? ` or set agent.plugin in ${info.source}` : ''}`
    return { candidates, hint }
  }
  return { candidates: [name], hint: addAgentHint(name) }
}

const RERUN_FIX = 'then re-run the same workflow'

/**
 * Errors the host reports when the session or account cannot run any agent. Patterns are anchored on
 * the host's own error text so a report that merely discusses a quota feature does not match.
 * @type {{ kind: string, pattern: RegExp, line: string }[]}
 */
const HOST_FATAL = [
  {
    kind: 'auth',
    pattern: /please run \/login|\bAPI Error: 401\b|"type"\s*:\s*"authentication_error"|\bOAuth token (?:has )?expired\b|\binvalid api key\b/i,
    line: `host session not authenticated. Fix: sign in to the host again, ${RERUN_FIX}`,
  },
  {
    kind: 'access',
    pattern: /\bAPI Error: 403\b|"type"\s*:\s*"permission_error"/,
    line: `host account has no access (API 403). Fix: check the account or organization permissions, sign in to the host with an account that has access, ${RERUN_FIX}`,
  },
  {
    kind: 'limit',
    pattern: /credit balance is too low|usage limit reached|\bquota (?:exceeded|exhausted)\b/i,
    line: `host credit or usage limit reached. Fix: add credits or wait for the limit to reset, ${RERUN_FIX}`,
  },
]

/**
 * Run-level host abort. Set by the first host-fatal result; every later runAgent call returns null.
 * Module-level like RUN_COST: each run evaluates the script afresh, so a re-run starts clear.
 */
const HOST_ABORT = { kind: null, line: null, phase: null }

/**
 * Classifies an agent() failure. A thrown error is matched on its message at any length; a string
 * result only when its trimmed length is 500 characters or less, and only when the matched phrase is
 * not in the call's own prompt: an agent that repeats a ticket or spec quoting an error message is
 * answering, not failing.
 * @param {*} errOrText an Error, or the value agent() returned
 * @param {string} [prompt] the prompt of the call that returned errOrText
 * @returns {{ kind: string, line: string }|null} the matched class, or null when not host-fatal
 * @example isHostFatal('Please run /login')                                   // { kind: 'auth', line: '...' }
 * @example isHostFatal('Please run /login', 'Bug: users see "Please run /login"')  // null
 */
function isHostFatal(errOrText, prompt) {
  let text
  let returned = false
  if (errOrText instanceof Error || (errOrText && typeof errOrText === 'object' && typeof errOrText.message === 'string')) text = errOrText.message
  else if (typeof errOrText === 'string' && errOrText.trim().length <= 500) {
    text = errOrText
    returned = true
  } else return null
  for (const h of HOST_FATAL) {
    const m = h.pattern.exec(text)
    if (!m) continue
    if (returned && typeof prompt === 'string' && prompt.toLowerCase().includes(m[0].toLowerCase())) continue
    return { kind: h.kind, line: h.line }
  }
  return null
}

/** @returns {boolean} true once a host-fatal result has aborted the run */
const hostAborted = () => HOST_ABORT.kind !== null

/**
 * The result of a run ended by a host-fatal error. Built without an agent, so no report is written.
 * @param {{ failedTasks?: number[], notRun?: number[], assurance?: object[], handFixes?: string[] }} [parts] failures from before the abort,
 *   tasks never built, the ledger so far, and steps the user takes by hand because no agent can run to undo them
 * @returns {object} { recommendation: 'ABORTED', abort: { kind, line, phase }, failedTasks, notRun, assurance, agentCap, next }
 */
function hostAbortResult(parts = {}) {
  const abort = { kind: HOST_ABORT.kind, line: HOST_ABORT.line, phase: HOST_ABORT.phase }
  return {
    recommendation: 'ABORTED',
    abort,
    failedTasks: parts.failedTasks || [],
    notRun: parts.notRun || [],
    assurance: parts.assurance || [],
    agentCap: agentCapResult(),
    next: `${abort.line}. Changes made before the abort are uncommitted in the working tree; check git status.${parts.handFixes && parts.handFixes.length ? ` Fix by hand: ${parts.handFixes.join('; ')}.` : ''}`,
  }
}

function tripHostAbort(fatal, phase) {
  if (hostAborted()) return
  HOST_ABORT.kind = fatal.kind
  HOST_ABORT.line = fatal.line
  HOST_ABORT.phase = phase
  log(fatal.line)
}

/**
 * Runs `prompt` through agent() with the agent type resolved for this install, adds the
 * browser guide to browser phases, and counts the call under opts.phase in RUN_COST.
 * @param {string} prompt
 * @param {object} [opts] agent() options; agentType is a bare agent name
 * @returns {Promise<*>} the agent's result
 */
async function runAgent(prompt, opts) {
  if (hostAborted()) return null
  const phaseName = (opts && opts.phase) || 'unphased'
  const cap = RUN_COST.cap
  if (cap.limit !== null && cap.used >= cap.limit && !AGENT_CAP_EXEMPT.has(phaseName)) {
    if (cap.refused === 0) {
      cap.phase = phaseName
      log(`Agent cap of ${cap.limit} reached in ${phaseName}; later agent calls are refused and their checks do not run. Fix: re-run with a higher maxAgents`)
    }
    cap.refused += 1
    return null
  }
  cap.used += 1
  const guard = (result) => {
    const fatal = isHostFatal(result, prompt)
    if (!fatal) return result
    tripHostAbort(fatal, phaseName)
    return null
  }
  const launch = async (p, o) => {
    try {
      return guard(await agent(p, o))
    } catch (e) {
      const fatal = isHostFatal(e)
      if (!fatal) throw e
      tripHostAbort(fatal, phaseName)
      return null
    }
  }
  costPhase((opts && opts.phase) || 'unphased').agents += 1
  if (opts && BROWSER_PHASES.has(opts.phase)) prompt = `${prompt}\n\n${browserGuideFor()}`
  if (!opts || !opts.agentType || opts.agentType === 'general-purpose') return launch(prompt, opts)
  const name = opts.agentType
  const { agentType, ...rest } = opts
  if (resolvedAgents.has(name)) {
    const known = resolvedAgents.get(name)
    return known === null ? launch(prompt, rest) : launch(prompt, { ...opts, agentType: known })
  }
  const { candidates, hint } = agentCandidates(name)
  for (const candidate of candidates) {
    if (hostAborted()) return null
    if (rejectedAgentTypes.has(candidate)) continue
    let result
    try {
      result = await agent(prompt, { ...opts, agentType: candidate })
    } catch (e) {
      const fatal = isHostFatal(e)
      if (fatal) {
        tripHostAbort(fatal, phaseName)
        return null
      }
      // Unknown agent type in this install mode; try the next form.
      rejectedAgentTypes.add(candidate)
      RUN_COST.probesFailed += 1
      continue
    }
    if (!resolvedAgents.has(name)) resolvedAgents.set(name, candidate)
    return guard(result)
  }
  if (!resolvedAgents.has(name)) {
    resolvedAgents.set(name, null)
    log(`Specialist ${name} not available (tried: ${candidates.join(', ')}); ${hint}. Falling back to general-purpose.`)
  }
  if (hostAborted()) return null
  return launch(prompt, rest)
}

// --- manifest validation ------------------------------------------------
// One validator for the generator and the runtime. It interprets STACK_SCHEMA
// (type, required, enum, additionalProperties, properties, items, pattern and
// oneOf) and adds the rules a schema cannot express. Problems come back in
// validation order as { pointer, rule, problem, fix }; the caller formats them as
// "<pointer> <problem>. Fix: <fix>". problem and fix may quote manifest values; rule
// never does, so text that reaches a prompt is built from pointer and rule only (redactedReason).
function manifestTypeOf(v) {
  if (Array.isArray(v)) return 'array'
  if (v === null) return 'null'
  if (Number.isInteger(v)) return 'integer'
  return typeof v
}

const manifestPointer = (parent, key) => `${parent}/${String(key).replace(/~/g, '~0').replace(/\//g, '~1')}`

function manifestSchemaCheck(value, schema, ptr, overlay, out) {
  const at = ptr || '/'
  const actual = manifestTypeOf(value)
  if (schema.oneOf) {
    const branch = schema.oneOf.find((b) => b.type === actual)
    if (!branch) {
      out.push({ pointer: at, rule: 'type', problem: `has the wrong type (found ${actual})`, fix: `use ${schema.oneOf.map((b) => `an ${b.type}`).join(' or ')}` })
      return
    }
    manifestSchemaCheck(value, branch, ptr, overlay, out)
    return
  }
  if (schema.type) {
    const ok = schema.type === actual || (schema.type === 'number' && actual === 'integer')
    if (!ok) {
      out.push({ pointer: at, rule: 'type', problem: `has the wrong type (found ${actual})`, fix: `use a ${schema.type}` })
      return
    }
  }
  if (schema.enum && !schema.enum.some((e) => e === value)) {
    out.push({ pointer: at, rule: 'enum', problem: `has the invalid value ${JSON.stringify(value)}`, fix: `use one of: ${schema.enum.map((e) => JSON.stringify(e)).join(', ')}` })
  }
  if (typeof value === 'string') {
    if (schema.pattern && !new RegExp(schema.pattern).test(value)) {
      out.push({ pointer: at, rule: 'pattern', problem: `does not match the pattern (found ${JSON.stringify(value)})`, fix: `match ${schema.pattern}` })
    }
    if (schema.maxLength !== undefined && value.length > schema.maxLength) {
      out.push({ pointer: at, rule: 'maxLength', problem: `is longer than ${schema.maxLength} characters`, fix: 'shorten it' })
    } else if (overlay && value.length > STACK_LIMITS.maxString) {
      out.push({ pointer: at, rule: 'maxLength', problem: `is longer than ${STACK_LIMITS.maxString} characters`, fix: 'shorten it' })
    }
  }
  if (actual === 'object' && schema.properties) {
    // An extending overlay refines a first-party stack, so it needs only its identity.
    const required = overlay && hasOwn(schema.properties, 'extends') && hasOwn(value, 'extends') ? schema.required.filter((k) => ['name', 'order'].includes(k)) : schema.required || []
    for (const key of required) {
      if (!hasOwn(value, key)) out.push({ pointer: manifestPointer(ptr, key), rule: 'required', problem: 'is missing', fix: `add "${key}"` })
    }
    for (const key of Object.keys(value)) {
      if (!hasOwn(schema.properties, key)) {
        if (schema.additionalProperties === false) {
          out.push({ pointer: manifestPointer(ptr, key), rule: 'additionalProperties', problem: 'is not an allowed key', fix: `remove "${key}" (allowed: ${Object.keys(schema.properties).join(', ')})` })
        }
      } else {
        manifestSchemaCheck(value[key], schema.properties[key], manifestPointer(ptr, key), overlay, out)
      }
    }
  }
  if (actual === 'array') {
    if (schema.minItems !== undefined && value.length < schema.minItems) {
      out.push({ pointer: at, rule: 'minItems', problem: `has fewer than ${schema.minItems} items`, fix: 'add an item' })
    }
    if (schema.maxItems !== undefined && value.length > schema.maxItems) {
      out.push({ pointer: at, rule: 'maxItems', problem: `has more than ${schema.maxItems} items`, fix: 'remove items' })
    } else if (overlay && value.length > STACK_LIMITS.maxItems) {
      out.push({ pointer: at, rule: 'maxItems', problem: `has more than ${STACK_LIMITS.maxItems} items`, fix: 'remove items' })
    }
    if (schema.items) value.forEach((item, i) => manifestSchemaCheck(item, schema.items, manifestPointer(ptr, i), overlay, out))
  }
}

// Rules per entry that the schema cannot express: unique keys in an array
// manifest, the 1-8 entry bound, where agent.plugin is allowed, and that only
// the core other manifest declares gateTemplates.
function manifestEntryRules(value, overlay, out) {
  const isList = Array.isArray(value)
  const entries = isList ? value : [value]
  if (isList && (value.length < 1 || value.length > STACK_LIMITS.maxEntries)) {
    out.push({ pointer: '/', rule: 'entryCount', problem: `must hold 1 to ${STACK_LIMITS.maxEntries} entries`, fix: 'split the manifest' })
  }
  const seen = new Set()
  entries.forEach((entry, i) => {
    if (manifestTypeOf(entry) !== 'object') return
    const ptr = isList ? `/${i}` : ''
    if (typeof entry.name === 'string') {
      if (seen.has(entry.name)) out.push({ pointer: `${ptr}/name`, rule: 'uniqueKeys', problem: `duplicates key "${entry.name}" in this file`, fix: 'use unique keys' })
      seen.add(entry.name)
    }
    if (hasOwn(entry, 'gateTemplates') && (overlay || entry.name !== 'other')) {
      out.push({ pointer: `${ptr}/gateTemplates`, rule: 'gateTemplates', problem: 'is reserved for the core other manifest', fix: 'remove "gateTemplates" and list the gates under "gates"' })
    }
    if (overlay && hasOwn(entry, 'devUrlHosts')) {
      out.push({ pointer: `${ptr}/devUrlHosts`, rule: 'additionalProperties', problem: 'is not an allowed key', fix: 'remove it (stack.schema.json lists the allowed keys)' })
    }
    if (overlay && hasOwn(entry, 'extends')) {
      if (typeof entry.extends === 'string' && (!FIRST_PARTY_KEYS.includes(entry.extends) || entry.extends === 'other')) {
        out.push({ pointer: `${ptr}/extends`, rule: 'extendsTarget', problem: 'names a stack that cannot be extended', fix: `name a first-party key other than "other", for example "${EXTENDS_EXAMPLE}"` })
      }
      if (FIRST_PARTY_KEYS.includes(entry.name)) {
        out.push({ pointer: `${ptr}/name`, rule: 'extendsName', problem: 'is a first-party key', fix: 'give the overlay its own key, for example "<key>-local"' })
      }
      for (const field of ['detect', 'markers', 'packages', 'role']) {
        if (hasOwn(entry, field)) out.push({ pointer: `${ptr}/${field}`, rule: 'extendsField', problem: 'is not allowed in an extending overlay', fix: 'remove it; classification comes from the extended stack' })
      }
    }
    if (!overlay && hasOwn(entry, 'extends')) {
      out.push({ pointer: `${ptr}/extends`, rule: 'additionalProperties', problem: 'is not an allowed key', fix: 'remove it (stack.schema.json lists the allowed keys)' })
    }
    const agent = entry.agent
    if (overlay && manifestTypeOf(agent) === 'object' && CORE_AGENTS.includes(agent.name)) {
      out.push({ pointer: `${ptr}/agent/name`, rule: 'coreAgent', problem: `names the core agent "${agent.name}"`, fix: 'name your own specialist, for example "<stack>-dev"' })
    }
    if (manifestTypeOf(agent) !== 'object' || !hasOwn(agent, 'plugin')) return
    if (agent.name === 'general-purpose') {
      out.push({ pointer: `${ptr}/agent/plugin`, rule: 'agentPlugin', problem: 'is not allowed for general-purpose', fix: 'remove "plugin"' })
    } else if (overlay && agent.plugin === 'sdd-kit') {
      out.push({ pointer: `${ptr}/agent/plugin`, rule: 'corePlugin', problem: 'names the core plugin "sdd-kit"', fix: "set your add-on's plugin name" })
    }
  })
}

/**
 * Validates a parsed stack manifest (one entry object, or an array of entries).
 * @param {unknown} value the parsed JSON
 * @param {{ overlay?: boolean }} [options] overlay: also apply the string, item and agent.plugin limits that guard project and user manifests
 * @returns {{ pointer: string, rule: string, problem: string, fix: string }[]} every problem, empty when valid
 */
function validateStackManifest(value, options) {
  const overlay = !!(options && options.overlay)
  const out = []
  manifestSchemaCheck(value, STACK_SCHEMA, '', overlay, out)
  manifestEntryRules(value, overlay, out)
  return out
}

// --- canonical JSON, sha256 and trust ----------------------------------------
// Workflow scripts cannot import modules, so the hash that identifies a manifest
// is computed here without crypto. src/skills/stack-trust/scripts/trust-store.mjs
// uses node:crypto over the same canonical text; tools/test/fixtures/trust-vectors.json
// pins both to the same digests.

/**
 * Serializes a JSON value with object keys sorted in code-unit order and no whitespace.
 * @param {unknown} value parsed JSON
 * @returns {string} the canonical text
 */
function canonicalJson(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`
  if (value !== null && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((k) => `${JSON.stringify(k)}:${canonicalJson(value[k])}`).join(',')}}`
  }
  return JSON.stringify(value)
}

// Canonical text of a parsed manifest: `$schema` is dropped from the top-level object, or from each top-level element of an array.
function canonicalManifest(parsed) {
  const strip = (e) => {
    if (e === null || typeof e !== 'object' || Array.isArray(e) || !hasOwn(e, '$schema')) return e
    const { $schema, ...rest } = e
    return rest
  }
  return canonicalJson(Array.isArray(parsed) ? parsed.map(strip) : strip(parsed))
}

const SHA256_K = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
]

// UTF-8 bytes of a string; a lone surrogate encodes as U+FFFD, as node does.
function utf8Bytes(text) {
  const bytes = []
  for (const ch of text) {
    let c = ch.codePointAt(0)
    if (c >= 0xd800 && c <= 0xdfff) c = 0xfffd
    if (c < 0x80) bytes.push(c)
    else if (c < 0x800) bytes.push(0xc0 | (c >> 6), 0x80 | (c & 63))
    else if (c < 0x10000) bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63))
    else bytes.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63))
  }
  return bytes
}

/**
 * SHA-256 of a string's UTF-8 bytes, as lowercase hex.
 * @param {string} text
 * @returns {string} 64 hex characters
 */
function sha256Hex(text) {
  const bytes = utf8Bytes(text)
  const bitLength = bytes.length * 8
  bytes.push(0x80)
  while (bytes.length % 64 !== 56) bytes.push(0)
  const high = Math.floor(bitLength / 0x100000000)
  const low = bitLength >>> 0
  for (const word of [high, low]) bytes.push((word >>> 24) & 255, (word >>> 16) & 255, (word >>> 8) & 255, word & 255)
  const h = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]
  const w = new Array(64)
  const rotr = (x, n) => (x >>> n) | (x << (32 - n))
  for (let offset = 0; offset < bytes.length; offset += 64) {
    for (let i = 0; i < 16; i++) {
      const j = offset + i * 4
      w[i] = ((bytes[j] << 24) | (bytes[j + 1] << 16) | (bytes[j + 2] << 8) | bytes[j + 3]) >>> 0
    }
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3)
      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10)
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0
    }
    let [a, b, c, d, e, f, g, hh] = h
    for (let i = 0; i < 64; i++) {
      const t1 = (hh + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + SHA256_K[i] + w[i]) >>> 0
      const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) >>> 0
      hh = g
      g = f
      f = e
      e = (d + t1) >>> 0
      d = c
      c = b
      b = a
      a = (t1 + t2) >>> 0
    }
    const next = [a, b, c, d, e, f, g, hh]
    for (let i = 0; i < 8; i++) h[i] = (h[i] + next[i]) >>> 0
  }
  return h.map((x) => x.toString(16).padStart(8, '0')).join('')
}

// Hash that identifies a manifest (file or entry) in the trust store and in FIRST_PARTY_HASHES.
const manifestHash = (parsed) => sha256Hex(canonicalManifest(parsed))

// Approved hashes from the trust store text Detect read. A store that is present but does not parse approves nothing.
function parseTrustStore(text) {
  if (text === null || text === undefined) return { hashes: new Set(), unreadable: false }
  try {
    const store = JSON.parse(text)
    if (store && typeof store === 'object' && Array.isArray(store.trusted)) {
      return { hashes: new Set(store.trusted.map((t) => t && t.sha256).filter((h) => typeof h === 'string')), unreadable: false }
    }
  } catch (e) {
    // falls through to unreadable
  }
  return { hashes: new Set(), unreadable: true }
}

// --- overlay: third-party manifests merged over the inlined registry ----------
// Workflow scripts cannot read files, so Detect returns raw manifest text and this code
// validates, deduplicates and trusts it. First-party entries are inlined and always win.

const DISCOVERY_MODES = ['plugin', 'file-copy', 'mixed', 'unknown', 'none']
const DISCOVERY_METHODS = ['plugin-list', 'installed-plugins', 'cache-sweep', 'stacks-dir', 'none']
const SCOPE_RANK = { project: 0, plugin: 1, user: 2 }
const STALE_FIX = {
  file: 're-run install.sh to refresh it',
  plugin: (plugin) => `update sdd-kit and ${plugin} to the same version`,
}

const problemReason = (p) => `${p.pointer} ${p.problem}. Fix: ${p.fix}`

// What each validation rule means, as the run reports it. A rejected manifest's reason carries its JSON
// pointer, the rule name and this fixed text; no value, key or other text of the manifest reaches a prompt.
const RULE_TEXT = {
  type: ['has the wrong type', 'use the type stack.schema.json gives for it'],
  enum: ['has a value outside the allowed list', 'use one of the values stack.schema.json lists for it'],
  pattern: ['does not match its pattern', 'match the pattern stack.schema.json gives for it'],
  maxLength: [`is longer than ${STACK_LIMITS.maxString} characters`, 'shorten it'],
  required: ['is missing', 'add it'],
  additionalProperties: ['is not an allowed key', 'remove it (stack.schema.json lists the allowed keys)'],
  minItems: ['has too few items', 'add an item'],
  maxItems: [`has more than ${STACK_LIMITS.maxItems} items`, 'remove items'],
  entryCount: [`must hold 1 to ${STACK_LIMITS.maxEntries} entries`, 'split the manifest'],
  uniqueKeys: ['duplicates another key in this file', 'use unique keys'],
  gateTemplates: ['is reserved for the core other manifest', 'remove "gateTemplates" and list the gates under "gates"'],
  coreAgent: ['names a core agent', 'name your own specialist, for example "<stack>-dev"'],
  agentPlugin: ['is not allowed for general-purpose', 'remove "plugin"'],
  corePlugin: ['names the core plugin "sdd-kit"', "set your add-on's plugin name"],
  extendsTarget: ['names a stack that cannot be extended', `name a first-party key other than "other", for example "${EXTENDS_EXAMPLE}"`],
  extendsName: ['is a first-party key', 'give the overlay its own key, for example "<key>-local"'],
  extendsField: ['is not allowed in an extending overlay', 'remove it; classification comes from the extended stack'],
  json: ['is not valid JSON', 'correct the JSON syntax'],
  maxSize: [`is larger than ${STACK_LIMITS.maxRawLength / 1024} KB`, 'shorten the manifest'],
}

// Every property name the schema declares; a pointer segment that is neither one of these nor an array index
// is a key the manifest chose, and is reported as <key>.
const SCHEMA_KEY_NAMES = (() => {
  const names = new Set()
  const walk = (node) => {
    if (Array.isArray(node)) return node.forEach(walk)
    if (node === null || typeof node !== 'object') return
    if (node.properties) for (const k of Object.keys(node.properties)) names.add(k)
    for (const v of Object.values(node)) walk(v)
  }
  walk(STACK_SCHEMA)
  return names
})()

/**
 * A rejection reason as the run reports it: the problem's JSON pointer (manifest-chosen keys replaced by
 * <key>), the rule it breaks and that rule's fixed text.
 * @param {{ pointer: string, rule: string }} p a validator problem, or { pointer: '/', rule: 'json' | 'maxSize' }
 * @returns {string} for example '/role has a value outside the allowed list (rule enum). Fix: use one of the values stack.schema.json lists for it'
 */
function redactedReason(p) {
  const pointer = !p.pointer || p.pointer === '/' ? '/' : p.pointer.split('/').map((seg, i) => (i === 0 || /^\d{1,3}$/.test(seg) || SCHEMA_KEY_NAMES.has(seg) ? seg : '<key>')).join('/')
  const rule = hasOwn(RULE_TEXT, p.rule) ? p.rule : 'schema'
  const [ruleProblem, fix] = hasOwn(RULE_TEXT, rule) ? RULE_TEXT[rule] : ['breaks the manifest schema', 'check the manifest against stack.schema.json']
  // A length or count limit comes from the schema or STACK_LIMITS, never from the manifest, so the validator's
  // text is kept when it is exactly that sentence with a number.
  const limitText = (rule === 'maxLength' && /^is longer than \d+ characters$/.test(String(p.problem || ''))) || (rule === 'maxItems' && /^has more than \d+ items$/.test(String(p.problem || '')))
  const problem = limitText ? p.problem : ruleProblem
  return `${pointer} ${problem} (rule ${rule}). Fix: ${fix}`
}
const SOURCE_LABEL_PATTERN = /^[A-Za-z0-9:._~/@-]{1,120}$/

// The source labels Detect may report. Anything else is rejected before its text is read.
const MANIFEST_SOURCE_FORMS = [
  new RegExp(`^project:${escapeRegex(HOST_STACKS_DIR)}/[^/\\\\\\s]+$`),
  new RegExp(`^user:${escapeRegex(HOST_USER_STACKS_DIR)}/[^/\\\\\\s]+$`),
  /^plugin:[A-Za-z0-9][A-Za-z0-9._-]*@[A-Za-z0-9._-]+$/,
]
const MISSING_SOURCE = `missing or invalid source. Fix: report source as project:${HOST_STACKS_DIR}/<file>, user:${HOST_USER_STACKS_DIR}/<file> or plugin:<name>@<marketplace>`
// A label must pass SOURCE_LABEL_PATTERN as well as one of the forms: it is pasted into prompts and logs.
const isManifestSource = (source) => SOURCE_LABEL_PATTERN.test(source) && MANIFEST_SOURCE_FORMS.some((re) => re.test(source))
const STACK_KEY_PATTERN = /^[a-z][a-z0-9-]{1,31}$/

// Which add-on directory a manifest source stands in for, or null when the source is not a first-party location.
function firstPartyLocation(source) {
  const colon = source.indexOf(':')
  const scope = colon > 0 ? source.slice(0, colon) : ''
  const rest = source.slice(colon + 1)
  let dir = null
  let plugin = null
  if (scope === 'project') {
    const m = new RegExp(`^${escapeRegex(HOST_STACKS_DIR)}/([^/]+)\\.json$`).exec(rest)
    dir = m && m[1]
  } else if (scope === 'user') {
    const m = new RegExp(`^${escapeRegex(HOST_USER_STACKS_DIR)}/([^/]+)\\.json$`).exec(rest)
    dir = m && m[1]
  } else if (scope === 'plugin') {
    plugin = rest.split('@')[0]
    dir = FIRST_PARTY_PLUGINS.includes(plugin) ? plugin.replace(/^sdd-kit-/, '') : null
  }
  if (!dir || !hasOwn(FIRST_PARTY_FILES, dir)) return null
  return { dir, plugin, kind: scope === 'plugin' ? 'plugin' : 'file' }
}

const manifestEntries = (parsed) => (Array.isArray(parsed) ? parsed : [parsed])

const entryName = (e) => (e !== null && typeof e === 'object' && typeof e.name === 'string' ? e.name : null)

/**
 * Validates Detect's manifests and decides which keys join the registry.
 * Pure: nothing is installed until installOverlay(result) runs.
 * A first-party location may come back as { source, sha256 } (the canonical hash, no text): it is present
 * when the hash equals FIRST_PARTY_FILE_HASHES for its add-on, a stale copy otherwise.
 * @param {{ source: string, raw?: string, sha256?: string }[]} manifests manifest files from Detect
 * @param {string|null} trustStoreText verbatim trust store text, null when absent
 * A manifest without a string source, or with a source outside the forms in MANIFEST_SOURCE_FORMS, is
 * rejected and its text is never parsed. declinedKeys maps every stack key a rejected manifest names to the
 * reason, and unnamedRejections lists the rejected manifests whose keys could not be read, so resolveRepo can
 * report a repo of such a stack as not run.
 * @returns {{ present: string[], added: { key: string, source: string }[], ignored: { key: string, source: string, reason: string }[], rejected: { source: string, reason: string, firstParty: boolean }[], entries: object, keys: string[], untrusted: { source: string, keys: string[], sha256: string }[], logs: string[], storeUnreadable: boolean, declinedKeys: Object<string, string>, unnamedRejections: string[] }}
 */
function mergeOverlay(manifests, trustStoreText) {
  const present = []
  const ignored = []
  const rejected = []
  const logs = []
  const stale = []
  const candidates = []
  const trust = parseTrustStore(trustStoreText)
  const declinedKeys = {}
  const unnamedRejections = []
  const declineKeys = (value, reason) => {
    for (const e of manifestEntries(value)) {
      const key = entryName(e)
      if (key !== null && STACK_KEY_PATTERN.test(key) && !hasOwn(declinedKeys, key)) declinedKeys[key] = reason.slice(0, 300)
    }
  }

  const markStale = (source, where, keys) => {
    const fix = where.kind === 'plugin' ? STALE_FIX.plugin(where.plugin) : STALE_FIX.file
    for (const key of keys) ignored.push({ key, source, reason: `first-party key (stale or edited copy; ${fix})` })
    stale.push({ source, kind: where.kind, fix })
  }

  for (const m of Array.isArray(manifests) ? manifests : []) {
    if (!m || typeof m !== 'object' || typeof m.source !== 'string' || !isManifestSource(m.source)) {
      const label = m && typeof m === 'object' && typeof m.source === 'string' ? (SOURCE_LABEL_PATTERN.test(m.source) ? m.source : '(invalid source)') : '(no source)'
      rejected.push({ source: label, reason: MISSING_SOURCE, firstParty: false })
      unnamedRejections.push(label)
      logs.push(`Stack manifest rejected: ${label} — ${MISSING_SOURCE}`)
      continue
    }
    const source = m.source
    const where = firstPartyLocation(source)
    const reject = (reason, firstParty) => {
      rejected.push({ source, reason, firstParty })
      logs.push(`Stack manifest rejected: ${source} — ${reason}`)
    }
    if (typeof m.raw !== 'string' && typeof m.sha256 === 'string') {
      if (!where) reject('/ came back as a hash, but only a first-party location may. Fix: return the manifest text as raw', false)
      else if (m.sha256 === FIRST_PARTY_FILE_HASHES[where.dir]) present.push(source)
      else markStale(source, where, FIRST_PARTY_FILES[where.dir])
      continue
    }
    const raw = typeof m.raw === 'string' ? m.raw : ''
    let parsed
    let parseError = null
    try {
      parsed = JSON.parse(raw)
    } catch (e) {
      parseError = e
    }
    if (raw.length > STACK_LIMITS.maxRawLength || parseError) {
      if (raw.length > STACK_LIMITS.maxRawLength) {
        if (!parseError) declineKeys(parsed, `${source} was rejected (larger than ${STACK_LIMITS.maxRawLength / 1024} KB)`)
        else unnamedRejections.push(source)
        reject(redactedReason({ pointer: '/', rule: 'maxSize' }), !!where)
      } else {
        unnamedRejections.push(source)
        reject(redactedReason({ pointer: '/', rule: 'json' }), !!where)
      }
      continue
    }
    const keys = manifestEntries(parsed).map(entryName)
    const firstParty = !!where && keys.every((k) => k !== null && FIRST_PARTY_FILES[where.dir].includes(k))
    const problems = validateStackManifest(parsed, { overlay: !firstParty })
    if (problems.length) {
      declineKeys(parsed, `${source} was rejected (${redactedReason(problems[0])})`)
      reject(redactedReason(problems[0]), firstParty)
      continue
    }
    if (firstParty) {
      if (manifestEntries(parsed).every((e) => FIRST_PARTY_HASHES[e.name] === manifestHash(e))) {
        present.push(source)
      } else {
        markStale(source, where, keys)
      }
      continue
    }
    const scope = source.slice(0, source.indexOf(':'))
    candidates.push({ source, rank: hasOwn(SCOPE_RANK, scope) ? SCOPE_RANK[scope] : 3, parsed, sha256: manifestHash(parsed) })
  }

  // The first valid entry for a key wins: project before plugin before user, then by source.
  candidates.sort((a, b) => a.rank - b.rank || (a.source < b.source ? -1 : a.source > b.source ? 1 : 0))
  const entries = {}
  const bySource = new Map()
  const extending = []
  const extendsMap = {}
  const untrustedExtending = []
  for (const c of candidates) {
    for (const entry of manifestEntries(c.parsed)) {
      if (hasOwn(entry, 'extends')) {
        if (trust.hashes.has(c.sha256)) {
          extending.push({ entry, c })
        } else {
          untrustedExtending.push({ source: c.source, keys: [entry.name], sha256: c.sha256, extends: entry.extends })
          logs.push(`${c.source} extends ${entry.extends} but is not trusted — using the first-party ${entry.extends} stack. Fix: run /stack-trust`)
        }
      } else if (FIRST_PARTY_KEYS.includes(entry.name)) {
        ignored.push({ key: entry.name, source: c.source, reason: 'first-party key' })
      } else if (hasOwn(entries, entry.name)) {
        ignored.push({ key: entry.name, source: c.source, reason: `duplicate key (kept ${entries[entry.name].source})` })
      } else {
        entries[entry.name] = { entry, source: c.source, sha256: c.sha256, trusted: trust.hashes.has(c.sha256) }
        if (!bySource.has(c.source)) bySource.set(c.source, [])
        bySource.get(c.source).push(entry.name)
      }
    }
  }
  // Trusted overlays that extend one key compete: the lowest order wins, then the key in code-unit order.
  extending.sort((a, b) => a.entry.order - b.entry.order || (a.entry.name < b.entry.name ? -1 : a.entry.name > b.entry.name ? 1 : 0))
  for (const { entry, c } of extending) {
    if (hasOwn(extendsMap, entry.extends)) {
      const winner = entries[extendsMap[entry.extends]]
      ignored.push({ key: entry.name, source: c.source, reason: `extends ${entry.extends}, and ${extendsMap[entry.extends]} from ${winner.source} wins (lower order, then key). Fix: give the overlay you want the lowest order, or remove the other.` })
    } else if (hasOwn(entries, entry.name)) {
      ignored.push({ key: entry.name, source: c.source, reason: `duplicate key (kept ${entries[entry.name].source})` })
    } else {
      const { extends: target, ...declared } = entry
      entries[entry.name] = { entry: { ...firstPartyEntry(target), ...declared }, source: c.source, sha256: c.sha256, trusted: true, extends: target, declared: Object.keys(declared) }
      extendsMap[target] = entry.name
      if (!bySource.has(c.source)) bySource.set(c.source, [])
      bySource.get(c.source).push(entry.name)
    }
  }
  const added = candidates.flatMap((c) => (bySource.get(c.source) || []).map((key) => (entries[key].extends ? { key, source: c.source, extends: entries[key].extends } : { key, source: c.source })))
  const untrusted = [...bySource].filter(([source]) => !entries[bySource.get(source)[0]].trusted).map(([source, keys]) => ({ source, keys, sha256: entries[keys[0]].sha256 })).concat(untrustedExtending)

  for (const i of ignored) if (!i.reason.startsWith('first-party key (')) logs.push(`Stack manifest ignored: ${i.source} — ${i.reason}`)
  if (stale.length) {
    const sources = stale.map((s) => s.source).join(', ')
    const fixes = ['file', 'plugin'].flatMap((kind) => [...new Set(stale.filter((s) => s.kind === kind).map((s) => s.fix))])
    logs.push(`First-party stack manifests differ from this core (${sources}). Fix: ${fixes.join('; ')}.`)
  }

  const overlayKeys = Object.keys(entries).sort()
  const keys = [...FIRST_PARTY_KEYS.filter((k) => k !== 'other'), ...overlayKeys, 'other']
  return { present, added, ignored, rejected, entries, keys, untrusted, logs, storeUnreadable: trust.unreadable, declinedKeys, unnamedRejections, extends: extendsMap }
}

/**
 * A first-party stack as a manifest entry, rebuilt from the registry blocks manifestRows projected. An
 * extending overlay overrides some of its fields and inherits the rest.
 * @param {string} key a first-party stack key
 * @returns {object} the entry
 */
function firstPartyEntry(key) {
  const row = STACKS[key]
  const traits = hasOwn(STACK_TRAITS, key) ? STACK_TRAITS[key] : {}
  const extras = hasOwn(STACK_EXTRAS, key) ? STACK_EXTRAS[key] : {}
  const meta = extras.gates || {}
  const skip = traits.scaffoldSkipGates || []
  const entry = {
    role: row.role,
    detect: row.detect,
    agent: hasOwn(AGENT_PLUGIN, row.agent) ? { name: row.agent, plugin: AGENT_PLUGIN[row.agent] } : { name: row.agent },
    conventions: row.conventions,
    gates: row.gates.map((g) => ({ ...g, ...(meta[g.name] || {}), ...(skip.includes(g.name) ? { skipWhenScaffolded: true } : {}) })),
    debugPatterns: row.debugPatterns,
    acceptance: row.acceptance,
  }
  if (row.devUrl !== undefined) entry.devUrl = row.devUrl
  if (row.visual !== undefined) entry.visual = row.visual
  if (traits.buildGateGuard !== undefined) entry.buildGateGuard = traits.buildGateGuard
  if (traits.execWrapper !== undefined) entry.execWrapper = traits.execWrapper
  const contractSync = {}
  if (traits.routeListCommand !== undefined) contractSync.routeListCommand = traits.routeListCommand
  if (traits.contractTemplate !== undefined) contractSync.template = traits.contractTemplate
  if (traits.contractConsumer === true) contractSync.consumer = true
  if (Object.keys(contractSync).length) entry.contractSync = contractSync
  for (const f of MANIFEST_EXTRA_FIELDS) if (extras[f] !== undefined) entry[f] = extras[f]
  return entry
}

// Optional manifest blocks copied unchanged into STACK_EXTRAS.
const MANIFEST_EXTRA_FIELDS = ['skills', 'scaffold', 'ci', 'e2e', 'e2eBackend', 'migrations', 'audit', 'markers', 'packages', 'packageManagers', 'sourceDirs', 'explore', 'docImpact', 'testIntegrity', 'security', 'gateTemplates']

/**
 * The one projection of a manifest entry onto the registry: its STACKS row plus the trait and extra
 * blocks that sit beside it. gen-stacks renders the first-party registry through this function and
 * installOverlay applies it to overlay entries, so a schema field reaches both or neither.
 * @param {object} entry a validated manifest entry
 * @returns {{ row: object, traits: object, extras: object }} traits/extras are {} when the entry has none
 */
function manifestRows(entry) {
  const row = {
    role: entry.role,
    detect: entry.detect,
    agent: entry.agent.name,
    conventions: entry.conventions,
    gates: entry.gates.map((g) => ({ name: g.name, command: g.command })),
    debugPatterns: entry.debugPatterns,
  }
  if (entry.devUrl !== undefined) row.devUrl = entry.devUrl
  if (entry.visual !== undefined) row.visual = entry.visual
  row.acceptance = entry.acceptance
  const traits = {}
  if (entry.buildGateGuard !== undefined) traits.buildGateGuard = entry.buildGateGuard
  if (entry.execWrapper !== undefined) traits.execWrapper = entry.execWrapper
  const cs = entry.contractSync || {}
  if (cs.routeListCommand !== undefined) traits.routeListCommand = cs.routeListCommand
  if (cs.template !== undefined) traits.contractTemplate = cs.template
  if (cs.consumer === true) traits.contractConsumer = true
  const skip = entry.gates.filter((g) => g.skipWhenScaffolded === true).map((g) => g.name)
  if (skip.length) traits.scaffoldSkipGates = skip
  const extras = {}
  const gates = {}
  for (const g of entry.gates) {
    const meta = {}
    if (g.kind !== undefined) meta.kind = g.kind
    if (g.unless !== undefined) meta.unless = g.unless
    if (g.requires !== undefined) meta.requires = g.requires
    if (g.lintFix !== undefined) meta.lintFix = g.lintFix
    if (g.scriptFallback !== undefined) meta.scriptFallback = g.scriptFallback
    if (Object.keys(meta).length) gates[g.name] = meta
  }
  if (Object.keys(gates).length) extras.gates = gates
  for (const f of MANIFEST_EXTRA_FIELDS) if (entry[f] !== undefined) extras[f] = entry[f]
  return { row, traits, extras }
}

// Specialist agents of the effective registry: name -> { plugin, stacks, source }. An untrusted overlay
// contributes none (OD-17a).
function buildAgentInfo(overlay) {
  const info = {}
  for (const key of STACK_KEYS) {
    const name = STACKS[key].agent
    if (name === 'general-purpose' || (hasOwn(overlay, key) && !overlay[key].trusted)) continue
    if (!hasOwn(info, name)) {
      const own = hasOwn(overlay, key) ? overlay[key] : null
      info[name] = { plugin: hasOwn(AGENT_PLUGIN, name) ? AGENT_PLUGIN[name] : (own && own.plugin) || null, stacks: [], source: own ? own.source : null }
    }
    info[name].stacks.push(key)
  }
  return info
}

/**
 * Makes a mergeOverlay result the effective registry: STACKS, STACK_KEYS, STACK_AGENT, AGENT_INFO and
 * the trust of each overlay key. Everything stackCatalog, debugScanFor and gate planning read follows.
 */
function installOverlay(merged) {
  const overlay = {}
  for (const [key, e] of Object.entries(merged.entries)) {
    const { row, traits, extras } = manifestRows(e.entry)
    STACKS[key] = row
    if (Object.keys(traits).length) STACK_TRAITS[key] = traits
    if (Object.keys(extras).length) STACK_EXTRAS[key] = extras
    overlay[key] = { source: e.source, plugin: e.entry.agent.plugin || null, trusted: e.trusted, sha256: e.sha256 }
    if (e.extends) overlay[key].declared = e.declared
  }
  EXTENDS = merged.extends || {}
  STACK_KEYS = merged.keys
  // An untrusted overlay's specialist name is never used: its steps run as the default agent (OD-17a).
  STACK_AGENT = Object.fromEntries(STACK_KEYS.map((k) => [k, hasOwn(overlay, k) && !overlay[k].trusted ? 'general-purpose' : STACKS[k].agent]))
  AGENT_INFO = buildAgentInfo(overlay)
  OVERLAY_META = overlay
  DECLINED_KEYS = merged.declinedKeys || {}
  DECLINED_UNNAMED = merged.unnamedRejections || []
  MANIFESTS_DECLINED = !!((merged.rejected || []).length || (merged.ignored || []).length || (merged.untrusted || []).length)
}

// --- Detect plumbing ---------------------------------------------------------

// Schema fragments every workflow spreads into its Detect result schema.
const DETECT_EXTRA_SCHEMA = {
  stackManifests: {
    type: 'array',
    items: { type: 'object', required: ['source'], properties: { source: { type: 'string' }, raw: { type: 'string' }, sha256: { type: 'string' } } },
  },
  // Absent and unreadable stores are both null (or omitted); unreadable also adds a discovery error.
  trustStore: { type: ['string', 'null'] },
  discovery: {
    type: 'object',
    properties: {
      mode: { type: 'string', enum: DISCOVERY_MODES },
      method: { type: 'string', enum: DISCOVERY_METHODS },
      errors: { type: 'array', items: { type: 'string' } },
    },
  },
}
// Per repo: the gates whose `unless` globs matched a file or directory in that repo.
const REPO_UNLESS_SCHEMA = {
  type: 'array',
  items: { type: 'object', required: ['gate', 'glob'], properties: { gate: { type: 'string' }, glob: { type: 'string' } } },
}
const GATE_NAMES_SCHEMA = { type: 'array', items: { type: 'string' } }
// Per repo: the unmet entries of each gate whose requires list is unmet, each entry as the manifest writes it.
const MISSING_REQUIRES_SCHEMA = {
  type: 'array',
  items: {
    type: 'object',
    required: ['gate', 'entries'],
    properties: { gate: { type: 'string' }, entries: { type: 'array', items: { anyOf: [{ type: 'string' }, { type: 'array', items: { type: 'string' } }] } } },
  },
}
const EXEC_WRAPPER_FACT_SCHEMA = { type: 'object', required: ['present'], properties: { present: { type: 'boolean' }, running: { type: 'boolean' }, dir: { type: 'string' } } }
/**
 * The per-repo answers the Detect prompt asks for (stackDiscoveryPrompt), spread into the repo item of
 * every workflow's Detect schema. A structured-output agent only fills declared properties, so a field
 * the prompt asks for and this block omits never reaches cleanRepoFields.
 */
const REPO_DETECT_SCHEMA = {
  // Gates of this repo's stack whose `unless` globs matched a file or directory here.
  unlessMatched: REPO_UNLESS_SCHEMA,
  // Exec wrapper of the stack manifest: present = its marker file exists here, running = its running check succeeded,
  // dir = this repo's path relative to the marker's directory, for a wrapper with workdir.
  execWrapper: EXEC_WRAPPER_FACT_SCHEMA,
  // Hostnames of the URLs at the manifest's devUrlFields in the running check's output, when that check passed.
  reportedDevHosts: GATE_NAMES_SCHEMA,
  // Gates whose `requires` file is absent in this repo.
  missingTools: GATE_NAMES_SCHEMA,
  // For each such gate with a requires list: the entries that are unmet.
  missingRequires: MISSING_REQUIRES_SCHEMA,
  // Per trusted extending manifest (keyed by its name): the facts above answered for that manifest's own fields.
  overlayFacts: {
    type: 'object',
    additionalProperties: { type: 'object', properties: { execWrapper: EXEC_WRAPPER_FACT_SCHEMA, reportedDevHosts: GATE_NAMES_SCHEMA, missingTools: GATE_NAMES_SCHEMA, missingRequires: MISSING_REQUIRES_SCHEMA, unlessMatched: REPO_UNLESS_SCHEMA } },
  },
  // Gates whose project script contains the `lintFix` flag.
  mutatingGates: GATE_NAMES_SCHEMA,
  // Gates whose project script contains the `scriptFallback` text.
  legacyScriptGates: GATE_NAMES_SCHEMA,
  // The lowest major each `scriptFallback` dependency's declared range admits; a dependency left out is unknown.
  dependencyMajors: {
    type: 'array',
    items: { type: 'object', required: ['dependency', 'major'], properties: { dependency: { type: 'string' }, major: { type: 'integer' } } },
  },
}

// Prints "<sha256> <file>" for each file: the canonical manifest hash (canonicalManifest + sha256), with node:crypto.
const MANIFEST_HASH_COMMAND = `node -e 'const c=require("crypto"),f=require("fs");const j=(v)=>Array.isArray(v)?"["+v.map(j).join(",")+"]":v!==null&&typeof v=="object"?"{"+Object.keys(v).sort().map((k)=>JSON.stringify(k)+":"+j(v[k])).join(",")+"}":JSON.stringify(v);const s=(e)=>{if(e===null||typeof e!="object"||Array.isArray(e))return e;const{$schema,...r}=e;return r};for(const p of process.argv.slice(1)){const m=JSON.parse(f.readFileSync(p,"utf8"));console.log(c.createHash("sha256").update(j(Array.isArray(m)?m.map(s):s(m))).digest("hex"),p)}'`

// First-party manifest locations and the hash a copy that matches this core has, for the Detect prompt.
function firstPartyHashLine() {
  return Object.keys(FIRST_PARTY_FILES)
    .filter((dir) => hasOwn(FIRST_PARTY_FILE_HASHES, dir))
    .map((dir) => `${dir} (${HOST_STACKS_DIR}/${dir}.json, ${HOST_USER_STACKS_DIR}/${dir}.json, plugin sdd-kit-${dir}): ${FIRST_PARTY_FILE_HASHES[dir]}`)
    .join('; ')
}

// Appended to every Detect prompt; the discovery recipe itself lives in the code-explorer agent.
// First-party copies come back as a hash, not their text: their content is inlined here already, and
// echoing it would cost thousands of output tokens on every run.
function stackDiscoveryPrompt() {
  const firstParty = firstPartyHashLine()
  const hashRule = firstParty
    ? ` For a first-party location inside the project, hash the file first with \`${MANIFEST_HASH_COMMAND} <file>\`; when the hash equals the one listed for that add-on, return {source, sha256} and no raw. Expected hashes: ${firstParty}. A first-party location outside the project, or one whose hash differs or cannot be computed, returns raw like any other manifest.`
    : ''
  return `STACK MANIFESTS — follow your stack discovery recipe and also return: stackManifests (one item per manifest you found: source as project:${HOST_STACKS_DIR}/<file>, user:${HOST_USER_STACKS_DIR}/<file> or plugin:<name>@<marketplace> (plugin:<name>@inline for a --plugin-dir plugin), raw = the file text, unmodified.${hashRule}), trustStore (the verbatim text of ${HOST_TRUST_STORE_DIR}/trusted-stacks.json, where <home> is the home directory your recipe reads from the OS user database, never $HOME or CLAUDE_CONFIG_DIR; null or omitted when the file is absent; null or omitted plus "trustStore unreadable" in discovery.errors when <home> cannot be resolved or the Read is refused or fails), and discovery {mode, method, errors}. Outside the project use only the Read and Glob tools, on literal absolute paths under the <config> directory and the ${HOST_TRUST_STORE_DIR} directory your recipe resolves: never cat, ls or find there, and no Bash command with a variable in braces.${workdirOutsideRule()} A refused read goes into discovery.errors ("trustStore unreadable", "user stacks unreadable", "plugin list unreadable") and is never treated as trusted. A repo that matches no catalog stack but matches a manifest's detect text takes that manifest's name as stack. For each repo and each gate of its stack that lists unless globs, add {gate, glob} to unlessMatched for every glob that matches a file or directory in that repo (${UNLESS_GLOB_RULE}). TRUST — run a discovered manifest's own commands (its running check, and test -e through its exec wrapper) only when its canonical sha256, computed with \`${MANIFEST_HASH_COMMAND} <file>\`, appears in the trustStore text you read; for any other manifest report only host-side reads (marker presence and unless matches). OVERLAY FACTS — for each such trusted manifest that declares extends: <key>, add to every repo of stack <key> an overlayFacts.<manifest name> object {execWrapper, reportedDevHosts, missingTools, unlessMatched}, answered for that manifest's own fields.${execWrapperDetectLine()}${gateGuardDetectLine()}

${REPO_PATH_RULE}`
}

// Local development hosts only: localhost, the loopback addresses, and *.localhost, *.test and every first-party
// devUrlHosts suffix. A suffix needs at least one label before it; labels may use any case, suffixes are lower case.
const DEV_URL_SUFFIXES = ['localhost', 'test', ...DEV_URL_HOSTS]
// Port, plain path and a query string. The query set holds no space, quote, backtick, $, ;, &, <, > or #, so a
// dev URL cannot break out of the quoted text of a prompt or chain a second command when an agent pastes it
// into a shell line.
const DEV_URL_TAIL = '(?::\\d{1,5})?(?:\\/[A-Za-z0-9._~/-]*)?(?:\\?[A-Za-z0-9._~=%/-]*)?$'
const DEV_URL_PATTERN = new RegExp(
  `^https?:\\/\\/(?:localhost|127\\.0\\.0\\.1|\\[::1\\]|(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\\.)+(?:${DEV_URL_SUFFIXES.map(escapeRegex).join('|')}))${DEV_URL_TAIL}`
)
// A hostname a repo's running check reported through its manifest's devUrlFields: two or more DNS labels.
const REPORTED_HOST_PATTERN = /^(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$/
// A dev URL on such a host; group 1 is the hostname, matched against the repo's reported hosts.
const REPORTED_HOST_URL_PATTERN = new RegExp(`^https?:\\/\\/(${REPORTED_HOST_PATTERN.source.slice(1, -1)})${DEV_URL_TAIL}`)
// Private and reserved top-level names (RFC 2606, RFC 6761, RFC 6762 appendix G, RFC 8375, ICANN .internal).
// A reported host widens the dev-URL rule only when it ends in one of them or in a dev URL suffix; any other host,
// such as an extra FQDN on a public or country-code TLD (staging.example.com, shop.co.uk) or an IP address, is dropped.
const PRIVATE_TLDS = ['internal', 'local', 'lan', 'home.arpa', 'localhost', 'test', 'example', 'invalid', 'intranet', 'private', 'corp', 'home']
// The same host set as prose, for prompts, logs and Fix text.
const DEV_URL_HOST_TEXT = `localhost, 127.0.0.1, [::1] or a ${DEV_URL_SUFFIXES.map((h) => `*.${h}`).join(', ').replace(/, ([^,]*)$/, ' or $1')} host`
// How Detect reports repo paths and dev URLs so that resolveDetect keeps them (isRepoPath, isDevUrl).
const REPO_PATH_RULE = `REPO PATHS — report each repo's path relative to the current directory ("." for the current directory itself), using only letters, digits, ".", "_", "/" and "-", with no ".." segment and no leading "-". A repo outside the current directory is reported only when the caller hinted its root, and then with that hint verbatim. Any other path drops the repo. devUrl must be an http(s) URL on ${DEV_URL_HOST_TEXT}, or on a host in that repo's reportedDevHosts (optional port, plain path and query string); any other devUrl is dropped.`

/**
 * Runs the Detect agent call, turning a throw into a failure message instead of ending the workflow.
 * @param {string} prompt the Detect prompt
 * @param {object} opts options for runAgent
 * @returns {Promise<{ project: object|null, failure: string|null }>}
 */
async function detectStacks(prompt, opts) {
  log(`SDD Kit ${KIT_VERSION}`)
  try {
    return { project: await runAgent(prompt, opts), failure: null }
  } catch (e) {
    return { project: null, failure: (e && e.message) || String(e) }
  }
}

/**
 * Turns Detect's raw result into the repos a workflow runs on and merges the stack overlay.
 * Never re-runs Detect: a failure, a null result or zero repos all end in the single fallback repo.
 * @param {object|null} project Detect's result, null when it failed
 * @param {{ failure?: string, listKey?: string, fallback?: object }} [opts] failure: message when Detect threw; listKey: the repo list property (default "repos"); fallback: the repo used when none were detected
 * @returns {{ list: object[], stackOverlay: object, untrusted: object[] }}
 */
function resolveDetect(project, opts) {
  const o = opts || {}
  const listKey = o.listKey || 'repos'
  const data = project && typeof project === 'object' ? project : null
  const failure = o.failure || (data ? null : 'Detect returned no result')
  const discovery = { mode: 'unknown', method: 'none', errors: [] }
  const found = data && data.discovery && typeof data.discovery === 'object' ? data.discovery : null
  if (found) {
    if (DISCOVERY_MODES.includes(found.mode)) discovery.mode = found.mode
    if (DISCOVERY_METHODS.includes(found.method)) discovery.method = found.method
    if (Array.isArray(found.errors)) discovery.errors = safeTexts(found.errors, 'Detect discovery errors')
  }
  if (failure) {
    discovery.mode = 'none'
    discovery.method = 'none'
    discovery.errors = [`Detect failed: ${failure}`]
  }
  discoveryMode = discovery.mode
  const roots = callerRoots(o.roots)
  let list = (data && Array.isArray(data[listKey]) ? data[listKey] : []).filter((r) => {
    if (r && typeof r === 'object' && isRepoPath(r.path, roots)) return true
    const shown = r && typeof r === 'object' && typeof r.path === 'string' ? JSON.stringify(r.path.slice(0, 80)) : '(none)'
    log(`Repo dropped: path ${shown} is not a relative path inside the workspace. Fix: run from a directory that contains every repo, or pass the repo roots in args.repos.`)
    return false
  })
  if (!list.length) {
    if (!failure) discovery.errors.push('Detect returned no repos')
    list = [o.fallback || { role: 'fullstack', path: '.', stack: 'other', gateCommands: [] }]
  }
  const manifests = data && Array.isArray(data.stackManifests) ? data.stackManifests : []
  // A store Detect calls unreadable approves nothing, whatever text came back with it. The store lives in the OS
  // home directory, not the config directory, so a config directory inside the project does not affect it.
  const storeRefused = discovery.errors.includes('trustStore unreadable')
  const merged = mergeOverlay(manifests, !storeRefused && data && typeof data.trustStore === 'string' ? data.trustStore : null)
  if (merged.storeUnreadable && !discovery.errors.includes('trustStore unreadable')) discovery.errors.push('trustStore unreadable')
  installOverlay(merged)

  const stackOverlay = {
    discovery: { mode: discovery.mode, method: discovery.method, count: manifests.length, errors: discovery.errors },
    present: merged.present,
    added: merged.added,
    ignored: merged.ignored,
    rejected: merged.rejected,
  }
  log(`Stacks: discovery ${discovery.method}, ${manifests.length} manifest(s), ${discovery.errors.length} error(s); added: ${merged.added.map((a) => a.key).join(', ') || 'none'}; ignored: ${merged.ignored.length}; rejected: ${merged.rejected.length}`)
  merged.logs.forEach((line) => log(line))
  merged.untrusted.filter((u) => !u.extends).forEach((u) => log(`Stack manifest untrusted: ${u.source} (${u.keys.join(', ')}) — its gates will not run, and its steps run as the default agent with no stack skills (its specialist agent and skills are not used). Fix: run /stack-trust.`))
  return { list: list.map((r) => resolveRepo(r)), stackOverlay, untrusted: merged.untrusted }
}

// --- Detect values: everything a prompt or a command quotes passes a strict pattern -----
// Detect and scaffold agents read repository content, so every value they report is checked before a
// prompt or command quotes it. An invalid value is dropped and logged, never quoted.

const REPO_ROLES = ['backend', 'frontend', 'fullstack', 'mobile']
const REPO_PATH_PATTERN = /^[A-Za-z0-9._/-]{1,200}$/
// Prose Detect reports (conventions, warnings, blockers): words and plain punctuation, no quotes, shell
// operators, substitutions or redirections.
const SAFE_TEXT_PATTERN = /^[\p{L}\p{N} .,:()/_+*@#%=–—-]{1,200}$/u
const MAX_TEXT_ITEMS = 20
const NOT_RUN_NO_GATE = 'not run (no allowlisted gate'

/**
 * Whether a repo path Detect reported may be quoted into a prompt or command: relative, inside the
 * workspace (no ".." segment), [A-Za-z0-9._/-] only and no leading "-"; or exactly a repo root the caller
 * passed in args.repos, which defines the workspace for a polyrepo run.
 * @param {unknown} p the reported path
 * @param {Set<string>} [roots] caller repo roots (callerRoots)
 * @returns {boolean}
 * @example isRepoPath('web') // true
 * @example isRepoPath('web" && touch x') // false
 * @example isRepoPath('../web', callerRoots({ frontend: '../web' })) // true
 */
function isRepoPath(p, roots) {
  if (typeof p !== 'string' || !REPO_PATH_PATTERN.test(p) || p.startsWith('-')) return false
  if (roots && roots.has(p)) return true
  return !p.startsWith('/') && !p.split('/').includes('..')
}

/**
 * The tracker key a workflow may put into a branch name, a folder or file name, or shell text: an uppercase
 * Jira-style key (PROJ-123) of at most 64 characters, so it holds no shell metacharacter or path separator
 * and stays a valid ref name. Anything else gives ''.
 * @param {unknown} value the ticket the caller passed or the run read
 * @returns {string} the key, or '' when it is not a safe key
 * @example ticketKey('PROJ-123') // 'PROJ-123'
 * @example ticketKey('proj-123') // ''
 * @example ticketKey('PROJ-1; rm -rf ~') // ''
 */
function ticketKey(value) {
  return typeof value === 'string' && value.length <= 64 && /^[A-Z][A-Z0-9_]+-\d+$/.test(value) ? value : ''
}

/**
 * How a workflow resolves a spec reference to one folder under .ai/specs/: the rule the ship-feature loader
 * and qa-and-docs share, as prompt text with the lookup command.
 * @param {string} ref a reference that passed specRefValue, so it is safe inside the double-quoted shell value
 * @returns {string}
 */
function specRefLookupText(ref) {
  return `Accept: a full folder name or path; a legacy numeric id ("0042", "spec-0042", "14" → folders spec-0042-* or 14-*, leading zeros ignored); a ticket key ("PROJ-123" → spec-PROJ-123-*, case-insensitive); a timestamp id ("20261018-1430" → spec-20261018-1430-*). E.g.:
   REF="${ref}"; REF="\${REF#.ai/specs/}"; REF="\${REF%/}"; KEY="\${REF#spec-}"
   [ -d ".ai/specs/$REF" ] || { echo "$KEY" | grep -qE '^[0-9]+$' && ls -d .ai/specs/*/ | grep -E "/(spec-)?0*$((10#$KEY))-" || ls -d .ai/specs/*/ | grep -iE "/(spec-)?$KEY-"; }`
}

/**
 * A spec reference (folder name or path, numeric id, ticket key or timestamp id) that is safe to place in
 * shell text: letters, digits, ".", "_", "-" and "/" (128 characters after an optional ".ai/specs/" prefix),
 * starting with a letter or digit, with no ".." segment. Anything else gives ''.
 * @param {unknown} value the caller's { spec }
 * @returns {string} the reference, or '' when it is not safe
 * @example specRefValue('20261018-1430') // '20261018-1430'
 * @example specRefValue('x"; touch /tmp/pwn; "') // ''
 */
function specRefValue(value) {
  const text = typeof value === 'number' ? String(value) : value
  return typeof text === 'string' && /^(?:\.ai\/specs\/)?[A-Za-z0-9][A-Za-z0-9._/-]{0,127}$/.test(text) && !text.split('/').includes('..') ? text : ''
}

/**
 * A file-name or branch slug computed in script: lowercase, every run of other characters turned into "-",
 * cut to `max` characters at a hyphen.
 * @param {string} text
 * @param {number} [max]
 * @returns {string} '' when the text has no letters or digits
 * @example toSlug('Postgres vs. Mongo?')  // 'postgres-vs-mongo'
 */
function toSlug(text, max = 40) {
  let slug = String(text == null ? '' : text).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')
  if (slug.length > max) {
    const cut = slug.slice(0, max)
    slug = slug[max] === '-' || cut.lastIndexOf('-') === -1 ? cut : cut.slice(0, cut.lastIndexOf('-'))
    slug = slug.replace(/-+$/, '')
  }
  return slug
}

/**
 * The one ADR-naming instruction of every workflow that writes an ADR: the next free four-digit number (the
 * doc-hygiene ordered.adr convention), a slug the script computes, and a no-overwrite write.
 * @param {string} dir the ADR directory, or a placeholder the prompt defines
 * @param {string} topic text the slug is made from (the decision question or the project idea)
 * @returns {string}
 */
function adrNamingInstruction(dir, topic) {
  const slug = toSlug(topic) || 'decision'
  return `Name: NNNN = the highest four-digit number among the existing ${dir}/NNNN-*.md files plus one, zero-padded to four digits (0001 when there is none). SLUG=${slug} (use it exactly as given). DATE=$(date +%Y-%m-%d); existing ADR files keep their names and ids.
File: ${dir}/$NNNN-$SLUG.md (lowercase). Create it with a no-overwrite write (set -o noclobber; cat > "$FILE" <<'EOF' ... EOF, or open with O_EXCL); when another ADR already took that number, take the next number and retry. Never overwrite or renumber an existing file.
Heading: the first line is "# ADR <id>: <title>", where <id> is $NNNN and <title> is the decision in a few words.`
}

/**
 * The work branch a run switches to when it starts on a protected branch. Computed in script, never by an
 * agent, so no agent text reaches a git argument.
 *
 * The slug is the spec folder name without "spec-", the YYYYMMDD-HHMM- timestamp and a leading
 * ticket key, lowercased, with every run of other characters turned into "-", and cut to 40
 * characters at a hyphen. Without a folder, the same rule runs on the fallback text.
 *
 * @param {'feature'|'fix'} prefix  branch prefix
 * @param {string|null} folder      spec folder path or name; null when there is none
 * @param {string|null} key         ticket key; used only when it matches PROJ-123 form
 * @param {string} [fallback]       text to slug when there is no folder (the feature or bug description)
 * @returns {string|null}  "<prefix>/<KEY>-<slug>", "<prefix>/<slug>", or null when nothing usable is left
 * @example workBranchName('feature', '.ai/specs/spec-20261112-1058-kit-limits', 'PROJ-7')  // 'feature/PROJ-7-kit-limits'
 * @example workBranchName('fix', null, 'PROJ-7', 'Cart total is wrong')                    // 'fix/PROJ-7-cart-total-is-wrong'
 */
function workBranchName(prefix, folder, key, fallback) {
  const validKey = ticketKey(key)
  let base = folder ? String(folder).split('/').filter(Boolean).pop() || '' : String(fallback || '')
  if (folder) base = base.replace(/^spec-/, '').replace(/^\d{8}-\d{4}-/, '')
  let slug = toSlug(base, Infinity)
  const keySlug = validKey ? `${toSlug(validKey, Infinity)}-` : ''
  if (keySlug && slug.startsWith(keySlug)) slug = slug.slice(keySlug.length)
  slug = toSlug(slug)
  const name = validKey ? (slug ? `${prefix}/${validKey}-${slug}` : `${prefix}/${validKey}`) : slug ? `${prefix}/${slug}` : null
  return name && new RegExp(`^${prefix}/[A-Za-z0-9._-]+$`).test(name) ? name : null
}

/**
 * Whether a branch is protected without a git call: a detached HEAD (""), main, master, develop,
 * release/*, or a name or glob the Prepare agent read from SDD_KIT_PROTECTED_BRANCHES. In a glob
 * `*` matches any characters including "/" and `?` one character. The origin default branch is known
 * only inside the repo, so the agent reports it as `protected`.
 *
 * @param {string} branch    output of git branch --show-current
 * @param {string[]} [extra] names or globs reported as extraProtected
 * @returns {boolean}
 * @example isProtectedBranch('release/a/b')            // true
 * @example isProtectedBranch('staging', ['stag*'])     // true
 */
function isProtectedBranch(branch, extra = []) {
  const b = String(branch || '').trim()
  if (b === '' || b === 'main' || b === 'master' || b === 'develop' || b.startsWith('release/')) return true
  const globs = (Array.isArray(extra) ? extra : []).flatMap((entry) => String(entry ?? '').split(/[\s,]+/)).filter(Boolean)
  return globs.some((glob) => globRegExp(glob).test(b))
}

/**
 * A bash `case` pattern as an anchored regex: `*` matches any characters including "/", `?` one
 * character, and `[...]` a bracket expression (`[!x]` or `[^x]` negated, a leading `]` literal). An
 * unclosed `[` is a literal, as in bash. block-dangerous.sh matches the same globs with `case`.
 * @param {string} glob
 * @returns {RegExp}
 * @example globRegExp('release-[0-9]*').test('release-2.1')  // true
 */
function globRegExp(glob) {
  const escape = (c) => c.replace(/[.+^${}()|[\]\\*?\/-]/g, '\\$&')
  let out = ''
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i]
    if (c === '*') out += '.*'
    else if (c === '?') out += '.'
    else if (c === '[') {
      let j = i + 1
      const negated = glob[j] === '!' || glob[j] === '^'
      if (negated) j++
      if (glob[j] === ']') j++
      while (j < glob.length && glob[j] !== ']') j++
      if (j >= glob.length) {
        out += '\\['
        continue
      }
      const body = glob.slice(i + 1 + (negated ? 1 : 0), j).replace(/[\\\]^]/g, '\\$&')
      out += `[${negated ? '^' : ''}${body}]`
      i = j
    } else out += escape(c)
  }
  return new RegExp(`^${out}$`)
}

/**
 * Prompt text that defines a protected branch for an agent: the built-in set plus the names and globs
 * in the SDD_KIT_PROTECTED_BRANCHES environment variable (spaces or commas). The variable only adds branches.
 */
const PROTECTED_BRANCH_RULE = 'The branch is protected when HEAD is detached, or it is main, master, develop, release/<anything>, or the default branch. It is also protected when it matches a name or glob in the output of printenv SDD_KIT_PROTECTED_BRANCHES (entries split on spaces or commas, blanks ignored, * matches any characters including /; empty or unset adds nothing)'

/**
 * The feature branch of ship-feature.
 * @param {string|null} folder  spec folder path or name; null when no spec was persisted
 * @param {string|null} key     ticket key
 * @param {string} [fallback]   text to slug when there is no folder
 * @returns {string|null}
 * @example featureBranchName('.ai/specs/spec-PROJ-7-kit-limits', 'PROJ-7') // 'feature/PROJ-7-kit-limits'
 */
function featureBranchName(folder, key, fallback) {
  return workBranchName('feature', folder, key, fallback)
}

// The repo roots a caller passed (args.repos as an object or array of paths), limited to the path characters.
function callerRoots(hints) {
  const values = (Array.isArray(hints) ? hints : hints && typeof hints === 'object' ? Object.values(hints) : []).map((v) => (v && typeof v === 'object' ? v.path : v))
  return new Set(values.filter((v) => typeof v === 'string' && REPO_PATH_PATTERN.test(v) && !v.startsWith('-')))
}

/**
 * Whether a dev server URL may be quoted: http(s) on a local development host, or on exactly one of the hosts the
 * repo's own running check reported (reportedHostsFor), with an optional port, plain path and query string.
 * @param {unknown} url the URL
 * @param {string[]} [repoHosts] the reportedDevHosts of the repo the URL is for, lower case
 * @returns {boolean}
 * @example isDevUrl('https://shop.test/user/login?destination=/node') // true
 * @example isDevUrl('https://shop.internal', ['shop.internal']) // true
 * @example isDevUrl('https://other.internal', ['shop.internal']) // false
 */
function isDevUrl(url, repoHosts) {
  if (typeof url !== 'string' || url.length > 200) return false
  if (DEV_URL_PATTERN.test(url)) return true
  const m = Array.isArray(repoHosts) && repoHosts.length ? REPORTED_HOST_URL_PATTERN.exec(url) : null
  return !!m && repoHosts.includes(m[1].toLowerCase())
}

/**
 * The hosts a repo's running check reported through its manifest's execWrapper.requiresRunning.devUrlFields,
 * kept only when the manifest is first-party or trusted, declares the field, and the check passed. A host must
 * have two or more DNS labels and end in a PRIVATE_TLDS name or a dev URL suffix; the rest are dropped and logged.
 * @param {object} r the reported repo
 * @param {string} stack its resolved stack key
 * @param {boolean} declined whether the stack comes from a manifest this run does not use
 * @returns {string[]} lower-case hostnames, at most MAX_TEXT_ITEMS
 * @example reportedHostsFor({ path: '.', execWrapper: { present: true, running: true }, reportedDevHosts: ['Site.internal', 'staging.example.com'] }, 'acme', false) // ['site.internal'] when acme's running check declares devUrlFields
 */
function reportedHostsFor(r, stack, declined) {
  const declared = devUrlFieldsOf(traitsFor(stack).execWrapper).length > 0
  const ran = r.execWrapper && typeof r.execWrapper === 'object' && r.execWrapper.present === true && r.execWrapper.running === true
  if (!Array.isArray(r.reportedDevHosts) || declined || isUntrustedStack(stack) || !declared || !ran) return []
  const where = r.path || '.'
  const hosts = []
  const publicHosts = []
  let invalid = 0
  const isPrivate = (h) => [...PRIVATE_TLDS, ...DEV_URL_SUFFIXES].some((tld) => h.endsWith(`.${tld}`))
  for (const h of r.reportedDevHosts) {
    if (typeof h !== 'string' || h.length > 253 || !REPORTED_HOST_PATTERN.test(h)) invalid++
    else if (!isPrivate(h.toLowerCase())) publicHosts.push(h)
    else if (!hosts.includes(h.toLowerCase())) hosts.push(h.toLowerCase())
  }
  if (publicHosts.length) log(`Reported dev hosts dropped for ${where}: ${publicHosts.slice(0, 5).join(', ')} are not on a private development TLD (${PRIVATE_TLDS.join(', ')}). Fix: open that site by a host on one of them or ${DEV_URL_HOST_TEXT}`)
  if (invalid) log(`Reported dev hosts dropped for ${where}: ${invalid} value(s) are not hostnames.`)
  if (hosts.length > MAX_TEXT_ITEMS) log(`Reported dev hosts for ${where}: ${hosts.length - MAX_TEXT_ITEMS} beyond the first ${MAX_TEXT_ITEMS} dropped.`)
  return hosts.slice(0, MAX_TEXT_ITEMS)
}

/**
 * The prose items of a Detect list that pass SAFE_TEXT_PATTERN, at most MAX_TEXT_ITEMS; the rest are logged.
 * @param {unknown} list reported strings
 * @param {string} label what the list is, for the log line
 * @returns {string[]}
 */
function safeTexts(list, label) {
  if (!Array.isArray(list)) return []
  const kept = list.filter((t) => typeof t === 'string' && SAFE_TEXT_PATTERN.test(t)).slice(0, MAX_TEXT_ITEMS)
  if (kept.length < list.length) log(`${label}: ${list.length - kept.length} item(s) dropped (quotes, shell syntax or too long).`)
  return kept
}

/**
 * A package manager name a scaffold or Detect reported, kept only when the stack's first-party or trusted
 * manifest declares it in packageManagers.
 * @param {string} stack Stack key.
 * @param {unknown} name the reported name
 * @param {string} where repo path, for the log line
 * @returns {string} the name, or '' when it was dropped
 */
function declaredPackageManager(stack, name, where) {
  if (name === undefined || name === null || name === '') return ''
  if (packageManagersFor(stack).some((p) => p.name === name)) return name
  log(`Package manager dropped for ${where}: ${JSON.stringify(String(name).slice(0, 40))} is not declared by the ${stack} manifest.`)
  return ''
}

// The reported gate names that the stack's manifest gives the field (requires, lintFix, scriptFallback).
function declaredGateNames(stack, names, field) {
  const gates = extrasFor(stack).gates || {}
  return (Array.isArray(names) ? names : []).filter((n) => typeof n === 'string' && hasOwn(gates, n) && gates[n][field] !== undefined)
}

// The reported unmet requires entries, kept only for gates with a requires list and only for entries that list declares, in its order.
function declaredMissingRequires(stack, reported) {
  const gates = extrasFor(stack).gates || {}
  const seen = new Set()
  const out = []
  for (const m of Array.isArray(reported) ? reported : []) {
    if (!m || typeof m.gate !== 'string' || !hasOwn(gates, m.gate) || !Array.isArray(gates[m.gate].requires) || seen.has(m.gate) || !Array.isArray(m.entries)) continue
    const entries = gates[m.gate].requires.filter((e) => m.entries.some((r) => sameRequiresEntry(e, r)))
    if (!entries.length) continue
    seen.add(m.gate)
    out.push({ gate: m.gate, entries })
  }
  return out
}

/**
 * The gates of the effective registry that declare a guard field, as "<stack> gate <name> (<detail>)".
 * @param {string} field requires, lintFix or scriptFallback
 * @param {(value: object) => string} detail renders the field's value
 * @returns {string[]}
 */
function guardedGates(field, detail) {
  const out = []
  for (const k of Object.keys(STACK_EXTRAS)) {
    const gates = STACK_EXTRAS[k].gates || {}
    for (const name of Object.keys(gates)) if (gates[name][field] !== undefined) out.push(`${k} gate ${name} (${detail(gates[name][field])})`)
  }
  return out
}

// How Detect probes a requires path; the trust-store plan step probes the same way.
const WRAPPER_PROBE_RULE = 'check it through the exec wrapper (the repo\'s execWrapper command, then test -e <path>) only when execWrapper.present is true and either the manifest declares no running check or execWrapper.running is true, otherwise with test -e <path> in the repo; a wrapper that is not running is never used'

// WRAPPER_PROBE_RULE, plus the workdir flag for a nested repo when a manifest declares workdir.
function wrapperProbeRule() {
  if (!workdirStacks().length) return WRAPPER_PROBE_RULE
  return `${WRAPPER_PROBE_RULE}; for a wrapper with workdir and an execWrapper.dir other than ".", put the workdir flag and <root>/<dir> between the command and test -e`
}

// The BINARY CHECK sentence for the list form of requires; '' while no manifest uses it.
function binaryCheckListRules() {
  const lists = Object.keys(STACK_EXTRAS).some((k) => Object.values(STACK_EXTRAS[k].gates || {}).some((g) => Array.isArray(g.requires)))
  return lists ? ' A requires list is unmet when any entry is unmet; an entry that is a list of paths is met when at least one of its paths exists. For a gate with an unmet requires list, also add {gate, entries} to missingRequires, where entries are its unmet entries exactly as the manifest writes them.' : ''
}

/**
 * The binary-check, lint-fix and script-fallback questions Detect answers per repo. The prompt is built
 * before the manifests Detect discovers are merged, so each question also covers the same field in a
 * discovered manifest; cleanRepoFields keeps only the gate names the merged, trusted registry declares it on.
 * @returns {string}
 */
function gateGuardDetectLine() {
  const known = (list) => (list.length ? `${list.join('; ')}; a discovered manifest's gates declare their own` : `as a discovered manifest's gates declare it`)
  const rules = guardedGates('requires', requiresDetectText)
  const fixes = guardedGates('lintFix', (v) => `flag ${v.flag}`)
  const majors = guardedGates('scriptFallback', (v) => `${v.dependency} from ${v.manifest}, major ${v.minMajor} or later, script containing "${v.contains}"`)
  return [
    ` BINARY CHECK — for each repo and gate that declares requires (${known(rules)}), add the gate name to missingTools when that file does not exist in the repo; ${wrapperProbeRule()}.${binaryCheckListRules()}`,
    ` MUTATING LINT — for each repo and gate that declares a lintFix flag (${known(fixes)}), add the gate name to mutatingGates when the repo's script for that gate contains the flag.`,
    ` DEPENDENCY MAJOR — for each repo and gate that declares a scriptFallback (${known(majors)}), add {dependency, major} to dependencyMajors, where major is the lowest major version (an integer) that the version range declared for that dependency in the named manifest file of the repo admits; leave the dependency out when that range cannot be read. Add the gate name to legacyScriptGates when the repo's script for that gate contains the quoted text.`,
  ].join('')
}

// The reported dependency majors for dependencies a scriptFallback of the stack's manifest names, one per dependency.
function declaredMajors(stack, majors) {
  const gates = extrasFor(stack).gates || {}
  const deps = new Set(Object.keys(gates).filter((n) => gates[n].scriptFallback !== undefined).map((n) => gates[n].scriptFallback.dependency))
  const seen = new Set()
  return (Array.isArray(majors) ? majors : []).filter((m) => {
    if (!m || typeof m.dependency !== 'string' || !deps.has(m.dependency) || seen.has(m.dependency) || !Number.isInteger(m.major) || m.major < 0) return false
    seen.add(m.dependency)
    return true
  }).map((m) => ({ dependency: m.dependency, major: m.major }))
}

// The unless matches whose gate and glob the stack's manifest declares, in the manifest's unless order, so a
// gate's skip text names the same glob whatever order Detect reported them in.
function declaredUnless(stack, matched) {
  const gates = (hasOwn(STACK_EXTRAS, stack) && STACK_EXTRAS[stack].gates) || {}
  const rank = (m) => gates[m.gate].unless.indexOf(m.glob)
  return (Array.isArray(matched) ? matched : []).filter((m) => m && hasOwn(gates, m.gate) && (gates[m.gate].unless || []).includes(m.glob)).sort((a, b) => rank(a) - rank(b))
}

// How an unless glob matches, as Detect is told it; unlessGlobMatches implements it for the plan step.
const UNLESS_GLOB_RULE = 'a glob is relative to the repo root; * and ? match within one path segment'

/**
 * Whether an unless glob matches a file or directory of a repo, by UNLESS_GLOB_RULE. The runtime reads no
 * files itself, so the caller lists directories.
 * @param {string} glob an unless entry, for example "lint.config.*" or "config/*.json"
 * @param {(dir: string) => string[]|null} entries the entry names of a repo-relative directory ('' is the root), null when it is not one
 * @returns {boolean}
 * @example unlessGlobMatches('lint.config.*', (dir) => (dir === '' ? ['lint.config.json'] : null)) // true
 */
function unlessGlobMatches(glob, entries) {
  const parts = glob.split('/').filter((p) => p !== '' && p !== '.')
  const walk = (dir, i) => {
    const names = entries(dir)
    if (!names) return false
    const re = new RegExp(`^${parts[i].replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*').replace(/\?/g, '.')}$`)
    const hits = names.filter((n) => re.test(n))
    return i === parts.length - 1 ? hits.length > 0 : hits.some((n) => walk(dir ? `${dir}/${n}` : n, i + 1))
  }
  return parts.length > 0 && walk('', 0)
}

/**
 * The fields of a Detect repo that workflows use, each validated for the repo's resolved stack. Unknown
 * fields are dropped, so a prompt that quotes the repo quotes only checked values.
 * @param {object} r the reported repo
 * @param {string} stack its resolved stack key
 * @param {boolean} declined whether the stack comes from a manifest this run does not use
 * @returns {object}
 */
function cleanRepoFields(r, stack, declined) {
  const where = r.path || '.'
  const out = { role: REPO_ROLES.includes(r.role) ? r.role : 'fullstack', path: r.path || '.' }
  if (r.role !== undefined && out.role !== r.role) log(`Repo role dropped for ${where}: ${JSON.stringify(String(r.role).slice(0, 40))} is not ${REPO_ROLES.join(', ')}.`)
  for (const flag of ['tracked', 'e2eConfig', 'empty', 'hasTrackedFiles']) if (typeof r[flag] === 'boolean') out[flag] = r[flag]
  const pm = declaredPackageManager(stack, r.packageManager, where)
  if (pm) out.packageManager = pm
  if (r.execWrapper && typeof r.execWrapper === 'object' && typeof r.execWrapper.present === 'boolean') {
    out.execWrapper = { present: r.execWrapper.present }
    if (typeof r.execWrapper.running === 'boolean') out.execWrapper.running = r.execWrapper.running
    // dir is the one Detect value that reaches a command line (the workdir argument), so it must be a plain relative path.
    const dir = r.execWrapper.dir
    if (dir !== undefined) {
      const declared = traitsFor(stack).execWrapper
      if (declared && declared.workdir && isRepoPath(dir)) out.execWrapper.dir = dir
      else {
        log(`execWrapper dir ${JSON.stringify(String(dir).slice(0, 40))} dropped for ${where}. Fix: report a plain relative dir, or declare execWrapper.workdir in the ${stack} manifest`)
        if (declared && declared.workdir) out.execWrapper.dirUnusable = true
      }
    }
  }
  const hosts = reportedHostsFor(r, stack, declined)
  if (hosts.length) out.reportedDevHosts = hosts
  if (isDevUrl(r.devUrl, hosts)) out.devUrl = r.devUrl
  else if (r.devUrl !== undefined && r.devUrl !== '') log(`devUrl dropped for ${where}: ${JSON.stringify(String(r.devUrl).slice(0, 80))} is not an http(s) URL on ${DEV_URL_HOST_TEXT}.`)
  const ownStack = !declined && !isUntrustedStack(stack)
  if (hasOwn(r, 'conventions')) out.conventions = ownStack ? safeTexts(r.conventions, `Conventions for ${where}`) : []
  if (hasOwn(r, 'warnings')) out.warnings = safeTexts(r.warnings, `Warnings for ${where}`)
  if (hasOwn(r, 'unlessMatched')) out.unlessMatched = declaredUnless(stack, r.unlessMatched)
  if (hasOwn(r, 'missingTools')) out.missingTools = declaredGateNames(stack, r.missingTools, 'requires')
  if (hasOwn(r, 'missingRequires')) out.missingRequires = declaredMissingRequires(stack, r.missingRequires)
  if (hasOwn(r, 'mutatingGates')) out.mutatingGates = declaredGateNames(stack, r.mutatingGates, 'lintFix')
  if (hasOwn(r, 'dependencyMajors')) out.dependencyMajors = declaredMajors(stack, r.dependencyMajors)
  if (hasOwn(r, 'legacyScriptGates')) out.legacyScriptGates = declaredGateNames(stack, r.legacyScriptGates, 'scriptFallback')
  return out
}

/**
 * Moves a repo of an extended first-party stack onto the trusted overlay that extends it. The overlay's
 * own Detect facts replace the repo's. A declared execWrapper with no reported wrapper fact counts as
 * present and not running, so its gates skip instead of running unwrapped; an inherited one keeps the
 * repo's first-party fact.
 * @param {object} r the repo as Detect reported it
 * @returns {object} the repo with the overlay key as its stack, or r itself
 */
function applyExtends(r) {
  if (typeof r.stack !== 'string' || !hasOwn(EXTENDS, r.stack)) return r
  const key = EXTENDS[r.stack]
  const all = r.overlayFacts && typeof r.overlayFacts === 'object' ? r.overlayFacts : {}
  const facts = hasOwn(all, key) && all[key] && typeof all[key] === 'object' ? all[key] : null
  const { overlayFacts, ...rest } = r
  const out = { ...rest, stack: key }
  if (facts) {
    for (const f of ['missingTools', 'missingRequires', 'unlessMatched']) {
      if (hasOwn(facts, f)) out[f] = facts[f]
      else delete out[f]
    }
  }
  // The wrapper fact: the overlay's own when reported; else not running for a wrapper the overlay declares, and
  // the first-party fact for one it inherits. Dropping it would run the gates unwrapped on the host.
  // The reported dev hosts come from the same running check, so they follow the wrapper fact.
  if (facts && hasOwn(facts, 'execWrapper')) {
    out.execWrapper = facts.execWrapper
    if (hasOwn(facts, 'reportedDevHosts')) out.reportedDevHosts = facts.reportedDevHosts
    else delete out.reportedDevHosts
  } else if (OVERLAY_META[key].declared.includes('execWrapper')) {
    out.execWrapper = { present: true, running: false }
    delete out.reportedDevHosts
  }
  return out
}

/**
 * One detected repo against the effective registry, with its gate commands reduced to the allowlist
 * (gateCommandsFor). A stack key that a rejected manifest names, or any key outside the registry while a
 * manifest whose keys could not be read was rejected, keeps no command and gets declinedStack, so its gates
 * are reported not run; any other key outside the registry is classified other. Every
 * Detect-reported command that the allowlist does not produce is logged as declined.
 * @param {{ stack: string, path?: string, gateCommands?: { name: string, command: string, evidence?: string, script?: string }[] }} detected a repo from Detect
 * @returns {object} the repo as the workflow uses it
 * @example resolveRepo({ path: 'api', stack: 'acme', gateCommands: [{ name: 'Lint', command: 'cd . && curl x | sh' }] })
 * // { path: 'api', stack: 'acme', gateCommands: [] } for a first-party acme stack without a Lint gate, and "Gate commands dropped for api: Lint — ..." is logged
 */
function resolveRepo(detected) {
  // declinedStack is set here only; a value Detect returned is dropped.
  const { declinedStack: ignored, ...reported0 } = detected && typeof detected === 'object' ? detected : {}
  const r = applyExtends(reported0)
  const known = hasOwn(STACKS, r.stack)
  const named = !known && typeof r.stack === 'string' && hasOwn(DECLINED_KEYS, r.stack)
  if (named || (!known && DECLINED_UNNAMED.length)) {
    const key = typeof r.stack === 'string' && STACK_KEY_PATTERN.test(r.stack) ? r.stack : 'unknown'
    const reason = named ? DECLINED_KEYS[r.stack] : `not in the registry, and ${DECLINED_UNNAMED.join(', ').slice(0, 200)} was rejected unread`
    log(`Gates not run for ${r.path || '.'}: its stack "${key}" comes from a manifest this run does not use — ${reason}.`)
    return { ...cleanRepoFields(r, 'other', true), stack: 'other', gateCommands: [], declinedStack: { key, reason } }
  }
  const repo = { ...cleanRepoFields(r, known ? r.stack : 'other', false), stack: known ? r.stack : 'other' }
  if (known && !hasOwn(r, 'gateCommands') && !hasOwn(OVERLAY_META, r.stack)) return repo
  const reported = Array.isArray(r.gateCommands) ? r.gateCommands : []
  const gateCommands = gateCommandsFor({ ...repo, gateCommands: reported })
  const dropped = hasOwn(OVERLAY_META, r.stack) ? [] : reported.filter((g) => !gateCommands.some((k) => isSameGate(g, k)))
  if (dropped.length) {
    const allowed = repo.stack === 'other' ? 'a gate template of the other stack with its evidence file and script name' : `a gate of the ${repo.stack} catalog`
    log(`Gate commands dropped for ${r.path || '.'}: ${dropped.map(gateLabel).join(', ')} — declined, not ${allowed}.`)
  }
  return { ...repo, gateCommands }
}

// One line for the "Stack overlay" part of a report.
function stackOverlayLine(overlay, untrusted) {
  const names = (list) => list.map((x) => x.key).join(', ') || 'none'
  return `discovery ${overlay.discovery.method} (${overlay.discovery.mode}); added: ${overlay.added.map((x) => (x.extends ? `${x.key} extends ${x.extends}` : x.key)).join(', ') || 'none'}; ignored: ${overlay.ignored.length}; rejected: ${overlay.rejected.length}; untrusted: ${(untrusted || []).map((u) => u.keys.join(', ')).join(', ') || 'none'}`
}

/**
 * The untrusted manifests that hold the stack of a repo this run works on. Only these block a verdict;
 * any other untrusted manifest (an unused user overlay, an add-on for another stack) is reported for information.
 * @param {{ keys: string[] }[]} untrusted resolveDetect's untrusted list
 * @param {{ stack: string }[]} repos the detected repos or targets
 * @returns {object[]} the subset of `untrusted` that blocks
 */
function blockingUntrusted(untrusted, repos) {
  const stacks = new Set((repos || []).map((r) => r.stack))
  return (untrusted || []).filter((u) => !u.extends && u.keys.some((k) => stacks.has(k)))
}

// "Next:" line that every untrusted-manifest recommendation ends with; '' when nothing is untrusted.
const untrustedNext = (workflow, untrusted) => ((untrusted || []).length ? `Next: /stack-trust, then re-run ${workflow}.` : '')

// --- gates: the command allowlist, untrusted manifests and unless globs -----
// A gate command runs only when the registry produces it: (a) the inlined catalog of a first-party stack,
// (b) the approved manifest of a trusted overlay, or (c) for `other`, a gate template of the core other
// manifest rendered with a script name Detect found in the template's evidence file. Detect's text only
// selects among these; it never becomes a command itself.

// Script or target names a gate template accepts: no whitespace, quotes or shell syntax, no leading dash.
const GATE_SCRIPT_PATTERN = /^[A-Za-z0-9][A-Za-z0-9:._-]{0,63}$/
const CONTRACT_SYNC_COMMAND = 'node scripts/contract-sync.mjs'
const CONTRACT_SYNC_SCRIPTS = ['contract-sync', 'contract:sync']

const trimmed = (v) => (typeof v === 'string' ? v.trim() : '')
const gateLabel = (g) => JSON.stringify(trimmed(g && g.name).slice(0, 60) || '?')
const isSameGate = (reported, kept) => !!reported && (trimmed(reported.command) === kept.command || trimmed(reported.name).toLowerCase() === kept.name.toLowerCase())

// The gate templates of the core other manifest: { evidence, command } with {script} in the command.
function gateTemplates() {
  return (hasOwn(STACK_EXTRAS, 'other') && STACK_EXTRAS.other.gateTemplates) || []
}

const renderGateTemplate = (template, script) => template.command.split('{script}').join(script)

// The gate templates as one prompt fragment: "<evidence> → <command>; ...".
function gateTemplatesLine() {
  return gateTemplates().map((t) => `${t.evidence} → ${t.command}`).join('; ') || '(none)'
}

// How an agent reports a stack's gate commands so that the allowlist keeps them, for a prompt.
function gateReportRule(stack) {
  return stack === 'other'
    ? `each as {name, command, evidence, script} from these templates, any other command is dropped: ${gateTemplatesLine()}`
    : 'use the gate names and commands listed above verbatim, any other command is dropped'
}

/**
 * The gate an other repo runs for one Detect item, or null. The item must name a template's evidence file
 * and a script name that matches GATE_SCRIPT_PATTERN, and its command must equal that template rendered
 * with the script. The gate is named after the script and keeps its evidence, so planning it again keeps it.
 * @param {{ command?: string, evidence?: string, script?: string }} g a gate command Detect reported
 * @returns {{ name: string, command: string, evidence: string, script: string }|null}
 * @example templateGateCommand({ name: 'Lint', command: 'make lint', evidence: 'Makefile', script: 'lint' })
 * // { name: 'lint', command: 'make lint', evidence: 'Makefile', script: 'lint' }
 */
function templateGateCommand(g) {
  if (!g || typeof g.script !== 'string' || !GATE_SCRIPT_PATTERN.test(g.script)) return null
  const evidence = trimmed(g.evidence).replace(/^\.\//, '')
  const command = trimmed(g.command)
  const template = gateTemplates().find((t) => t.evidence === evidence && renderGateTemplate(t, g.script) === command)
  return template ? { name: g.script, command, evidence, script: g.script } : null
}

/**
 * The catalog gates of a first-party stack that Detect found, in catalog order, with <pm>/<pmx> filled from
 * the package manager Detect recorded (the stack's default when it recorded none it declares). A Detect
 * item selects a catalog gate by its name or by the catalog command (raw or filled); its own text is not kept.
 */
function catalogGateCommands(repo, reported) {
  const pms = packageManagersFor(repo.stack)
  const own = packageManagerFor(repo, false)
  const fill = own || pms[pms.length - 1] || null
  return STACKS[repo.stack].gates
    .filter((g) => {
      const forms = new Set([g.command.trim(), ...(own ? [own] : pms).map((pm) => fillPackageManager(g.command, pm).trim())])
      return reported.some((r) => r && (forms.has(trimmed(r.command)) || trimmed(r.name).toLowerCase() === g.name.toLowerCase()))
    })
    .map((g) => ({ name: g.name, command: fillPackageManager(g.command, fill) }))
}

/**
 * The gate commands a repo runs, from the allowlist only.
 * - A first-party stack: the catalog gates Detect found (catalogGateCommands).
 * - `other`: the gate templates Detect proved with an evidence file and script name (templateGateCommand).
 * - An overlay: none when untrusted; the approved manifest's gates when trusted, with <pm>/<pmx> filled from
 *   the package manager Detect recorded (the manifest's last, default, entry otherwise).
 * - A declined stack, or a stack outside the effective registry: none.
 * @param {{ stack: string, packageManager?: string, declinedStack?: object, gateCommands?: object[] }} repo
 * @returns {{ name: string, command: string, evidence?: string, script?: string }[]} evidence and script only for other
 */
function gateCommandsFor(repo) {
  if (!hasOwn(STACKS, repo.stack) || repo.declinedStack) return []
  if (hasOwn(OVERLAY_META, repo.stack)) {
    if (isUntrustedStack(repo.stack)) return []
    const pm = packageManagerFor(repo)
    return STACKS[repo.stack].gates.map((g) => ({ name: g.name, command: fillPackageManager(g.command, pm) }))
  }
  const reported = (Array.isArray(repo.gateCommands) ? repo.gateCommands : []).filter((g) => g && typeof g === 'object')
  if (repo.stack !== 'other') return catalogGateCommands(repo, reported)
  const out = []
  for (const g of reported) {
    const gate = templateGateCommand(g)
    if (gate && !out.some((k) => k.command === gate.command)) out.push(gate)
  }
  return out
}

/**
 * The command that runs the contract-sync checker: the checker script itself, or a contract-sync script of
 * the repo's task runner rendered from a gate template. Anything else Detect reported is declined and logged.
 * @param {string|undefined} reported the command Detect reported
 * @returns {string} the command, or '' when it was declined
 */
function contractSyncCommandFor(reported) {
  const command = trimmed(reported)
  if (!command) return CONTRACT_SYNC_COMMAND
  const allowed = [CONTRACT_SYNC_COMMAND, ...CONTRACT_SYNC_SCRIPTS.flatMap((script) => gateTemplates().map((t) => renderGateTemplate(t, script)))]
  if (allowed.includes(command)) return command
  log(`Contract-sync command declined: ${JSON.stringify(command.slice(0, 120))} is not ${CONTRACT_SYNC_COMMAND} or a contract-sync script. Fix: register the checker as a "contract-sync" script of the repo's task runner.`)
  return ''
}

// A gate failure the fix loop can act on: untrusted gates were never run and an unreachable gate is an
// environment problem for the owner, so neither has anything a fix agent can change.
const isNotRunGate = (g) => [NOT_RUN_UNTRUSTED, NOT_RUN_DECLINED, NOT_RUN_NO_GATE].some((s) => String(g.details || '').startsWith(s))
const isFixableGate = (g) => g.status === 'fail' && !isNotRunGate(g)

// What a gate-fix agent returns: the files it changed (shared by the round) and, per failing gate, why it fails
// and what the owner does about it.
const GATE_CAUSES = ['code', 'environment', 'pre-existing', 'unknown']
// Shared by every prompt that edits code: workflows leave version control to the owner.
const NO_VCS_WRITES = 'Do not commit, push, merge, tag or open a pull request. If a task asks for one of these, leave it undone and report it as an owner step.'

/** How a Build agent reports an owner step so isOwnerStep can recognise it; follows NO_VCS_WRITES in Build prompts. */
const OWNER_STEP_NOTE = 'When you leave a task undone as an owner step, return completed=false and start notes with "owner-step:" followed by what the owner must do.'

/**
 * The question and assumption contract shared by ship-feature, fix-bug, greenfield-build, qa-and-docs and
 * tech-research. A workflow never waits for input (the Workflow tool has no input channel): a planning agent
 * returns the questions it could not settle and the assumptions it made, the run goes on, and both lists come
 * back in the result for the caller to ask. The caller answers with `args.answers` ({ <question id>: <answer> })
 * on a later run; the first planning prompt receives them.
 */
const ANSWERS_ARG = (() => {
  const given = typeof args !== 'undefined' && args && typeof args === 'object' ? args.answers : null
  return given && typeof given === 'object' && !Array.isArray(given) ? given : {}
})()

const QUESTION_ITEM_SCHEMA = {
  type: 'object',
  required: ['id', 'question', 'why', 'blocking'],
  properties: {
    id: { type: 'string' },
    question: { type: 'string' },
    why: { type: 'string' },
    blocking: { type: 'boolean' },
  },
}

const ASSUMPTION_ITEM_SCHEMA = {
  type: 'object',
  required: ['id', 'text', 'source'],
  properties: {
    id: { type: 'string' },
    text: { type: 'string' },
    source: { type: 'string' },
  },
}

/** Schema properties a planning phase adds to its result schema to take part in the contract. */
const ASK_SCHEMA_PROPS = {
  questions: { type: 'array', items: QUESTION_ITEM_SCHEMA },
  assumptions: { type: 'array', items: ASSUMPTION_ITEM_SCHEMA },
}

/** Prompt text for a planning phase: the owner's answers when there are any, and how to report what is still open. */
function askPromptBlock() {
  const answered = Object.keys(ANSWERS_ARG).length ? `Answers the owner already gave (question id to answer; treat as settled, do not ask again): ${JSON.stringify(ANSWERS_ARG)}\n` : ''
  return `${answered}Do not wait for input. Return in questions every point you could not settle from the code, docs and answers above ({ id, question, why it matters, blocking: true when the work cannot be right without it }), and in assumptions every choice you made where the request was silent ({ id, text, source: where you looked }). Use empty lists when there are none.`
}

const askedQuestions = []
const assumedChoices = []

const askCounters = {}

/**
 * Collects the questions and assumptions of one planning result. Ids are assigned here
 * (`Q-<scope>-<n>`, `<scope>-A<n>`, in the order returned, counted per scope) and the agent's own ids are
 * ignored, so two phases or repos that both call a question "Q1" never collide and an owner's answer
 * matches the id the run assigned. A question whose assigned id has an answer, or whose text was already
 * asked, is skipped.
 */
function collectAsk(result, scope) {
  const tag = scope ? `${scope}-` : ''
  const next = (kind) => {
    const key = `${kind}:${tag}`
    askCounters[key] = (askCounters[key] || 0) + 1
    return askCounters[key]
  }
  for (const q of (result && Array.isArray(result.questions) && result.questions) || []) {
    const id = `Q-${tag}${next('Q')}`
    const text = String((q && q.question) || '')
    if (Object.prototype.hasOwnProperty.call(ANSWERS_ARG, id)) continue
    if (askedQuestions.some((k) => k.id === id || (text && k.question === text))) continue
    askedQuestions.push({ id, question: text, why: String((q && q.why) || ''), blocking: !!(q && q.blocking) })
  }
  for (const a of (result && Array.isArray(result.assumptions) && result.assumptions) || []) {
    const text = typeof a === 'string' ? a : a && a.text ? String(a.text) : ''
    if (!text) continue
    const id = `${tag}A${next('A')}`
    if (assumedChoices.some((k) => k.id === id || k.text === text)) continue
    assumedChoices.push({ id, text, source: typeof a === 'string' ? scope || '' : String(a.source || scope || '') })
  }
}

/** True when a question the work cannot be right without is still open; the caller ends the run and returns it. */
function blockingQuestionOpen() {
  return askedQuestions.some((q) => q.blocking)
}

// Bounds on what one Build agent reply adds to the run's assumptions, so a runaway reply cannot flood the report.
const MAX_BUILD_ASSUMPTIONS = 20
const MAX_ASSUMPTION_TEXT = 300

/**
 * Contract items ({ id, text, source }) for the assumption strings one Build reply returned. At most
 * MAX_BUILD_ASSUMPTIONS are kept, each cut to MAX_ASSUMPTION_TEXT characters; when more came back, one last
 * item says how many were left out, so the report still accounts for every one.
 * @param {unknown} raw the reply's assumptions (strings; an object's text is used)
 * @param {{ prefix: string, source: string, start?: number }} o ids are `${prefix}${n}`, numbered from start + 1
 * @returns {{ id: string, text: string, source: string }[]}
 * @example buildAssumptionItems(['uses UTC'], { prefix: 'T3-A', source: 'build:t3' })  // [{ id: 'T3-A1', text: 'uses UTC', source: 'build:t3' }]
 */
function buildAssumptionItems(raw, { prefix, source, start = 0 }) {
  const texts = (Array.isArray(raw) ? raw : [])
    .map((a) => (typeof a === 'string' ? a : a && typeof a.text === 'string' ? a.text : ''))
    .map((t) => t.replace(/\s+/g, ' ').trim())
    .filter(Boolean)
  const kept = texts.slice(0, MAX_BUILD_ASSUMPTIONS).map((t) => (t.length > MAX_ASSUMPTION_TEXT ? `${t.slice(0, MAX_ASSUMPTION_TEXT - 1)}…` : t))
  if (texts.length > MAX_BUILD_ASSUMPTIONS) kept.push(`${texts.length - MAX_BUILD_ASSUMPTIONS} more assumption(s) not listed (the reply returned ${texts.length})`)
  return kept.map((text, i) => ({ id: `${prefix}${start + i + 1}`, text, source }))
}

/** The contract keys of a workflow result: `questions` and `assumptions`, empty lists when there are none. */
function askResult(extraAssumptions) {
  return { questions: askedQuestions.slice(), assumptions: [...assumedChoices, ...(extraAssumptions || [])] }
}

const GATE_FIX_SCHEMA = {
  type: 'object',
  required: ['changedFiles', 'causes'],
  properties: {
    changedFiles: { type: 'array', items: { type: 'string' } },
    causes: {
      type: 'array',
      items: {
        type: 'object',
        required: ['gate', 'cause'],
        properties: {
          gate: { type: 'string' },
          cause: { type: 'string', enum: GATE_CAUSES },
          ownerAction: { type: 'string' },
        },
      },
    },
  },
}

const GATE_FIX_PROMPT_TAIL = 'Return changedFiles (every file you changed; an empty list when you changed none) and causes: one entry for each failing gate listed above, with gate (its name exactly as listed), cause (code when the failure is in this repo\'s code and you fixed it; environment when the tooling, dependencies, services or container cannot run the gate; pre-existing when the failure predates this run; unknown otherwise) and ownerAction (what the owner does by hand, empty for a fixed code failure).'

/**
 * Identity of a failing gate across fix rounds: repo, gate name and the trusted plan command. Agent-written
 * details never enter it, so a gate whose output text changes between rounds is still recognised.
 * @param {{name: string, repo?: string}} gate
 * @param {Map<string, string>} [planCommands] gatePlanKey to plan command
 * @returns {string} `<repo>::<name>::<command>`; the command is empty when the plan has none
 */
function gateSignature(gate, planCommands = GATE_PLAN_COMMANDS) {
  const repo = (gate && gate.repo) || ''
  const name = (gate && gate.name) || ''
  return `${repo}::${name}::${planCommands.get(gatePlanKey(repo, name)) || ''}`
}

/**
 * Whether a Build agent's reply hands the task to the owner: not completed, and the notes start with the
 * marker "owner-step:" (any case). A note that only mentions the word, such as a negation, does not count.
 * Such a task is an owner step, not a failure.
 * @param {*} result the build agent's reply
 * @returns {boolean}
 */
function isOwnerStep(result) {
  return !!result && result.completed === false && /^\s*owner-step:/i.test(String(result.notes || ''))
}

/** The first entry of a fix reply's causes for the named gate, or undefined. */
const gateFixEntry = (result, gateName) =>
  result && Array.isArray(result.causes) ? result.causes.find((c) => c && c.gate === gateName) : undefined

/**
 * Whether a fix round got nowhere for one gate: no result, an invalid one, no changed file, no valid entry
 * for the gate, or a cause the agent cannot fix. A cause of code or unknown with changed files is not stuck.
 * @param {*} result the gate-fix agent's reply
 * @param {string} gateName
 * @returns {boolean}
 */
function gateFixStuck(result, gateName) {
  if (!result || !Array.isArray(result.changedFiles)) return true
  const entry = gateFixEntry(result, gateName)
  if (!entry || !GATE_CAUSES.includes(entry.cause)) return true
  return result.changedFiles.length === 0 || entry.cause === 'environment' || entry.cause === 'pre-existing'
}

/**
 * Records, gate by gate, the failing gates a fix round left stuck, with the owner action reported for each.
 * @param {Map<string, string>} stuck signature to owner action, updated in place
 * @param {object[]} failing the gates that round was asked to fix
 * @param {*} result the gate-fix agent's reply
 * @param {Map<string, string>} [planCommands] gatePlanKey to plan command
 * @returns {boolean} whether any gate was left stuck
 */
function recordGateFix(stuck, failing, result, planCommands = GATE_PLAN_COMMANDS) {
  let any = false
  for (const g of failing) {
    if (!gateFixStuck(result, g.name)) continue
    const entry = gateFixEntry(result, g.name)
    stuck.set(gateSignature(g, planCommands), entry && typeof entry.ownerAction === 'string' ? entry.ownerAction : '')
    any = true
  }
  return any
}

/** The failing gates a fix agent may still be sent: fixable and not recorded as stuck. */
const gatesToFix = (gates, stuck, planCommands = GATE_PLAN_COMMANDS) => gates.filter((g) => isFixableGate(g) && !stuck.has(gateSignature(g, planCommands)))

/**
 * Whether a gate-fix round changed no file in any repo, so re-running the gates would repeat the same result.
 * An invalid reply is not counted: the agent may still have edited files.
 * @param {*[]} replies the gate-fix agents' replies for the round
 * @returns {boolean}
 */
const gateRoundIdle = (replies) => replies.length > 0 && replies.every((r) => r && Array.isArray(r.changedFiles) && r.changedFiles.length === 0)

/** Plan commands of the gates run so far, by gatePlanKey. */
const GATE_PLAN_COMMANDS = new Map()
const gatePlanKey = (repo, name) => `${repo}\u0000${name}`

/**
 * The gates the owner must act on: every unreachable gate and every failing gate a fix round left stuck.
 * Gates that were never run (untrusted, declined, no allowlisted gate) are left out: /stack-trust, not a hand run, resolves them.
 * The command comes only from the trusted gate plan, looked up by repo and gate name; a command the agent reported is ignored.
 * @param {object[]} gates the gates of every repo, each with its repo path
 * @param {Map<string, string>} stuck signature to owner action
 * @param {Map<string, string>} [planCommands] gatePlanKey to plan command
 * @returns {{gate: string, command: string, ownerAction: string}[]} command is '' when the plan has none
 */
function environmentIssues(gates, stuck, planCommands = GATE_PLAN_COMMANDS) {
  return gates
    .filter((g) => (g.status === 'unreachable' && !isNotRunGate(g)) || (g.status === 'fail' && stuck.has(gateSignature(g, planCommands))))
    .map((g) => ({
      gate: g.name,
      command: planCommands.get(gatePlanKey(g.repo, g.name)) || '',
      ownerAction: stuck.get(gateSignature(g, planCommands)) || String(g.details || '').split('\n').map((l) => l.trim()).find(Boolean) || 'check the environment and re-run the gate',
    }))
}

/** Report text for the environment issues: an "Environment issues" table and the Next line entries; '' when there are none. */
function environmentReportText(issues) {
  if (!issues.length) return ''
  const cell = (v) => String(v).replace(/`/g, "'").replace(/\|/g, '\\|').replace(/\s+/g, ' ')
  const rows = issues.map((i) => `| ${cell(i.gate)} | ${i.command ? `\`${cell(i.command)}\`` : '(no command; see the gate output)'} | ${cell(i.ownerAction)} |`)
  const table = ['Environment issues (gates the fix loop could not act on):', '| Gate | Command | Owner action |', '| --- | --- | --- |', ...rows].join('\n')
  return `${table}\nPut this table in the report under "Environment issues" and end the Next line with: ${issues.filter((i) => i.command).map((i) => `Run by hand: ${i.command}`).join('; ')}`
}

/**
 * Whether a repo with no allowlisted gate may fall back to the lint and test tooling it visibly has (AC-36):
 * only a first-party or other stack, and only when no manifest was rejected, ignored or untrusted in this run.
 * @param {{ stack: string, declinedStack?: object }} repo
 * @returns {boolean}
 */
function toolingFallbackAllowed(repo) {
  return FIRST_PARTY_KEYS.includes(repo.stack) && !hasOwn(OVERLAY_META, repo.stack) && !repo.declinedStack && !MANIFESTS_DECLINED
}

/**
 * The gate-prompt line for a repo whose gate list is empty: the tooling fallback when it is allowed, else none.
 * @param {object} repo the repo the prompt is for
 * @param {string} [fallback] the fallback wording
 * @returns {string} one "- (...)" line
 */
function noGatesLine(repo, fallback) {
  return toolingFallbackAllowed(repo) ? `- (${fallback || 'none detected — run any lint/test tooling that exists'})` : '- (no allowlisted gate — run no other lint/test tooling)'
}

/**
 * Splits a repo's gates into those to run, those decided without running, and the untrusted ones.
 * A repo whose stack comes from a declined manifest runs nothing: one unreachable gate names the reason.
 * @param {{ stack: string, declinedStack?: { key: string, reason: string }, gateCommands?: { name: string, command: string }[], unlessMatched?: { gate: string, glob: string }[] }} repo
 * @returns {{ untrusted: boolean, declined: boolean, run: object[], fixed: { name: string, status: string, details: string }[] }}
 */
function gatePlanFor(repo) {
  if (repo.declinedStack) {
    const details = `${NOT_RUN_DECLINED}: stack "${repo.declinedStack.key}" — ${repo.declinedStack.reason})`
    return { untrusted: false, declined: true, run: [], fixed: [{ name: 'Quality gates', status: 'unreachable', details }] }
  }
  if (isUntrustedStack(repo.stack)) {
    // Gate names of an untrusted manifest are its text too, so they are reported by position only.
    return { untrusted: true, declined: false, run: [], fixed: STACKS[repo.stack].gates.map((g, i) => ({ name: `gate ${i + 1} (untrusted manifest)`, status: 'unreachable', details: NOT_RUN_UNTRUSTED })) }
  }
  const matched = repo.unlessMatched || []
  const wrapper = execWrapperFor(repo)
  const guards = extrasFor(repo.stack).gates || {}
  const run = []
  const fixed = []
  for (const g of gateCommandsFor(repo)) {
    const hit = matched.find((m) => m && m.gate === g.name)
    if (hit) fixed.push({ name: g.name, status: 'skip', details: `skipped — ${hit.glob} present` })
    else if (wrapper && wrapper.notRunning) fixed.push({ name: g.name, status: 'skip', details: `not run (${wrapper.command.split(' ')[0]} not running)` })
    else if (wrapper && wrapper.unplaced) fixed.push({ name: g.name, status: 'unreachable', details: `not run (${wrapper.command} cannot be pointed at the repo, whose path from the wrapper's marker directory holds characters a gate command does not carry). Fix: run the gate by hand from the repo's directory inside the container, or rename the directory to letters, digits, . _ - and /` })
    else if ((repo.missingTools || []).includes(g.name) && guards[g.name] && guards[g.name].requires !== undefined) {
      const unmet = (repo.missingRequires || []).find((m) => m && m.gate === g.name)
      fixed.push({ name: g.name, status: 'skip', details: requiresSkipText(guards[g.name].requires, unmet && unmet.entries) })
    }
    else {
      const fix = (repo.mutatingGates || []).includes(g.name) && guards[g.name] && guards[g.name].lintFix
      const legacy = (repo.legacyScriptGates || []).includes(g.name) && guards[g.name] && guards[g.name].scriptFallback
      // An unknown major takes the fallback: the script names a command the newer release removed, and the
      // fallback command works on the older releases as well.
      const known = legacy && (repo.dependencyMajors || []).find((m) => m.dependency === legacy.dependency)
      const outdated = legacy && (!known || known.major >= legacy.minMajor)
      const replacement = fix || (outdated && legacy)
      const command = replacement ? fillPackageManager(replacement.fallback, packageManagerFor(repo)) : g.command
      run.push(wrapper ? { ...g, command: `${wrapper.prefix} ${command}`, wrapped: true } : { ...g, command })
    }
  }
  if (!run.length && !fixed.length && !toolingFallbackAllowed(repo)) {
    const why = hasOwn(OVERLAY_META, repo.stack) ? `the ${repo.stack} manifest declares none` : 'a stack manifest was rejected, ignored or untrusted in this run'
    return { untrusted: false, declined: true, run: [], fixed: [{ name: 'Quality gates', status: 'unreachable', details: `${NOT_RUN_NO_GATE}; ${why})` }] }
  }
  return { untrusted: false, declined: false, run, fixed }
}

/**
 * Runs one repo's gates through an agent, resolving skipped and untrusted gates in the script.
 * Side effect: records each gate's trusted plan command in GATE_PLAN_COMMANDS, keyed by repo.path, which
 * gateSignature, recordGateFix, gatesToFix and environmentIssues read; the returned `repo` is repo.path
 * (never the agent's text) so those lookups match.
 * @param {object} repo the detected repo (path, stack, gateCommands, unlessMatched)
 * @param {(repo: object) => string} instructionsFor builds the gate prompt for the gates that remain
 * @param {object} runOpts options for runAgent
 * @returns {Promise<{ repo: string, gates: object[], allPassed: boolean }|null>}
 */
async function runRepoGates(repo, instructionsFor, runOpts) {
  const plan = gatePlanFor(repo)
  if (plan.untrusted || plan.declined) return { repo: repo.path, gates: plan.fixed, allPassed: false }
  if (!plan.run.length && plan.fixed.length) return { repo: repo.path, gates: plan.fixed, allPassed: false }
  const result = await runAgent(instructionsFor({ ...repo, gateCommands: plan.run }), runOpts)
  if (!result) return result
  const wrapper = execWrapperFor(repo)
  const wrapped = new Set(plan.run.filter((g) => g.wrapped).map((g) => g.name))
  const commands = new Map(plan.run.map((g) => [g.name, g.command]))
  commands.forEach((command, name) => GATE_PLAN_COMMANDS.set(gatePlanKey(repo.path, name), command))
  const reported = (result.gates || []).map((g) => {
    // A failing or unreachable gate also carries its trusted command on the gate itself.
    const { command: _agentCommand, ...own } = g || {}
    const withCommand = g && (g.status === 'fail' || g.status === 'unreachable') && commands.has(g.name) ? { ...own, command: commands.get(g.name) } : own
    if (!wrapped.has(g && g.name)) return withCommand
    const details = mapContainerPaths(String(g.details || ''), wrapper)
    if (details.includes(wrapper.command)) return details === String(g.details || '') ? withCommand : { ...withCommand, details }
    return { ...withCommand, details: `${details ? `${details} ` : ''}(via ${wrapper.command})` }
  })
  return { ...result, repo: repo.path, gates: [...reported, ...plan.fixed] }
}

const normalFile = (f) => String(f || '').trim().replace(/^(\.\/)+/, '')

/** Whether two reported paths name the same file; one may carry a longer prefix (an absolute or container path). */
function sameFile(a, b) {
  return a === b || a.endsWith(`/${b}`) || b.endsWith(`/${a}`)
}

// Lint and format violations can sit in files the run never touched; types, test, build and e2e failures can
// come from a change in another file, so they always block.
const SCOPED_GATE_KINDS = ['lint', 'format']

/**
 * Passes a failing lint or format gate whose reported files all lie outside the run's changed files.
 * The kind comes from the stack manifest by gate name; a gate without files, of another kind or of an
 * unknown kind stays as reported, so the check fails closed.
 * @param {{ allPassed: boolean, gates?: object[] }|null} result  one repo's gate result
 * @param {string} stack  the repo's stack
 * @param {string[]} changed  the repo's changed files, repo-relative
 * @returns {object|null}  the result, with allPassed recomputed when a gate was passed
 * @example
 * // The stack's manifest declares a gate "Lint" of kind lint; it fails only in legacy/old.js, which the run did not change:
 * scopeLintFailures({ allPassed: false, gates: [{ name: 'Lint', status: 'fail', files: ['legacy/old.js'] }] }, stack, ['src/page.js'])
 * // -> { allPassed: true, gates: [{ name: 'Lint', status: 'pass', details: 'pre-existing violations only: 1 file(s) this run did not change (not in scope)', ... }] }
 */
function scopeLintFailures(result, stack, changed) {
  if (!result || !Array.isArray(result.gates)) return result
  const kinds = extrasFor(stack).gates || {}
  const inRun = (changed || []).map(normalFile).filter(Boolean)
  let passed = 0
  const gates = result.gates.map((g) => {
    const kind = g && hasOwn(kinds, g.name) ? kinds[g.name].kind : null
    if (!g || g.status !== 'fail' || !SCOPED_GATE_KINDS.includes(kind)) return g
    const files = Array.from(new Set((Array.isArray(g.files) ? g.files : []).map(normalFile).filter(Boolean)))
    if (!files.length || files.some((f) => inRun.some((c) => sameFile(f, c)))) return g
    passed++
    return { ...g, status: 'pass', details: `pre-existing violations only: ${files.length} file(s) this run did not change (not in scope)` }
  })
  if (!passed) return result
  return { ...result, gates, allPassed: gates.every((g) => g && (g.status === 'pass' || g.status === 'skip')) }
}

/** The stable failure ids a gate reported (test names, `file:rule`, advisory ids), trimmed and de-duplicated. */
function gateFailureIds(gate) {
  const ids = gate && Array.isArray(gate.failures) ? gate.failures : []
  return Array.from(new Set(ids.map((id) => String(id == null ? '' : id).trim()).filter(Boolean)))
}

/**
 * Compares one repo's failing gates with the gate baseline taken before the build. A failing gate is
 * `pre-existing` only when the baseline run of the same gate (repo, name, plan command) also failed and every
 * failure id it reports now was already in the baseline. A new id, a failing gate with no ids, a gate that
 * passed or was absent in the baseline, and a gate unreachable in the baseline all stay failing, so they block.
 * A pre-existing gate is passed with `preExisting: true`, so it is not sent to a fix agent and does not block.
 * @param {{ repo: string, allPassed: boolean, gates?: object[] }|null} result  one repo's gate result
 * @param {object[]|null} baseline  the allGates of the baseline run, or null when none was taken
 * @returns {object|null}  the result, with allPassed recomputed when a gate was classified pre-existing
 * @example
 * // Baseline: the test gate failed with ['FooTest']. Now it fails with ['FooTest'] only: pre-existing. With ['FooTest', 'BarTest']: a regression.
 */
function classifyAgainstBaseline(result, baseline) {
  if (!result || !Array.isArray(result.gates) || !Array.isArray(baseline) || !baseline.length) return result
  // A baseline from gateBaselineOf carries the signature of the command that ran then; a changed plan command no longer matches.
  const before = new Map(baseline.filter((g) => g && g.status === 'fail').map((g) => [g.signature || gateSignature(g), gateFailureIds(g)]))
  let classified = 0
  const gates = result.gates.map((g) => {
    if (!g || g.status !== 'fail') return g
    const now = gateFailureIds(g)
    const known = before.get(gateSignature({ ...g, repo: result.repo }))
    if (!known || !now.length || !now.every((id) => known.includes(id))) return g
    classified++
    return { ...g, status: 'pass', preExisting: true, details: `pre-existing: failed the same way before this run (${now.length} known failure(s)); not a regression` }
  })
  if (!classified) return result
  return { ...result, gates, allPassed: gates.every((g) => g && (g.status === 'pass' || g.status === 'skip')) }
}

/**
 * The gate baseline as kept for later comparison: each gate with the signature of the plan command it ran
 * with, recorded now, so a gate whose command changes before the later run is not matched to it.
 * @param {object[]} allGates the allGates of the baseline run
 * @returns {object[]}
 */
function gateBaselineOf(allGates) {
  return (Array.isArray(allGates) ? allGates : []).map((g) => ({ ...g, signature: gateSignature(g) }))
}

/**
 * Runs the gates of every repo in parallel, plus any extra jobs (such as a contract-sync gate).
 * @param {object} opts
 * @param {object[]} opts.repos  the repos to run gates in
 * @param {(repo: object) => Promise<object|null>} opts.runRepo  runs one repo's gates (normally runRepoGates)
 * @param {(repo: object) => string[]} [opts.changedIn]  a repo's changed files; when given, lint and format failures outside them are passed
 * @param {object[]|null} [opts.baseline]  the allGates of a run taken before the build; failures it already had are classified pre-existing
 * @param {Array<() => Promise<object|null>>} [opts.extraJobs]  further gate jobs, each returning a { repo, gates, allPassed } result
 * @returns {Promise<{ results: object[], allGates: object[], allPassed: boolean }>}
 */
async function runGateSet({ repos, runRepo, changedIn = null, baseline = null, extraJobs = [] }) {
  const jobs = repos.map((r) => async () => {
    const result = await runRepo(r)
    return classifyAgainstBaseline(changedIn ? scopeLintFailures(result, r.stack, changedIn(r)) : result, baseline)
  })
  const results = (await parallel([...jobs, ...extraJobs])).filter(Boolean)
  const allGates = results.flatMap((g) => (g.gates || []).map((x) => ({ ...x, repo: g.repo })))
  return { results, allGates, allPassed: results.length > 0 && results.every((g) => g.allPassed) }
}

/**
 * Whether a failing gate is of kind security in its repo's stack manifest. The kind comes from the manifest
 * by gate name; a gate of an untrusted manifest or of an unknown kind is not security.
 * @param {{ name?: string, repo?: string }} gate
 * @param {Array<{ path: string, stack: string }>} repos
 * @returns {boolean}
 */
function isSecurityGate(gate, repos) {
  const repo = repos.find((r) => r.path === gate.repo)
  const kinds = repo ? extrasFor(repo.stack).gates || {} : {}
  return hasOwn(kinds, gate.name) && kinds[gate.name].kind === 'security'
}

/**
 * Runs the gates and lets a fix agent repair failures, up to 3 rounds. A round stops the loop when nothing is
 * left to fix, the budget is low, no repo has changed files (with changedIn), or no fix agent changed a file.
 * Failures a round left stuck (no file changed, or an environment or pre-existing cause) are recorded in `stuck`
 * and not sent to a fix agent again.
 * @param {object} opts
 * @param {object[]} opts.repos  the repos a fix may target
 * @param {Map<string, object>} opts.stuck  stuck-gate bookkeeping, shared with environmentIssues in the report
 * @param {() => Promise<{ results: object[], allGates: object[], allPassed: boolean }>} opts.runGates  one gate run
 * @param {(repo: object, failing: object[], round: number) => Promise<object|null>} opts.fixRepo  runs the fix agent for one repo; builds its own prompt
 * @param {(repo: object) => string[]} [opts.changedIn]  a repo's changed files; a repo without any gets no fix call, its failures are pre-existing
 * @returns {Promise<{ results: object[], allGates: object[], allPassed: boolean }>}  the last gate run
 */
async function gateFixLoop({ repos, stuck, runGates, fixRepo, changedIn = null }) {
  let current = await runGates()
  let fixRounds = 0
  while (!current.allPassed && fixRounds < 3) {
    current.allGates.filter((g) => g.status === 'fail' && isSecurityGate(g, repos)).forEach((g) => {
      const sig = gateSignature(g, GATE_PLAN_COMMANDS)
      if (stuck.has(sig)) return
      const command = GATE_PLAN_COMMANDS.get(gatePlanKey(g.repo, g.name))
      stuck.set(sig, `Review the security finding(s) from ${command ? `\`${command}\`` : g.name} and fix or accept them; the fix loop does not change security findings`)
      log(`Gates: ${g.name} is a security gate — not sent to a fix agent; it blocks until the owner acts`)
    })
    const failing = gatesToFix(current.allGates, stuck)
    if (!failing.length) {
      log('Gates not all green but nothing actionable to fix — stopping loop.')
      break
    }
    if (budget.total && budget.remaining() < 60_000) {
      log(`Gates failing but budget low (${Math.round(budget.remaining() / 1000)}k left) — stopping fix loop.`)
      break
    }
    // Fix per repo so the right specialist edits the right tree.
    const byRepo = repos.filter((r) => failing.some((f) => f.repo === r.path))
    const targets = byRepo.length ? byRepo : repos
    if (changedIn) targets.filter((r) => !changedIn(r).length).forEach((r) => log(`Gates: ${r.path} failures are pre-existing (this run changed no file there) — not fixed`))
    const scoped = changedIn ? targets.filter((r) => changedIn(r).length) : targets
    if (!scoped.length) break
    fixRounds++
    log(`Gates round ${fixRounds}: fixing ${failing.length} failing gate(s)`)
    const round = fixRounds
    const replies = await parallel(
      scoped.map((r) => async () => {
        const repoFailing = failing.filter((f) => !f.repo || f.repo === r.path)
        const fixed = await fixRepo(r, repoFailing, round)
        if (recordGateFix(stuck, repoFailing, fixed)) log(`Gates: the ${r.role} fix round changed no file or reported an environment cause — those failures are not sent to a fix agent again`)
        return fixed
      })
    )
    if (gateRoundIdle(replies)) {
      log('Gates: no fix agent changed a file — not re-running the gates.')
      break
    }
    current = await runGates()
  }
  return current
}

// --- Base revision ---------------------------------------------------------
// The revision a run starts from and the files already modified or untracked then, per tracked repo.
// Later steps diff against the sha, so it is accepted only as a full hex revision id: it ends up inside
// git commands the script builds, never text from an agent.
const HASHES_SCHEMA = {
  type: 'array',
  items: {
    type: 'object',
    required: ['path', 'hash'],
    properties: { path: { type: 'string' }, hash: { type: 'string' } },
  },
}

const BASE_SCHEMA = {
  type: 'object',
  required: ['sha', 'dirty', 'hashes'],
  properties: {
    sha: { type: 'string' },
    dirty: { type: 'array', items: { type: 'string' } },
    hashes: HASHES_SCHEMA,
  },
}

/**
 * Whether a value is a full git revision id (sha-1 or sha-256), lower-case hex.
 * @param {unknown} value
 * @returns {boolean}
 * @example isCommitSha('0123456789abcdef0123456789abcdef01234567') // true
 * @example isCommitSha('HEAD; rm -rf ~') // false
 */
function isCommitSha(value) {
  return typeof value === 'string' && /^(?:[0-9a-f]{40}|[0-9a-f]{64})$/.test(value)
}

/**
 * Whether a repo-relative path is plain enough to be named inside a git command the script builds.
 * @param {string} file
 * @returns {boolean}
 */
function isHashablePath(file) {
  return /^[A-Za-z0-9._@+\/-]+$/.test(file) && !file.split('/').includes('..') && !file.startsWith('-')
}

/**
 * Turns an agent's hash list into a path to content-hash map. A hash is a hex object id, or '' for a
 * file that no longer exists; anything else is dropped.
 * @param {unknown} raw
 * @returns {Record<string, string>}
 */
function acceptHashes(raw) {
  const out = {}
  for (const item of Array.isArray(raw) ? raw : []) {
    if (!item || typeof item.path !== 'string' || typeof item.hash !== 'string') continue
    const file = normalFile(item.path)
    const hash = item.hash.trim()
    if (file && isHashablePath(file) && (hash === '' || isCommitSha(hash))) out[file] = hash
  }
  return out
}

/**
 * The content-hash lines of a prompt: one read-only `git hash-object` per already-dirty path.
 * @param {string} dir a validated repo path
 * @param {string[]} paths dirty paths, filtered through isHashablePath
 * @returns {string}
 */
function hashStepText(dir, paths) {
  const list = paths.filter(isHashablePath)
  if (!list.length) return ''
  return `   Run \`git -C "${dir}" hash-object -- <file> ...\` once, naming every one of these files that still exists (a missing file gets hash ''): ${list.join(', ')}. hashes = one {path, hash} per file; hash is '' when the file no longer exists.\n`
}

/**
 * The read-only steps that capture a repo's base revision and dirty-file list. Two git commands, no
 * stash or reset, and no commits, so the user's changes are never touched to take a baseline.
 * @param {string} dir a validated repo path
 * @returns {string}
 */
function baseStepText(dir) {
  return `Base revision. Run exactly these two read-only git commands, one at a time, and no other git command:
   git -C "${dir}" rev-parse HEAD
   git -C "${dir}" status --porcelain --untracked-files=all
   sha = the first command's output. dirty = the repo-relative path of every line of the second command's output (modified, staged, deleted or untracked; for a rename, the new path). dirty is [] when the output is empty. After those two commands, run \`git -C "${dir}" hash-object -- <path> ...\` once with every dirty path that still exists, and return hashes = one {path, hash} per dirty path (hash is '' when the file no longer exists; skip a path that starts with "-" or holds a space or quote). Never stash, reset, checkout, clean or make commits.`
}

/**
 * Turns one agent answer into a base entry, or null when the sha is not a full revision id.
 * @param {{ path: string, role?: string }} repo
 * @param {{ sha?: unknown, dirty?: unknown }|null} raw
 * @returns {{ repo: string, role: string, sha: string, dirty: string[] }|null}
 */
function acceptBase(repo, raw) {
  const sha = raw && typeof raw.sha === 'string' ? raw.sha.trim() : ''
  if (!isCommitSha(sha)) return null
  const dirty = (Array.isArray(raw.dirty) ? raw.dirty : []).map((f) => normalFile(f)).filter((f) => f && !/[\r\n]/.test(f))
  const entry = { repo: repo.path, role: repo.role, sha, dirty: [...new Set(dirty)] }
  const hashes = acceptHashes(raw.hashes)
  if (Object.keys(hashes).length) entry.hashes = hashes
  return entry
}

/**
 * The base entry of one repo from an agent answer: the accepted base, or a skipped entry that says why.
 * A repo with tracked !== true has no git history to diff against, and an unsafe path or a sha that is
 * not a revision id is never trusted.
 * @param {{ path: string, role: string, tracked?: boolean }} repo
 * @param {object|null} raw the agent answer (sha, dirty)
 * @param {Set<string>} [roots] caller repo roots (callerRoots)
 * @returns {{ repo: string, role: string, sha?: string, dirty?: string[], skipped?: string }}
 */
function baseEntry(repo, raw, roots) {
  const skip = (reason) => ({ repo: repo.path, role: repo.role, skipped: reason })
  if (repo.tracked !== true) return skip('untracked: no git history to diff against')
  if (!isRepoPath(repo.path, roots)) return skip('unsafe repo path')
  return acceptBase(repo, raw) || skip('no valid revision sha reported')
}

/**
 * Records the base revision of every repo. A repo with tracked !== true has no git history to diff
 * against: it is recorded as skipped and the run goes on. A rejected sha is recorded as skipped too.
 * @param {Array<{ path: string, role: string, tracked?: boolean }>} repoList
 * @param {{ roots?: Set<string>, run: (prompt: string, repo: object) => Promise<object|null> }} opts
 * @returns {Promise<Array<{ repo: string, role: string, sha?: string, dirty?: string[], skipped?: string }>>}
 */
async function recordBases(repoList, opts) {
  return Promise.all(repoList.map(async (repo) => {
    if (repo.tracked !== true || !isRepoPath(repo.path, opts.roots)) return baseEntry(repo, null, opts.roots)
    const raw = await opts.run(`Record the starting point of the ${repo.role} repo at "${repo.path}". Use Bash. Change nothing.\n1. ${baseStepText(repo.path)}\nReturn sha, dirty and hashes.`, repo)
    const entry = baseEntry(repo, raw, opts.roots)
    // A dirty file without a base hash later counts as changed by the run, so missing hashes are asked for once more.
    const missing = entry.sha ? entry.dirty.filter(isHashablePath).filter((f) => !hasOwn(entry.hashes || {}, f)) : []
    if (!missing.length) return entry
    const again = await opts.run(`Record the starting point of the ${repo.role} repo at "${repo.path}". Use Bash. Change nothing.\nThe content hashes of the already-changed files are missing. Return sha = ${entry.sha}, dirty = the same list as before, and hashes for these paths:\n1.${hashStepText(repo.path, missing).replace(/^ +/, ' ')}Return sha, dirty and hashes.`, repo)
    const more = again ? acceptHashes(again.hashes) : {}
    if (Object.keys(more).length) entry.hashes = { ...(entry.hashes || {}), ...more }
    return entry
  }))
}

/** Logs one line per base entry: the short sha and dirty count, or why it was skipped. */
function logBases(bases) {
  bases.forEach((b) => log(b.skipped ? `Base: ${b.role} skipped (${b.skipped})` : `Base: ${b.role} at ${b.sha.slice(0, 10)}, ${b.dirty.length} file(s) already changed`))
}

// --- Changed files from git -----------------------------------------------
// For a tracked repo with a recorded base, the files a run changed come from git (the diff from the
// base plus untracked files, minus the files already dirty at the start), not from what agents report.
const CHANGED_SCHEMA = {
  type: 'object',
  required: ['files', 'hashes'],
  properties: { files: { type: 'array', items: { type: 'string' } }, hashes: HASHES_SCHEMA },
}

/**
 * The read-only steps that list what changed since the base revision.
 * @param {string} dir a validated repo path
 * @param {string} sha a validated revision id (isCommitSha)
 * @param {string[]} [hashed] already-dirty paths whose content hash is read again
 * @returns {string}
 */
function changedStepText(dir, sha, hashed = []) {
  return `Changed files. Run exactly these two read-only git commands, one at a time, and no other git command:
   git -C "${dir}" diff --name-only ${sha}
   git -C "${dir}" ls-files --others --exclude-standard
   files = the repo-relative path of every line of both outputs, once each. files is [] when both are empty.
${hashStepText(dir, hashed)}   Never stash, reset, checkout, clean or make commits.`
}

/**
 * The files a run changed in one repo: the agent's git listing without spec files and without the
 * files that were already dirty at the base, except a dirty file whose content hash differs from the
 * one recorded at the base (the run changed it again).
 * @param {{ files?: unknown }|null} raw the agent answer
 * @param {{ dirty?: string[] }} base the repo's base entry
 * @returns {string[]|null} null when the answer holds no file list
 */
function acceptChanged(raw, base) {
  if (!raw || !Array.isArray(raw.files)) return null
  const dirty = (base.dirty || []).map((f) => normalFile(f))
  const before = base.hashes || {}
  const now = acceptHashes(raw.hashes)
  const files = raw.files.map((f) => normalFile(f)).filter((f) => f && !/[\r\n]/.test(f) && !/(^|\/)\.ai\/specs\//.test(f))
  // A dirty file the hashes cannot judge (no hash at the base or now) counts as changed.
  const touched = (f) => !(hasOwn(before, f) && hasOwn(now, f)) || before[f] !== now[f]
  return [...new Set(files.filter((f) => !dirty.includes(f) || touched(f)))]
}

/**
 * The changed files per repo. A tracked repo with a valid base is read from git; an untracked repo, a
 * repo without a base, or a git listing the agent did not return falls back to the files agents reported.
 * @param {Array<{ path: string, role: string, tracked?: boolean }>} repoList
 * @param {Array<{ repo: string, sha?: string, dirty?: string[] }>} bases
 * @param {{ roots?: Set<string>, run: (prompt: string, repo: object) => Promise<object|null>, reported: (repo: object) => string[] }} opts
 * @returns {Promise<Array<{ repo: string, role: string, files: string[], source: 'git'|'reported' }>>}
 */
async function collectChanged(repoList, bases, opts) {
  return Promise.all(repoList.map(async (repo) => {
    const base = bases.find((b) => b.repo === repo.path)
    const fallback = { repo: repo.path, role: repo.role, files: opts.reported(repo), source: 'reported' }
    if (repo.tracked !== true || !isRepoPath(repo.path, opts.roots) || !base || !isCommitSha(base.sha)) return fallback
    const raw = await opts.run(`List what changed in the ${repo.role} repo at "${repo.path}" since the run started. Use Bash. Change nothing.\n1. ${changedStepText(repo.path, base.sha, Object.keys(base.hashes || {}))}\nReturn files and hashes.`, repo)
    const files = acceptChanged(raw, base)
    return files ? { repo: repo.path, role: repo.role, files, source: 'git' } : fallback
  }))
}

const HASHED_SCHEMA = {
  type: 'object',
  required: ['hashes'],
  properties: { hashes: HASHES_SCHEMA },
}

/**
 * Content hashes of the files a run has changed so far, for a later comparison. One read-only step per
 * tracked repo with a valid base; an untracked repo, a repo without a base, or an answer without a hash
 * list leaves no entry for it, so the caller falls back to what agents reported.
 * @param {Array<{ path: string, role: string, tracked?: boolean }>} repoList
 * @param {Array<{ repo: string, sha?: string }>} bases
 * @param {(repo: object) => string[]} listOf the changed files of a repo, repo-relative
 * @param {{ roots?: Set<string>, run: (prompt: string, repo: object) => Promise<object|null> }} opts
 * @returns {Promise<Map<string, { files: string[], hashes: Record<string, string> }>>}
 */
async function hashChanged(repoList, bases, listOf, opts) {
  const out = new Map()
  await Promise.all(repoList.map(async (repo) => {
    const base = bases.find((b) => b.repo === repo.path)
    if (repo.tracked !== true || !isRepoPath(repo.path, opts.roots) || !base || !isCommitSha(base.sha)) return
    const files = listOf(repo).map((f) => normalFile(f)).filter(Boolean)
    const hashable = files.filter(isHashablePath)
    if (!hashable.length) {
      out.set(repo.path, { files, hashes: {} })
      return
    }
    const raw = await opts.run(`Read the content hashes of the files changed so far in the ${repo.role} repo at "${repo.path}". Use Bash. Change nothing.\n1.${hashStepText(repo.path, hashable).replace(/^ +/, ' ')}Return hashes.`, repo)
    if (!raw || !Array.isArray(raw.hashes)) return
    out.set(repo.path, { files, hashes: acceptHashes(raw.hashes) })
  }))
  return out
}

/**
 * The files of a later changed list that are new, or whose content hash differs from the snapshot taken
 * earlier. A file the hashes cannot judge (no hash in either snapshot) counts as changed.
 * @param {{ files: string[], hashes: Record<string, string> }} before
 * @param {{ files: string[], hashes: Record<string, string> }} after
 * @returns {string[]}
 */
function changedSinceSnapshot(before, after) {
  return after.files.filter((f) => {
    if (!before.files.includes(f)) return true
    const known = hasOwn(before.hashes, f) && hasOwn(after.hashes, f)
    return !known || before.hashes[f] !== after.hashes[f]
  })
}

/**
 * The lines a reviewer prompt carries so the reviewer reads the real diff: per repo with a base, the
 * exact diff command and the new-files command; for any other repo, the files agents reported.
 * @param {Array<{ path: string, role: string }>} repoList
 * @param {Array<{ repo: string, sha?: string }>} bases
 * @param {(repo: object) => string[]} reported
 * @param {(repo: object) => string[]} [scope] files to limit the diff to; the whole run diff when absent
 * @returns {string}
 */
function reviewDiffLines(repoList, bases, reported, scope) {
  const lines = repoList.map((repo) => {
    const base = bases.find((b) => b.repo === repo.path)
    if (base && isCommitSha(base.sha)) {
      const earlier = reported(repo).filter((f) => (base.dirty || []).includes(f))
      const note = earlier.length ? ` Already changed before the run and changed again, so their diff may include earlier changes: ${earlier.join(', ')}.` : ''
      const only = scope ? scope(repo) || [] : []
      const spec = only.length && only.every(isHashablePath) ? ` -- ${only.map((f) => `"${f}"`).join(' ')}` : ''
      return `- ${repo.role} (${repo.path}): read the changes with \`git -C "${repo.path}" diff ${base.sha}${spec}\`; new files with \`git -C "${repo.path}" ls-files --others --exclude-standard\`.${note}`
    }
    const files = reported(repo)
    return `- ${repo.role} (${repo.path}): no git base recorded; changed files: ${files.join(', ') || '(inspect the working tree)'}.`
  })
  return lines.join('\n')
}

// --- Review: findings, verify votes and the diff review shared by the workflows ---------------
const FINDINGS_SCHEMA = {
  type: 'object',
  required: ['findings'],
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        required: ['title', 'severity'],
        properties: {
          title: { type: 'string' },
          file: { type: 'string' },
          line: { type: 'integer' },
          severity: { type: 'string', enum: ['critical', 'major', 'minor'] },
          description: { type: 'string' },
          convention: { type: 'string' },
          excerpt: { type: 'string' },
        },
      },
    },
  },
}

const EXCERPT_LIMIT = 2000
const EXCERPT_MARKER = '[excerpt truncated]'
/** The reviewer instruction for excerpts. Excerpts come back in the workflow result, so no secret may be quoted. */
const EXCERPT_RULE = 'For each finding you may quote up to 10 lines of code either side in excerpt; never quote a secret value (a key, token, password or credential in a connection string): write <redacted> in its place.'

/**
 * An excerpt cut to EXCERPT_LIMIT characters with the truncation marker, so the verifier prompt and
 * the workflow result carry the same text.
 * @param {*} excerpt the reviewer's excerpt
 * @returns {*} the cut string, or the value unchanged when it is not a string within the limit
 */
function clipExcerpt(excerpt) {
  return typeof excerpt === 'string' && excerpt.length > EXCERPT_LIMIT ? `${excerpt.slice(0, EXCERPT_LIMIT)}\n${EXCERPT_MARKER}` : excerpt
}
const SEVERITY_RANK = { critical: 0, major: 1, minor: 2 }

/**
 * Caps one dimension's findings. Every critical and major finding is kept; the remaining slots are filled
 * in severity, file, line and title order, so the same reviewer output always gives the same selection and order.
 * @param {object[]} findings a dimension's findings
 * @param {number} [max] findings kept per dimension (the run's args.maxFindings by default)
 * @returns {{ kept: object[], skipped: object[] }} skipped = the lower-severity findings beyond the cap
 */
function capFindings(findings, max = REVIEW_CAP.maxFindings) {
  const rank = (f) => (f.severity in SEVERITY_RANK ? SEVERITY_RANK[f.severity] : 3)
  const cmp = (x, y) => (x < y ? -1 : x > y ? 1 : 0)
  const sorted = [...findings].sort(
    (a, b) =>
      rank(a) - rank(b) ||
      cmp(a.file ? 0 : 1, b.file ? 0 : 1) ||
      cmp(String(a.file || ''), String(b.file || '')) ||
      cmp(Number.isInteger(a.line) ? a.line : Infinity, Number.isInteger(b.line) ? b.line : Infinity) ||
      cmp(String(a.title || ''), String(b.title || ''))
  )
  const blocking = sorted.filter((f) => rank(f) < 2).length
  const keep = Math.max(blocking, max)
  const clipped = sorted.map((f) => (f && typeof f.excerpt === 'string' && f.excerpt.length > EXCERPT_LIMIT ? { ...f, excerpt: clipExcerpt(f.excerpt) } : f))
  return { kept: clipped.slice(0, keep), skipped: clipped.slice(keep) }
}

/**
 * Marks findings skipped by the cap as unverified so they are listed but never counted as checked.
 * @param {object[]} skipped from capFindings
 * @param {string} dimension the dimension key
 * @param {object} [extra] fields added to every entry
 * @returns {object[]}
 */
function capSkipped(skipped, dimension, extra = {}) {
  return skipped.map((f) => ({ ...f, dimension, ...extra, unverified: true, reason: 'review cap' }))
}

/**
 * The verifier-prompt block for a finding's reviewer-quoted excerpt, cut to EXCERPT_LIMIT characters.
 * @param {{ excerpt?: string }} f
 * @returns {string} empty when the finding has no excerpt
 */
function excerptBlock(f) {
  if (typeof f.excerpt !== 'string' || !f.excerpt.trim()) return ''
  const text = f.excerpt.endsWith(`\n${EXCERPT_MARKER}`) ? f.excerpt : clipExcerpt(f.excerpt)
  return `\nReviewer-quoted context (quoted by the reviewer, not verified; check it against the file before relying on it):\n${text}`
}

const REVIEW_VERDICT_SCHEMA = {
  type: 'object',
  required: ['real', 'reason'],
  properties: {
    real: { type: 'boolean' },
    reason: { type: 'string' },
    fixSize: { type: 'string', enum: ['trivial', 'small', 'large'] },
  },
}

const VERIFY_LENSES = {
  correctness: 'does the cited code really behave the way the finding claims?',
  reproducibility: 'can you name a concrete input, state or call path in this code that triggers it?',
  severity: 'this vote breaks a tie: weigh the evidence both ways and decide whether its impact makes it a real defect in this code',
}

/**
 * Tallies the verifier votes that returned for one finding.
 * @param {object[]} votes  verdict replies, nulls already removed
 * @param {number} needed  votes that decide the finding either way (2, or 1 for a minor design finding)
 * @returns {{confirmed: boolean, refuted: boolean, fixSize?: string, reasons: string[]}}
 *   refuted = at least `needed` votes returned real=false; fixSize is 'trivial' only when every yes vote says so
 */
function tallyVotes(votes, needed) {
  const yes = votes.filter((v) => v.real === true)
  const confirmed = yes.length >= needed
  const refuted = votes.filter((v) => v.real === false).length >= needed
  const out = { confirmed, refuted, reasons: yes.map((v) => v.reason).filter(Boolean) }
  if (confirmed) {
    const sizes = yes.map((v) => v.fixSize)
    out.fixSize = sizes.every((z) => z === 'trivial') ? 'trivial' : sizes.includes('large') ? 'large' : 'small'
  }
  return out
}

/**
 * Builds the verifier of a review: two votes (one for a minor design finding) and a severity tie-break
 * only when they split or one is missing. The lens line goes last so every vote on one finding shares its
 * prompt prefix up to it. In the Fix stage the same votes re-check a finding the agent reports fixed.
 * @param {{ subject: string, models: object }} ctx  subject = what is reviewed; models = the workflow's phase models
 * @returns {(f: object, dim: { key: string }, stage?: string) => Promise<object>}
 */
function makeFindingVerifier({ subject, models }) {
  const vote = (f, dim, lens, stage) =>
    runAgent(
      `You verify one finding from an adversarial code review of ${subject}. Try to REFUTE it: read the cited file and line in the actual code, and default real=false if you cannot confirm it there. Do not re-rate its severity. When it is real, set fixSize: trivial (a local change of a line or two), small (within one function or file) or large (several files, or a design change).${stage === 'Fix' ? ' A fix for it has just been applied: judge the code as it stands now.' : ''}
Finding (${dim.key}): "${f.title}" in ${f.file || '?'}${f.line ? ':' + f.line : ''}
${f.description || ''}${f.convention ? `\nConvention: ${f.convention}` : ''}${stage === 'Fix' ? '' : excerptBlock(f)}
Lens: ${lens} — ${VERIFY_LENSES[lens]}`,
      { label: `${stage === 'Fix' ? 'reverify' : 'verify'}:${dim.key}`, phase: stage, schema: REVIEW_VERDICT_SCHEMA, ...models.verify }
    )
  return async function verifyFinding(f, dim, stage = 'Review') {
    const single = dim.key === 'design' && f.severity === 'minor'
    const first = single
      ? [await vote(f, dim, 'correctness', stage)]
      : await parallel([() => vote(f, dim, 'correctness', stage), () => vote(f, dim, 'reproducibility', stage)])
    const votes = first.filter(Boolean)
    const label = stage === 'Fix' ? 'reverify' : 'verify'
    if (!votes.length) {
      log(`${label}:${dim.key} unavailable for "${f.title}"`)
      return { confirmed: false, refuted: false, unverified: true, reasons: [] }
    }
    if (!single && (votes.length === 1 || votes[0].real !== votes[1].real)) {
      const tie = await vote(f, dim, 'severity', stage)
      if (tie) votes.push(tie)
    }
    const tally = tallyVotes(votes, single ? 1 : 2)
    // A fix counts only when the votes refute the finding; missing or undecided votes leave it open.
    if (!tally.confirmed && !tally.refuted) {
      if (stage === 'Fix') log(`${label}:${dim.key} unavailable for "${f.title}"`)
      else return { ...tally, unverified: true }
    }
    return tally
  }
}

/** Whether a finding's severity blocks the shipping verdict: critical or major. */
function isBlockingFinding(f) {
  return !!f && (f.severity === 'critical' || f.severity === 'major')
}

const SHARED_REVIEW_DIMENSIONS = [
  { key: 'correctness', prompt: 'logic errors, edge cases, off-by-one, null handling, incorrect business rules' },
  { key: 'security', prompt: 'auth/authz gaps, injection, unvalidated field binding (over-posting), sensitive data exposure, missing validation' },
]

/**
 * The second, independent security pass over the risk areas a diff touches, on the read-only security-hunter.
 * Its findings go through the same verify as the reviewers'.
 * @param {object} o
 * @param {string} o.subject  what is reviewed, for the prompt
 * @param {{ repo: object, files: string[] }[]} o.riskScope  from riskFiles
 * @param {object[]} o.bases  base revisions from recordBases
 * @param {(repo: object) => string[]} o.changed  a repo's changed files
 * @param {object} o.models  the workflow's phase models (review)
 * @param {string} o.phase  phase label of the agent calls
 * @param {Function} o.verify  from makeFindingVerifier
 * @param {number} [o.maxFindings]  findings verified; the rest come back unverified with reason 'review cap'
 * @returns {Promise<{ unavailable: boolean, reviewed: object[] }>}
 */
async function runDeepSecurity({ subject, riskScope, bases, changed, models, phase, verify, maxFindings = REVIEW_CAP.maxFindings }) {
  const deep = await runAgent(
    `Run a second, independent security review of ${subject}, limited to the risk areas the changes touch. Do not rely on any earlier review; read the code yourself.
Read the changes from git, per repo:
${reviewDiffLines(riskScope.map((x) => x.repo), bases, changed, (r) => (riskScope.find((x) => x.repo === r) || {}).files)}
Risk files:
${riskScope.map((x) => `- ${x.repo.path}: ${x.files.join(', ')}`).join('\n')}
${securityReviewText(riskScope.map((x) => x.repo))}
Report concrete findings only, with file and line. ${EXCERPT_RULE}`,
    { label: 'review:security-deep', phase, schema: FINDINGS_SCHEMA, agentType: DEEP_SECURITY_AGENT, ...models.review }
  )
  if (!deep) {
    log('review:security-deep unavailable')
    return { unavailable: true, reviewed: [] }
  }
  const secDim = { key: 'security' }
  const { kept, skipped } = capFindings(deep.findings || [], maxFindings)
  const checked = await parallel(kept.map((f) => () => verify(f, secDim, phase).then((v) => ({ ...f, dimension: 'security', deepPass: true, ...v }))))
  const reviewed = [...checked, ...capSkipped(skipped, 'security', { deepPass: true })]
  return { unavailable: false, reviewed }
}

/**
 * Reviews the diff of a run on correctness and security: each dimension on its reviewer, a second security
 * pass when the diff touches a risk area, and every finding through the two-vote verify.
 * A dimension whose reviewer returned nothing is `unavailable`, never clean. A finding no verifier answered for
 * is `unverified` and stays open.
 * @param {object} o
 * @param {string} o.subject  what is reviewed, for the prompts
 * @param {object[]} o.repos  repos in the review
 * @param {object[]} o.bases  base revisions from recordBases
 * @param {(repo: object) => string[]} o.changed  a repo's changed files
 * @param {object} o.models  the workflow's phase models (review, verify)
 * @param {string} [o.phase]  phase label of the agent calls
 * @param {{ key: string, prompt: string }[]} [o.dims]  review dimensions
 * @param {ReturnType<typeof makeFindingVerifier>} [o.verify]  the workflow's verifier, when it reuses one after the review
 * @param {number} [o.maxFindings]  findings verified per dimension (the run's cap by default); the rest are returned in `unverified` with reason 'review cap'
 * @param {string} [o.context]  one extra line for every reviewer prompt, e.g. the changed files
 * @param {(dim: { key: string }) => object} [o.schemaFor]  the reply schema of a dimension (FINDINGS_SCHEMA by default)
 * @param {(review: object, dim: { key: string }) => object[]} [o.findingsOf]  the findings to verify from a dimension's reply (all of its findings by default); the place for per-dimension verdict handling and filters
 * @returns {Promise<{ confirmed: object[], unverified: object[], unavailable: string[], securityReview: { ran: boolean, deep: 'ran'|'skipped'|'unavailable', findings: number }, noChanges: boolean, deep: { files: number, unavailable: boolean, blocking: number } }>}
 */
async function reviewDiff({ subject, repos, bases, changed, models, phase = 'Review', dims = SHARED_REVIEW_DIMENSIONS, verify = makeFindingVerifier({ subject, models }), context = '', schemaFor = () => FINDINGS_SCHEMA, findingsOf = (review) => review.findings || [], maxFindings = REVIEW_CAP.maxFindings }) {
  const unavailable = []
  const riskScope = riskFiles(repos, changed)
  // The deep pass starts with the dimension reviewers; it reads the code itself and needs none of their output.
  const deepRun = riskScope.length ? runDeepSecurity({ subject, riskScope, bases, changed, models, phase, verify, maxFindings }) : Promise.resolve({ unavailable: false, reviewed: [] })
  const reviewed = await parallel(dims.map((dim) => async () => {
    const review = await runAgent(
      `Adversarially review the changes for ${subject} on the ${dim.key} dimension. Look specifically for: ${dim.prompt}.
Read the changes from git, per repo:
${reviewDiffLines(repos, bases, changed)}${context ? `\n${context}` : ''}
Question every pattern — do not assume correctness. Report concrete findings only, with file and line where possible. ${EXCERPT_RULE}${dim.key === 'security' ? `\n${securityReviewText(repos)}` : ''}`,
      { label: `review:${dim.key}`, phase, schema: schemaFor(dim), ...(dim.key === 'security' ? { agentType: SECURITY_AGENT } : {}), ...models.review }
    )
    if (!review) {
      unavailable.push(dim.key)
      log(`review:${dim.key} unavailable`)
      return []
    }
    const { kept, skipped } = capFindings(findingsOf(review, dim), maxFindings)
    const checked = await parallel(kept.map((f) => () => verify(f, dim, phase).then((v) => ({ ...f, dimension: dim.key, ...v }))))
    return [...checked, ...capSkipped(skipped, dim.key)]
  }))
  const { unavailable: deepUnavailable, reviewed: deepReviewed } = await deepRun
  const all = [...reviewed.flat(), ...deepReviewed].filter(Boolean)
  const confirmed = all.filter((f) => f.confirmed).map((f, i) => ({ id: `F${i + 1}`, ...f }))
  const unverified = all.filter((f) => f.unverified).map((f, i) => ({ id: `U${i + 1}`, ...f }))
  return {
    confirmed,
    unverified,
    unavailable,
    securityReview: securityReviewResult({
      ran: !unavailable.includes('security'),
      deep: deepState(riskScope.length, deepUnavailable),
      findings: confirmed.filter((f) => f.dimension === 'security').length,
    }),
    noChanges: !repos.some((r) => changed(r).length),
    deep: { files: riskScope.length, unavailable: deepUnavailable, blocking: [...confirmed, ...unverified].filter((f) => f.deepPass && isBlockingFinding(f)).length },
  }
}

/**
 * The ledger entries a diff review adds: one per dimension, the security-ran entry and the second security pass.
 * @param {Awaited<ReturnType<typeof reviewDiff>>} review
 * @param {{ key: string }[]} [dims]
 * @returns {object[]}
 */
function reviewEntries(review, dims = SHARED_REVIEW_DIMENSIONS) {
  const open = [...review.confirmed, ...review.unverified].filter(isBlockingFinding)
  return [
    ...dims.map((d) =>
      review.unavailable.includes(d.key)
        ? assure(`review:${d.key}`, 'unavailable', 'the reviewer returned nothing')
        : open.some((f) => f.dimension === d.key)
          ? assure(`review:${d.key}`, 'fail', `${open.filter((f) => f.dimension === d.key).length} critical or major finding(s)`)
          : assure(`review:${d.key}`, 'pass')
    ),
    securityRanEntry(review.securityReview, review.noChanges),
    securityDeepEntry(review.deep),
  ]
}

// --- Test integrity ---------------------------------------------------------
// A run must not make its tests pass by deleting or rewriting them. Test paths and skip or focus
// markers come from the stack manifest; the agent only reports what git shows.
const TEST_INTEGRITY_SCHEMA = {
  type: 'object',
  required: ['files', 'markers'],
  properties: {
    files: {
      type: 'array',
      items: {
        type: 'object',
        required: ['file', 'status'],
        properties: { file: { type: 'string' }, status: { type: 'string', enum: ['deleted', 'modified', 'added'] } },
      },
    },
    markers: {
      type: 'array',
      items: { type: 'object', required: ['file', 'marker'], properties: { file: { type: 'string' }, marker: { type: 'string' } } },
    },
  },
}

/**
 * The read-only steps that show how a run changed the tests of one repo.
 * @param {string} dir a validated repo path
 * @param {string} sha a validated revision id (isCommitSha)
 * @param {string[]} skipMarkers the manifest's skip and focus markers
 * @param {string[]} [testPaths] the manifest's test-path patterns
 * @returns {string}
 */
function testIntegrityStepText(dir, sha, skipMarkers, testPaths) {
  const paths = JSON.stringify(Array.isArray(testPaths) ? testPaths : [])
  return `Test integrity. Run exactly these read-only git commands and no other git command:
   git -C "${dir}" diff --name-status ${sha}
   git -C "${dir}" ls-files --others --exclude-standard
   files = one entry per line of the first command: status "deleted" for D (and for the old path of a rename), "modified" for M, "added" for A.
   Test files are the files whose path matches one of these regular expressions: ${paths}. Look only at test files; ignore every other file.
   For the markers, run \`git -C "${dir}" diff -U0 ${sha} -- <test files>\` once, naming only the changed test files (and read only the untracked test files from the second command).
   markers = every added line ("+" lines of that diff, and the lines of the untracked test files) that contains one of these exact markers: ${JSON.stringify(skipMarkers)}. Give the test file and the marker it contains.
   Never stash, reset, checkout, clean or make commits.`
}

/**
 * Whether a built task names a file, in its files list or anywhere in its text.
 * @param {Array<{ title?: string, files?: string[], approach?: string, verify?: string }>} tasks the built tasks
 * @param {string} file repo-relative path
 * @returns {boolean}
 */
function namedByTask(tasks, file) {
  const target = normalFile(file)
  return (tasks || []).some((t) =>
    (Array.isArray(t.files) ? t.files : []).some((f) => normalFile(f) === target) ||
    [t.title, t.approach, t.verify].some((text) => typeof text === 'string' && text.includes(target)))
}

/** Test-path patterns from a manifest as regular expressions; an invalid pattern is dropped. */
function testPathMatchers(patterns) {
  return (Array.isArray(patterns) ? patterns : []).flatMap((p) => {
    try { return [new RegExp(p)] } catch { return [] }
  })
}

/**
 * Judges one repo's test-integrity answer against the manifest data. A deleted test file, a modified
 * one no built task names, and an added marker the manifest lists fail. Files that were already dirty at
 * the base, added files and files outside the manifest's test paths are not judged; a marker the manifest
 * does not list is dropped, so the agent cannot invent a failure.
 * @param {object|null} raw the agent answer (files, markers)
 * @param {{ dirty?: string[] }} base the repo's base entry
 * @param {{ testPaths?: string[], skipMarkers?: string[] }} rules the manifest's test-integrity data
 * @param {(file: string) => boolean} named whether a built task names the file
 * @returns {{ status: string, reason: string, deleted: string[], modified: string[], markers: object[] }}
 */
function judgeTestIntegrity(raw, base, rules, named) {
  if (!raw || !Array.isArray(raw.files) || !Array.isArray(raw.markers)) {
    return { status: 'unavailable', reason: 'the test-integrity check did not return', deleted: [], modified: [], markers: [] }
  }
  const matchers = testPathMatchers(rules.testPaths)
  const markerList = Array.isArray(rules.skipMarkers) ? rules.skipMarkers : []
  const dirty = (base.dirty || []).map((f) => normalFile(f))
  const isTest = (f) => matchers.some((m) => m.test(f))
  const entries = raw.files
    .map((e) => ({ file: normalFile(e && e.file), status: e && e.status }))
    .filter((e) => e.file && isTest(e.file) && !dirty.includes(e.file))
  const deleted = [...new Set(entries.filter((e) => e.status === 'deleted').map((e) => e.file))]
  const modified = [...new Set(entries.filter((e) => e.status === 'modified').map((e) => e.file))].filter((f) => !named(f))
  const seen = new Set()
  const markers = raw.markers
    .map((m) => ({ file: normalFile(m && m.file), marker: m && m.marker }))
    .filter((m) => m.file && isTest(m.file) && !dirty.includes(m.file) && markerList.includes(m.marker))
    .filter((m) => !seen.has(`${m.file}\n${m.marker}`) && seen.add(`${m.file}\n${m.marker}`))
  const problems = [
    deleted.length ? `deleted: ${deleted.join(', ')}` : '',
    modified.length ? `modified without a task naming it: ${modified.join(', ')}` : '',
    markers.length ? `added ${markers.map((m) => `${m.marker} in ${m.file}`).join(', ')}` : '',
  ].filter(Boolean)
  return { status: problems.length ? 'fail' : 'pass', reason: problems.join('; '), deleted, modified, markers }
}

/**
 * Runs the test-integrity check for every repo. A repo with tracked !== true, without a valid base, or
 * whose manifest declares neither test paths nor markers is skipped and runs no step.
 * @param {Array<{ path: string, role: string, stack?: string, tracked?: boolean }>} repoList
 * @param {Array<{ repo: string, sha?: string, dirty?: string[] }>} bases
 * @param {{ roots?: Set<string>, run: (prompt: string, repo: object) => Promise<object|null>, rulesFor: (repo: object) => { testPaths?: string[], skipMarkers?: string[] }, named: (file: string, repo: object) => boolean }} opts
 * @returns {Promise<Array<{ repo: string, status: string, reason: string, deleted?: string[], modified?: string[], markers?: object[] }>>}
 */
async function checkTestIntegrity(repoList, bases, opts) {
  return Promise.all(repoList.map(async (repo) => {
    const skip = (reason) => ({ repo: repo.path, role: repo.role, status: 'skipped', reason })
    const base = bases.find((b) => b.repo === repo.path)
    if (repo.tracked !== true || !isRepoPath(repo.path, opts.roots) || !base || !isCommitSha(base.sha)) return skip('no git base to compare against')
    const rules = opts.rulesFor(repo) || {}
    const markerList = Array.isArray(rules.skipMarkers) ? rules.skipMarkers.filter((m) => typeof m === 'string' && m && !/[\r\n]/.test(m)) : []
    if (!testPathMatchers(rules.testPaths).length && !markerList.length) return skip('the stack manifest declares no test paths or markers')
    const raw = await opts.run(`Check the tests of the ${repo.role} repo at "${repo.path}" against the run's starting point. Use Bash. Change nothing.\n1. ${testIntegrityStepText(repo.path, base.sha, markerList, rules.testPaths)}\nReturn files and markers.`, repo)
    return { repo: repo.path, role: repo.role, ...judgeTestIntegrity(raw, base, { ...rules, skipMarkers: markerList }, (f) => opts.named(f, repo)) }
  }))
}

/**
 * The one assurance entry of the check: fail on any failed repo, unavailable when one did not return,
 * skipped when no repo was checked, else pass.
 * @param {Array<{ repo: string, status: string, reason: string }>} results
 * @returns {{ check: string, status: string, reason: string }}
 */
function testIntegrityEntry(results) {
  const list = Array.isArray(results) ? results : []
  const failed = list.filter((r) => r.status === 'fail')
  if (failed.length) return assure('test-integrity', 'fail', failed.map((r) => `${r.repo}: ${r.reason}`).join(' | '))
  const missing = list.filter((r) => r.status === 'unavailable')
  if (missing.length) return assure('test-integrity', 'unavailable', missing.map((r) => `${r.repo}: ${r.reason}`).join(' | '))
  if (!list.some((r) => r.status === 'pass')) return assure('test-integrity', 'skipped', list.map((r) => r.reason).find(Boolean) || 'no repo to check')
  return assure('test-integrity', 'pass')
}

// --- Security review ----------------------------------------------------------
// The security dimension runs on the security-auditor agent. A diff that touches a risk area also gets a
// second, independent pass. Risk paths are neutral defaults plus the stack manifest's own patterns.
const SECURITY_AGENT = 'security-auditor'
// The read-only analyst for the second, independent security pass; resolved through runAgent.
const DEEP_SECURITY_AGENT = 'security-hunter'
const SECURITY_CHECKLIST = 'authorization per role (every route, action and query checks who may do it, and a user cannot reach another user\'s data), input validation, injection (query, command, template, path), mass assignment, secrets (none committed, none logged), file handling (type, size, storage path, serving) and data exposure (responses, logs, errors)'
const NEUTRAL_RISK_PATHS = [
  '(^|/)(auth|authn|authz|login|logout|signin|signup|password|passwords|permission|permissions|policy|policies|acl|oauth|jwt|session|sessions|guards?)([/._-]|$)',
  '(^|/)(routes?|controllers?|middleware|api)([/._-]|$)',
  '(^|/)migrations?/',
  '(^|/)(uploads?|attachments?|storage)([/._-]|$)',
  '(^|/)(payments?|billing|checkout|invoices?)([/._-]|$)',
  '\\.lock$',
  '(^|/)([a-z-]*-lock\\.(json|ya?ml)|go\\.sum|package\\.json|pyproject\\.toml|Gemfile|go\\.mod|Cargo\\.toml)$',
  '(^|/)\\.env([._-][^/]*)?$',
  '(^|/)\\.github/workflows/',
  '(^|/)\\.gitlab-ci\\.ya?ml$',
  '(^|/)(bitbucket-pipelines\\.ya?ml|azure-pipelines\\.ya?ml|Jenkinsfile)$',
  '(^|/)\\.circleci/',
  '(^|/)(Dockerfile|docker-compose[^/]*\\.ya?ml)$',
]

/**
 * Skill names the stack manifest lists for the security reviewer; empty for an untrusted overlay.
 * @param {string} stack Stack key.
 * @returns {string[]}
 */
function securitySkillsFor(stack) {
  const s = extrasFor(stack).security
  return s && Array.isArray(s.skills) ? s.skills : []
}

/**
 * The risk patterns for a stack: neutral defaults, then the manifest's riskPaths.
 * @param {string} stack Stack key.
 * @returns {string[]}
 */
function riskPathsFor(stack) {
  const s = extrasFor(stack).security
  return NEUTRAL_RISK_PATHS.concat(s && Array.isArray(s.riskPaths) ? s.riskPaths : [])
}

// --- doc impact: begin ---
const DOC_IMPACT_KINDS = ['endpoint', 'schema', 'business-rule', 'config', 'agent-instructions']
const DOC_IMPACT_STATUSES = ['updated', 'created', 'not-affected']
const DOC_IMPACT_NONE = 'none found'
const DOC_DEFAULT_PATHS = ['docs/context', 'docs/api']
const DOC_IMPACT_NONE_RULE = `For an item marked "${DOC_IMPACT_NONE}": return status not-affected with the reason "no doc owns this", or, when the project uses the default doc paths (${DOC_DEFAULT_PATHS.map((d) => `${d}/`).join(', ')}), create the default doc for that kind and return status created.`
// Neutral defaults cover configuration and agent instruction files only; where a stack keeps its endpoints
// and schema changes is stack knowledge, so those patterns come from the stack manifests' docImpact.
const DOC_IMPACT_DEFAULTS = {
  endpoint: [],
  schema: [],
  'business-rule': ['(^|/)business-rules[^/]*$'],
  config: ['(^|/)\\.env[^/]*$', '(^|/)config/'],
  'agent-instructions': ['(^|/)(CLAUDE|AGENTS)\\.md$', '(^|/)\\.claude/'],
}

/**
 * The path patterns of each doc-impact kind: the neutral defaults plus what the stack manifests add.
 * A kind outside DOC_IMPACT_KINDS and a pattern that is not a valid regular expression are dropped.
 * @param {object} [manifest] kind -> patterns, as merged from the stack manifests
 * @returns {Object<string, string[]>}
 */
function docImpactRules(manifest) {
  const extra = manifest && typeof manifest === 'object' ? manifest : {}
  const valid = (p) => {
    if (typeof p !== 'string' || !p) return false
    try {
      new RegExp(p, 'i')
      return true
    } catch (e) {
      return false
    }
  }
  const rules = {}
  for (const kind of DOC_IMPACT_KINDS) {
    const added = hasOwn(extra, kind) && Array.isArray(extra[kind]) ? extra[kind].filter(valid) : []
    rules[kind] = [...new Set([...DOC_IMPACT_DEFAULTS[kind], ...added])]
  }
  return rules
}

/**
 * The doc-impact patterns the repos' stack manifests declare, merged per kind.
 * @param {Array<{ stack: string }>} repoList
 * @returns {Object<string, string[]>}
 */
function docImpactManifestFor(repoList) {
  const merged = {}
  for (const repo of repoList) {
    const declared = extrasFor(repo.stack).docImpact
    if (!declared || typeof declared !== 'object') continue
    for (const kind of Object.keys(declared)) {
      if (Array.isArray(declared[kind])) merged[kind] = (merged[kind] || []).concat(declared[kind])
    }
  }
  return merged
}

/**
 * One item per kind found in the changed files, with the doc that owns it. The owner is the first
 * investigation doc tagged with that kind; DOC_IMPACT_NONE when no doc was named.
 * @param {string[]} files changed files
 * @param {Object<string, string[]>} rules from docImpactRules
 * @param {Array<{ path: string, kind?: string }>} [docs] docs the investigation flagged
 * @returns {Array<{ kind: string, files: string[], target: string }>}
 */
function docImpactItems(files, rules, docs = []) {
  const list = (Array.isArray(files) ? files : []).map(normalFile)
  return DOC_IMPACT_KINDS.flatMap((kind) => {
    const res = (rules[kind] || []).map((p) => new RegExp(p, 'i'))
    const hit = [...new Set(list.filter((f) => res.some((re) => re.test(f))))]
    if (!hit.length) return []
    const owner = (Array.isArray(docs) ? docs : []).find((d) => d && d.kind === kind && isDocPath(d.path))
    return [{ kind, files: hit, target: owner ? owner.path : DOC_IMPACT_NONE }]
  })
}

/**
 * Matches the Docs agent's entries to the impact items. An entry counts only with one of the three
 * statuses; it answers an item by kind, or by target when the kind is missing.
 * @param {Array<{ kind: string, target: string }>} items
 * @param {Array<{ kind?: string, target?: string, status?: string, reason?: string }>} entries
 * @returns {{ entries: object[], missing: string[] }} missing = kinds of the items with no entry
 */
function docImpactResults(items, entries) {
  const valid = (Array.isArray(entries) ? entries : []).filter((e) => e && typeof e.target === 'string' && DOC_IMPACT_STATUSES.includes(e.status))
  const answered = (item) => valid.some((e) => (e.kind ? e.kind === item.kind : item.target !== DOC_IMPACT_NONE && e.target === item.target))
  return { entries: valid, missing: items.filter((i) => !answered(i)).map((i) => i.kind) }
}

/**
 * The ledger entry of the docs check: unavailable when an impact item has no entry.
 * @param {string[]} missing kinds without an entry
 * @returns {{check: string, status: string, reason: string}}
 */
function docsAssurance(missing) {
  return missing.length ? assure('docs', 'unavailable', `no docs entry for ${missing.join(', ')}`) : assure('docs', 'pass')
}
/**
 * Ledger entries for a Detect call that returned nothing: the run then works on the fallback repo, which
 * is a guess, not a verified layout.
 * @param {object|null} project the Detect result
 * @param {string|null} [failure] the message when the Detect call threw
 * @returns {{check: string, status: string, reason: string}[]} empty when Detect answered
 */
function detectAssurance(project, failure) {
  return project && typeof project === 'object' && !failure ? [] : [assure('detect', 'unavailable', failure || 'Detect returned no result')]
}
/** Grader result shared by the docs check and qa-and-docs; phantomLinks are claims that resolve to no real code. */
const GRADE_SCHEMA = {
  type: 'object',
  required: ['verdict'],
  properties: {
    completeness: { type: 'integer' },
    helpfulness: { type: 'integer' },
    truthfulness: { type: 'integer' },
    phantomLinks: { type: 'array', items: { type: 'string' } },
    uncoveredCriteria: { type: 'array', items: { type: 'string' } },
    verdict: { type: 'string', enum: ['PASS', 'CHANGES_REQUIRED'] },
    notes: { type: 'string' },
  },
}

/**
 * Prompt of the one grader call that checks the written docs against the code.
 * @param {string} feature label of the shipped work
 * @param {string[]} docPaths updated and created docs
 * @param {Array<{ doc: string, heading: string }>} [sections] sections the Docs agent reports it changed; the grade is limited to them
 * @returns {string}
 */
function docsGradePrompt(feature, docPaths, sections = []) {
  const scoped = (Array.isArray(sections) ? sections : []).filter((x) => x && typeof x.doc === 'string' && typeof x.heading === 'string')
  const scope = scoped.length
    ? `\nChanged sections: ${JSON.stringify(scoped)}\nCheck only those sections of the docs they name; a doc with no section listed was created by this run, so check it whole. Do not report claims outside that scope, even stale ones.`
    : ''
  return `Act as a strict Verifier. Check each of these docs against the ACTUAL code. Read the code; do not trust the docs.
Feature: ${feature}
Docs: ${JSON.stringify(docPaths)}${scope}

phantomLinks = every claim in ${scoped.length ? 'that scope' : 'these docs'} (endpoint, route, class, function, command, config key, file path) that does NOT resolve to real code, one string per claim naming the doc. verdict = CHANGES_REQUIRED if there is any phantom link, else PASS.`
}

/**
 * Prompt that sends phantom links back for one repair round.
 * @param {string[]} phantoms claims that did not resolve
 * @param {{ docs?: string[], entries?: object[] }} [prior] the docs written so far and their impact entries
 * @returns {string}
 */
function docsRepairPrompt(phantoms, prior = {}) {
  const docs = Array.isArray(prior.docs) ? prior.docs : []
  const entries = Array.isArray(prior.entries) ? prior.entries : []
  return `A check of the docs you just wrote found claims that do not resolve to real code (phantom links):
${phantoms.map((p) => `- ${p}`).join('\n')}
Fix each one in the docs: correct it to what the code does, or remove it. Touch nothing else. Edit only docs, never code.${docs.length ? `\nDocs written so far: ${JSON.stringify(docs)}` : ''}${entries.length ? `\nImpact entries so far: ${JSON.stringify(entries)}` : ''}
Return the docs you changed in this round, with their changed sections; keep the entries above unless a fix changes one.`
}

const DOC_FILE_RE = /\.mdx?$/i
const OPENAPI_RE = /^docs\/(?:.*\/)?(?:openapi|swagger)[^/]*\.(?:ya?ml|json)$/i

/**
 * True for a path the Docs agent may write: a plain relative Markdown file, or an OpenAPI file under docs/,
 * outside .git/, .github/ and the Claude settings files.
 * @param {string} p
 * @returns {boolean}
 */
function isDocPath(p) {
  if (typeof p !== 'string' || !p.trim() || /[\n\0]/.test(p) || p.startsWith('/')) return false
  const parts = p.trim().replace(/^\.\//, '').split(/[\\/]/)
  if (parts.includes('..') || parts.includes('.git') || parts.includes('.github')) return false
  const at = parts.indexOf('.claude')
  if (at >= 0 && /^settings/i.test(parts[at + 1] || '')) return false
  return DOC_FILE_RE.test(p) || OPENAPI_RE.test(parts.join('/'))
}

/**
 * The files the Docs phase changed that are not doc files (see isDocPath), so code or config edited by a
 * Docs agent is not shipped unreviewed.
 * @param {string[]} changed files changed since the snapshot taken before Docs
 * @returns {string[]}
 */
function nonDocChanges(changed) {
  return [...new Set((Array.isArray(changed) ? changed : []).map((f) => normalFile(f)).filter((f) => f && !isDocPath(f)))]
}

/**
 * Ledger entry of the Docs-only rule: fail when a file other than a doc changed during Docs.
 * @param {string[]} offending result of nonDocChanges
 * @returns {{check: string, status: string, reason: string}|null} null when nothing outside the docs changed
 */
function docsScopeAssurance(offending) {
  return offending.length ? assure('docs', 'fail', `the Docs phase changed file(s) that are not docs: ${offending.join(', ')}`) : null
}

/**
 * Folds a repair round into the Docs result: doc lists are united, entries and sections come from the
 * repair when it returned any, else stay as they were.
 * @param {object|null} prev result of the first Docs call
 * @param {object|null} repair result of the repair call
 * @returns {object|null}
 */
function mergeDocsResult(prev, repair) {
  if (!prev || !repair) return prev || repair
  const list = (o, key) => (Array.isArray(o[key]) ? o[key] : [])
  const merged = { ...prev, ...repair }
  for (const key of ['updatedDocs', 'newDocs', 'skipped', 'files', 'runCommands']) {
    if (key in prev || key in repair) merged[key] = [...new Set([...list(prev, key), ...list(repair, key)])]
  }
  if ('changedSections' in prev || 'changedSections' in repair) merged.changedSections = [...list(prev, 'changedSections'), ...list(repair, 'changedSections')]
  const entries = Array.isArray(repair.entries) && repair.entries.length ? repair.entries : prev.entries
  if (entries) merged.entries = entries
  return merged
}

/**
 * Phantom links of a grader result.
 * @param {{ phantomLinks?: string[] } | null} grade
 * @returns {string[]}
 */
function phantomLinksOf(grade) {
  return grade && Array.isArray(grade.phantomLinks) ? grade.phantomLinks.filter((p) => typeof p === 'string' && p.trim()) : []
}

/**
 * Every doc a Docs result says it wrote: its updated and created lists, the targets of entries marked updated
 * or created, and the docs of its changed sections. Only plain relative doc paths count (isDocPath).
 * @param {{ updatedDocs?: string[], newDocs?: string[], entries?: object[], changedSections?: object[] }|null} result
 * @returns {string[]}
 */
function docsWrittenBy(result) {
  if (!result) return []
  const list = (key) => (Array.isArray(result[key]) ? result[key] : [])
  const fromEntries = list('entries').filter((e) => e && (e.status === 'updated' || e.status === 'created')).map((e) => e.target)
  const fromSections = list('changedSections').map((x) => x && x.doc)
  return [...new Set([...list('updatedDocs'), ...list('newDocs'), ...fromEntries, ...fromSections].filter((d) => typeof d === 'string' && isDocPath(d)))]
}

/**
 * The docs check of a run: one grader call over the docs written, one repair round when it finds phantom links,
 * and one more grader call after the repair.
 * @param {object} o
 * @param {object} o.result the docs agent's result
 * @param {(result: object) => Promise<object|null>} o.grade runs the grader on the docs of a result
 * @param {(phantoms: string[], result: object) => Promise<object|null>} o.repair runs the repair round
 * @param {string} [o.label] log prefix, the phase name
 * @returns {Promise<{ result: object, entry: {check: string, status: string, reason: string} }>} the result with the repair merged, and the ledger entry
 */
async function checkDocs({ result, grade, repair, label = 'Docs' }) {
  let current = result
  let graded = await grade(current)
  let phantoms = phantomLinksOf(graded)
  if (phantoms.length) {
    log(`${label}: ${phantoms.length} phantom link(s); one repair round.`)
    const repaired = await repair(phantoms, current)
    if (repaired) current = mergeDocsResult(current, repaired)
    graded = await grade(current)
    phantoms = phantomLinksOf(graded)
  }
  return { result: current, entry: docsGradeAssurance(phantoms, !!graded) }
}

/**
 * A file list for a prompt, cut to `max` names with a count of the rest, so a large change does not repeat
 * hundreds of paths in every prompt. The agent reads the full list from git.
 * @param {string[]} files
 * @param {number} [max]
 * @returns {string} '' when the list is empty
 * @example fileListText(['a', 'b', 'c'], 2)  // 'a, b and 1 more'
 */
function fileListText(files, max = 20) {
  const list = Array.isArray(files) ? files : []
  if (list.length <= max) return list.join(', ')
  return `${list.slice(0, max).join(', ')} and ${list.length - max} more`
}

/**
 * Ledger entry of the docs check after the grader and the one repair round.
 * @param {string[]} remaining phantom links left after the repair round
 * @param {boolean} graded false when the grader returned nothing
 * @returns {{check: string, status: string, reason: string}}
 */
function docsGradeAssurance(remaining, graded) {
  if (!graded) return assure('docs', 'unavailable', 'the docs grader returned no result')
  return remaining.length ? assure('docs', 'fail', `phantom link(s) remain: ${remaining.join('; ')}`) : assure('docs', 'pass')
}
const DOC_OWNERS_SCHEMA = {
  type: 'object',
  required: ['owners'],
  properties: {
    owners: {
      type: 'array',
      items: {
        type: 'object',
        required: ['kind', 'target'],
        properties: { kind: { type: 'string', enum: DOC_IMPACT_KINDS }, target: { type: 'string' } },
      },
    },
  },
}

/**
 * The business-rule item of a spec that cites rule ids, when the changed files did not already yield one.
 * @param {Array<{ kind: string, files: string[], target: string }>} items
 * @param {string[]} [ruleIds] the spec's brs
 * @returns {Array<{ kind: string, files: string[], target: string }>}
 */
function withBusinessRuleItem(items, ruleIds) {
  const ids = (Array.isArray(ruleIds) ? ruleIds : []).map(String).filter(Boolean)
  if (!ids.length || items.some((i) => i.kind === 'business-rule')) return items
  return [...items, { kind: 'business-rule', files: ids, target: DOC_IMPACT_NONE }]
}

/**
 * The read-only prompt that maps each impact kind to the doc that owns it.
 * @param {Array<{ kind: string, files: string[] }>} items
 * @returns {string}
 */
function docOwnersPrompt(items) {
  return `Find which existing doc owns each kind of change below in this project. Read only; change nothing.
Kinds: ${items.map((i) => `${i.kind} (${fileListText(i.files, 10)})`).join('; ')}
Look in this order and stop at the first hit per kind:
1. The "Always load" list in CLAUDE.md or AGENTS.md: the doc there that covers the kind.
2. The default doc paths: ${DOC_DEFAULT_PATHS.join(', ')}.
3. A search of the repo's docs (README files, docs/, OpenAPI files) for the doc that describes that area.
Return owners: one { kind, target } per kind, target a path that exists, or "${DOC_IMPACT_NONE}" when no doc owns the kind.`
}

/**
 * Applies the mapper's answer to the items. A kind outside DOC_IMPACT_KINDS, a kind that is not an item
 * and a target that is not a plain relative doc path (see isDocPath) are dropped; the item then keeps its target.
 * @param {Array<{ kind: string, files: string[], target: string }>} items
 * @param {{ owners?: Array<{ kind?: string, target?: string }> }|null} mapped
 * @returns {Array<{ kind: string, files: string[], target: string }>}
 */
function applyDocOwners(items, mapped) {
  const owners = mapped && Array.isArray(mapped.owners) ? mapped.owners : []
  const safe = (t) => isDocPath(t)
  return items.map((item) => {
    if (item.target !== DOC_IMPACT_NONE) return item
    const hit = owners.find((o) => o && o.kind === item.kind && DOC_IMPACT_KINDS.includes(o.kind) && safe(o.target))
    return hit ? { ...item, target: hit.target.trim() } : item
  })
}

/** True when an item has an owning doc, so the Docs agent has something to update. */
function docImpactOwned(items) {
  return items.some((i) => i.target !== DOC_IMPACT_NONE)
}
// --- doc impact: end ---

/**
 * The changed files that touch a risk area, per repo. A pattern that is not a valid regular expression
 * is ignored, so a bad manifest entry cannot stop the run.
 * @param {Array<{ path: string, stack: string }>} repoList
 * @param {(repo: object) => string[]} changed changed files of one repo
 * @returns {Array<{ repo: object, files: string[] }>} only repos with at least one risk file
 */
function riskFiles(repoList, changed) {
  return repoList
    .map((repo) => {
      const rules = riskPathsFor(repo.stack).flatMap((p) => {
        try {
          return [new RegExp(p, 'i')]
        } catch (e) {
          return []
        }
      })
      const files = (changed(repo) || []).filter((f) => rules.some((re) => re.test(normalFile(f))))
      return { repo, files }
    })
    .filter((x) => x.files.length)
}

/**
 * The prompt lines that make the security dimension a checklist review with the stack's skills.
 * @param {Array<{ role: string, stack: string }>} repoList
 * @returns {string}
 */
function securityReviewText(repoList) {
  const skills = Array.from(new Set(repoList.flatMap((r) => securitySkillsFor(r.stack))))
  return `Work through this checklist on the changed code: ${SECURITY_CHECKLIST}. Change no file and write nothing to git or memory.${skills.length ? `\nSkills to consult: ${skills.join(', ')}.` : ''}`
}

/**
 * The ledger entry for the second security pass.
 * @param {{ files: number, unavailable: boolean, blocking: number }} facts files = risk files found
 * @returns {object}
 */
function securityDeepEntry(facts) {
  if (!facts.files) return assure('security:deep', 'skipped', 'no risk area touched')
  if (facts.unavailable) return assure('security:deep', 'unavailable', 'the second security reviewer returned nothing')
  if (facts.blocking) return assure('security:deep', 'fail', `${facts.blocking} critical or major finding(s) in a risk area`)
  return assure('security:deep', 'pass')
}

const SECURITY_DEEP_STATES = ['ran', 'skipped', 'unavailable']

/**
 * The securityReview block of a workflow result. `deep` is 'ran' when the second pass returned, 'skipped'
 * when no risk area was touched and 'unavailable' when it was needed and did not return. `findings` is the
 * number of confirmed security findings.
 * @param {{ ran: boolean, deep: 'ran'|'skipped'|'unavailable', findings: number }} facts
 * @returns {{ ran: boolean, deep: 'ran'|'skipped'|'unavailable', findings: number }}
 * @throws {Error} when deep is not one of the three states
 */
function securityReviewResult(facts) {
  if (!SECURITY_DEEP_STATES.includes(facts.deep)) throw new Error(`securityReviewResult: unknown deep state ${JSON.stringify(facts.deep)}; use ${SECURITY_DEEP_STATES.join(', ')} (deepState() computes it)`)
  return { ran: !!facts.ran, deep: facts.deep, findings: facts.findings || 0 }
}

/**
 * State of the second security pass.
 * @param {number} riskFileCount risk files the changes touch
 * @param {boolean} unavailable the pass was needed and returned nothing
 * @returns {'ran'|'skipped'|'unavailable'}
 */
function deepState(riskFileCount, unavailable) {
  if (!riskFileCount) return 'skipped'
  return unavailable ? 'unavailable' : 'ran'
}

/**
 * Ledger entry: the shipping verdict requires the security review to have run.
 * A run that changed no file has nothing to review, so the entry is skipped and holds nothing.
 * @param {{ ran: boolean }} result
 * @param {boolean} [noChanges] the run changed no file
 */
function securityRanEntry(result, noChanges = false) {
  if (noChanges) return assure('security-review', 'skipped', 'the run changed no file')
  return result.ran ? assure('security-review', 'pass') : assure('security-review', 'unavailable', 'the security reviewer did not run')
}

const ASSURANCE_STATUSES = ['pass', 'fail', 'skipped', 'unavailable']
const STACK_TRUST_CHECK = 'stack-trust'

/**
 * Builds one assurance ledger entry.
 * `skipped` means the check does not apply to this run; `unavailable` means it applied and could not
 * run or did not return.
 * @param {string} check name of the check, such as "converge" or "review:security"
 * @param {'pass'|'fail'|'skipped'|'unavailable'} status
 * @param {string} [reason] why, or what a passing check left for a person
 * @returns {{ check: string, status: string, reason: string }}
 * @throws {Error} when the status is not one of the four
 */
function assure(check, status, reason = '') {
  if (!ASSURANCE_STATUSES.includes(status)) throw new Error(`assure: unknown status ${JSON.stringify(status)} for ${check}; use ${ASSURANCE_STATUSES.join(', ')}`)
  return { check: String(check), status, reason: String(reason || '') }
}

/**
 * Returns a new ledger with the entry added; an earlier entry for the same check is replaced in place.
 * @param {object[]} ledger
 * @param {{ check: string, status: string, reason: string }} entry
 * @returns {object[]}
 */
function assureInto(ledger, entry) {
  const list = Array.isArray(ledger) ? ledger : []
  return list.some((e) => e.check === entry.check) ? list.map((e) => (e.check === entry.check ? entry : e)) : [...list, entry]
}

/**
 * The one verdict of a run: an untrusted manifest blocks, any failed or unavailable check holds, else ship.
 * @param {object[]} ledger
 * @param {{ ship: string, hold: string, blocked: string }} names verdict names of the workflow
 * @returns {string}
 */
function assuranceVerdict(ledger, names) {
  const list = Array.isArray(ledger) ? ledger : []
  if (list.some((e) => e.check === STACK_TRUST_CHECK && e.status === 'fail')) return names.blocked
  return list.some((e) => e.status === 'fail' || e.status === 'unavailable') ? names.hold : names.ship
}

/**
 * Markdown table of the ledger, one row per entry, for the report.
 * @param {object[]} ledger
 * @returns {string}
 */
function assuranceTable(ledger) {
  const cell = (v) => String(v || '-').replace(/\|/g, '\\|').replace(/\s*\n\s*/g, ' ')
  const rows = (Array.isArray(ledger) ? ledger : []).map((e) => `| ${cell(e.check)} | ${cell(e.status)} | ${cell(e.reason)} |`)
  return ['| Check | Status | Reason |', '| --- | --- | --- |', ...rows].join('\n')
}

